/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20171011-4","meetingId":"h29-c-settlement","date":"2017年10月11日","dateIso":"2017-10-11","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を143件抜き出しています。","topics":[{"id":"topic-01","title":"◯鈴木（真）委員長 ただいまより、決算特別委員会を開会いたします。 それでは、平成２８年度品川区一般会計歳入歳出決算","agenda":"◯鈴木（真）委員長 ただいまより、決算特別委員会を開会いたします。 それでは、平成２８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"横山委員","kind":"質問","question":"おはようあります。私からは、１８１ページ、品川英語力向上推進プランについて、時間がありましたら１８３ページの家庭教育力向上支援についてをお伺いいたします。より正確に自分の気持ちを表現し、世の中をうつし出すことができる能力を身につけるために、国語も英語も語彙を増やしてほしいと考えていますが、区のお考えと現在の指導方法を教えてください。こちらは対話力と言えるかと思います。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"これから、今、品川区立学校教育要領の改訂を進めているところですけれども、今ご指摘がありました対話力というところにつきましては。実際にステップ、段階を追って自分の課題設定をする中で、実際にどのように取り組んでいくのか、その中で取り組もうと考えたことを。３番目にご質問がございましたスピーチ、受けとめて応じる会話の技術につきましてですけれども、全ての教科におきまして。","id":"exchange-001"},{"speaker":"横山委員","kind":"質問・要望","question":"対話力の部分、今まだ少し足りない部分があるということで、次の展開に期待しております。レジリエンスにつきましても、市民科などさまざまな教科の中で取り入れていただいて、品川区としてチャレンジができる子どもをぜひ育てていただきたいと考えています。教員の質の向上についてもお伺いいたします。品川の英語教育を進めていただくために、英語教員の質の向上を要望いたしますが、ご見解をお伺いします。","respondent":"熊谷指導課長","answer":"ちなみに今年度ですけれども、１０名が、取得に向けて研修を受講しています。ＪＴＥも含めて私どもで対応している英語科の専門教員、日本人の教員がおりますけれども、それも含めて研修を行っているところです。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"イングリッシュキャンプについてお伺いいたします。平成３０年９月より江東区にＴＯＫＹＯ ＧＬＯＢＡＬ ＧＡＴＥＷＡＹがオープンしますが、対象が５、６年生からということや、アクセスのしやすさ、日帰り利用もできる点を踏まえて、品川区では利用していくお考えなのかどうかお聞かせください。日本について、特に品川の魅力についてを英語で伝えることをぜひ実践していただきたいと考えております。","respondent":"熊谷指導課長","answer":"本区においては現在４年生で、ジュニア・イングリッシュキャンプを全校で行っているところです。実はＴＧＧにつきましては４年生でも可というふうに聞いておりますので、来年度検討をしていきたいと考えているところです。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"新しい施設であるＴＧＧができてまいりました。４年生も受け入れ可能ということですので、ぜひ、さまざまな形で実際に英語を勉強してきたことの成果を生かす場、そして成功体験を積む場というところの経験、ぜひそういった場を増やしていただけたらと考えています。こちらは要望です。平成２７年度に冊子ができたかと思うのですが、現在の状況や効果などが何かありましたらお願いいたします。","respondent":"品川庶務課長","answer":"家庭教育ブックですが、心身の発達等を考慮して３種類の家庭教育力チェックシート、家庭教育ブックを作成しております。チェックシートを見ていただいて、家庭教育ブックを見て、子育ての参考にしていただくというものです。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"１８８ページ、学校給食費、給食費無償化について、１７９ページ、市民科・各教科充実経費、がん教育について、１７８ページ、いじめ防止対策費から、ＳＮＳによる相談についてお伺いをいたします。品川区における、現在保護者が負担をしています１カ月の小・中学校の給食費をそれぞれ教えていただきたいと思います。徴収方法や、滞納者がいるのかどうかお伺いをいたします。","respondent":"有馬学務課長","answer":"これを基本的には食数、年間大体１９２日程度ということですので、それを月数で割ったもので月額の計算をしています。徴収方法につきましては、月毎にまとめて、今は入学のときに口座振替をお願いしておりまして、基本的には口座引き落としの形で対応しています。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"こういう方に対しては丁寧な対応をされていると思うのですが、ご家庭の事情があって、滞納されているケースも考えられますので、ご家庭の状況をよく確認をしていただきながらしっかり対応していただきたいと思います。品川区でも東京都の教育委員会から調査が来ていると思われるのですが、いかがでしょうか。このアンケートの内容を教えていただきたいと思います。","respondent":"有馬学務課長","answer":"内容につきましては、基本的に無償化、まず完全給食を実施していますかというところから入ってきています。これは、中学校のほうで完全給食の実施率というのがまだ８０％前後ということで、まずはこれを９０％に持っていこうということが背景にはあります。","id":"exchange-006"},{"speaker":"新妻委員","kind":"提案","question":"今回この調査は公明党が提案をいたしまして、文部科学省から発信をされているものです。しかし大きな財源が必要です。そのために今回この調査をして取り組んでいこうという方向性ですが、この給食費の無償化に関しての品川区の見解として、無償化ということに対してどう捉えているか、お伺いをしたいと思います。","respondent":"有馬学務課長","answer":"財源も相当かかりますので、これについては財源がしっかりつかないと難しいことではないかというふうに今のところ考えております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"確かにおっしゃるとおりだと思います。国、東京都、そして品川区、それぞれの自治体が協力し合いながら、給食費の無償化が進んでいくように注視をしていただきたいと思いますので、よろしくお願いいたします。続きまして、がん教育について伺います。若林委員とともに視察をさせていただきましたが、この日野学園で開催をされましたその経緯といきさつなど日野学園の状況を教えていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"保健体育として、健康な生活と疾病の予防ということを子どもたちに学ばせるために、どのような方法があるのか、これは品川区の教育会の体育部会の養護教諭を中心とした研究の中で、まずはやってみようという経緯の中で、日野学園で実施をしたような状況です。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"私も参加をさせていただいて、生徒たちが緊張しながら集まってくる姿から見せてもらいましたけれども、まずは開催できたことは大変よかったことだと考えています。そこで１つ確認をしたいのですが、学校の中には養護教諭、いわゆる保健室の先生がいらっしゃると思うのですが、この保健室の先生ががん教育にどのようにかかわったのか教えていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"その上で実際に外部講師をお呼びする際には、学校の狙いとして、今回の場合にはがんについて正しく理解をさせる、それから健康と命の大切さについて主体的に考えられるという２点を狙いとして取り組みました。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"非常になかなか子どもたちに理解をさせるのは難しいと思います。１点気になったことがありまして、この授業を受ける中で、生徒たちが筆記用具を持っていなかったのではないかなと思うのです。聞くだけで何も書きとどめることができなかったように見受けられたのですけれども、こういう授業の場合というのは、こういう形が普通なのか、たまたまそのときは筆記用具がなかったのか教えてください。","respondent":"大関教育総合支援センター長","answer":"その時間は、まずは講師の先生が用意してくださったパワーポイントの資料を集中して見るということで、筆記用具を持たせてしまうとメモをしてしまいがちですので、お話に集中できないということで意図的にその時間はメモをとらせず。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"私はもうその場でメモをしないと忘れてしまうので、メモがあったほうがいいなと思ったのですけれども、意図がよくわかりました。アンケートも非常に大事だと思います。今後、平成２９年度、これから品川区が目指すがん教育と今、次の流れが決まっているところがあれば教えていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"めったに経験できない、直接、病院の先生からがんについて詳しく聞くことができた、実際に自分の身内の方を想像しながら、その大変さを考えた生徒もおりましたし、あるいは生活習慣という部分が非常に大切だということを理解できた生徒もいました。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、日野学園で出されたアンケートも参考にしながら、他の学校で行うときにもまた生かしていただきたいと思います。最後に、ＳＮＳを活用したいじめに関する相談について伺いたいと思います。今、聞いているところでは３つの自治体でＬＩＮＥを活用し、またアプリにより相談を受け始めております。品川区における平成２８年度、昨年度のいじめ対策に関しての成果を教えていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"本区のいじめ対策、取り組みにつきましては、今年度で５年目となりますが、全校に子どもたちがいじめに関する相談をするための目安箱を設置し、さらにＨＥＡＲＴＳ「学校支援チーム」が直接子どもたちからの、あるいは保護者の方からの専用電話での相談を受けております。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"１７９ページの教育総合支援センター運営費にかかわって、ＬＧＢＴなど性的マイノリティに対する学校の取り組みについて、今回はカミングアウトとアウティングについて伺いたいと思います。私はこの先生への相談というのはつまりカミングアウトになるわけですけれども、これは子どもにとって悩みが深く、話しにくい苦しい気持ちがあると思うのですけれども、この点はいかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"はＬＧＢＴについて教員が理解をすること、そのことによって子どもたち、あるいは家庭から相談があったときに適切な対応をまずは受けとめることが重要と考えております。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"調査を見ますと、高校生までに自分がＬＧＢＴであることについて、多くが「誰にも話していない」か「ごく少数のみ」で、カミングアウトした人であっても相手は同級生が７割で担任の先生や保健の先生は１割ほどです。率直に伺いますけれども、なぜ先生にカミングアウトしにくいのか、子どもの苦しさの原因というのは一体何なのか、ご見解を伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"はいろいろな実態があるのだ、性に関する認識という部分は多様な考え方もあるのだという部分を、ＬＧＢＴのことに特化してということではないですが、まずはいろいろな人権ということで。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろと取り組みも始まっているかと思いますけれども、ぜひ進めていただきたいと考えています。それだけに自分へのカミングアウトについて悩んでいる子どもと、カミングアウトされた同級生や先生などへのサポートがそれぞれ必要だと思いますが、現状と今後の取り組みについて伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"実際に教員がどのように相談を受けるか、相談を受けた際にどのような点に注意するかという部分につきましては、人権教育プログラムを活用いたしまして、実際にＱ＆Ａの形で、このような問い合わせがあった場合はどういうふうに対応すべきかという部分も具体的に示しながら。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"これまで秘密にしていた自分の性のありようを表明する段階は２段階あると伺いました。１段階目は自分へのカミングアウト、２段階目は家族や友人など周囲へのカミングアウトです。どちらも大切なことであると思います。思春期を迎える小・中学校では、このＬＧＢＴのカミングアウトとアウティングについて、子どもたちが学校であらかじめ学ぶ機会が必要だと思いますけれども、現状についてお伺いします。","respondent":"大関教育総合支援センター長","answer":"その中の１つで、例えばＨＥＡＲＴＳも子どもから相談があればそういったことの相談を受けることもできますし、担任のほうに相談をするという形もあるかもしれませんが、学ぶ機会として、まずＬＧＢＴについてカミングアウトをしようというような教材等はございませんので。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"リーフレットもお配りになっているということですけれども、例えば品川区の男女共同参画センターのカウンセリング相談ですけれども、ここは小学生や中学生も相談してよいのか、あとはこの性別や同性愛に関する電話相談について、東京都のパンフレットにあるよりそいホットラインですけれども、学校から子どもへこの電話相談の周知はあるのかお伺いしたいと思います。","respondent":"島袋人権啓発課長、大関教育総合支援センター長","answer":"まだ子ども、１０代の方のご相談はないというふうに聞いております。ただ、私どもはそのような方々からご相談があった場合には関係機関との連携を含め、状況に応じて対応してまいりたいと考えているところです。自分の相談しやすい場所を選べるようになっておりますので、中には教育総合支援センターにあります教育相談室のカウンセラーに定期的にさまざまな悩みを相談してくる子どもがいますので、その中で、まだ具体的に自分の性というものを。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"ポスターの掲示やＡ４サイズのチラシや名刺サイズのものもありますので、学校の廊下や保健室など子どもたちが自由に見たり持って帰ったりできるようにしていただきたいと思いますけれども、この点はいかがでしょうか。それから学校図書における関連書籍の全校配置について、現在は４校だと伺っておりますけれども、全校に配置を広げていただきたいと思いますが、この点についてはいかがでしょうか。","respondent":"大関教育総合支援センター長、横山品川図書館長","answer":"よりそいホットラインにつきまして、相談窓口一覧の中に載せるかどうかにつきましては、さまざまな反応等もあろうかと思いますので、色々な状況等も考えながら検討していきたいと考えます。学校図書館の蔵書につきましても、各学校で選択をしているところでありますが、人権の中の１分野として資料を置かせていただくように配置してまいりたいと思います。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひいろいろ進めていただきたいと思います。これまで学校での学ぶ機会について、市民科の中で取り扱いを検討したいと答弁がありましたけれども、どこまで検討が進んだのかお伺いしたいと思います。このＮＰＯ法人ＲｅＢｉｔの研修も活用していただきたいと思いますが、この点はいかがでしょうか。","respondent":"大関教育総合支援センター長、島袋人権啓発課長","answer":"市民科の中では、先ほどご案内いたしましたとおり５年生の段階で「大切なこと」を活用してさまざまな考え方があるという部分は全校児童に投げかけております。は区職員、教職員も含めた研修ですが、ＬＧＢＴに関する理解を正しく浸透させることが大事かと考えております。","id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"私からは成果報告書の１７８ページ、生徒指導対策費、１８１ページ、マイスクール運営費の中でマイスクール八潮、マイスクール五反田について、１８９ページ、結核検診について伺いたいと思います。名称をクラブと部活動に分けている理由について伺います。次にこのクラブ・部活動はどのような方々が指導していて、そして１つのクラブまたは１つの部に対して何人体制で行われているのか伺います。","respondent":"有馬学務課長、大関教育総合支援センター長","answer":"それで基本的には、各学校での対応ですのでそれほど人数が多くありません。ばらばらですので、それほど１つの学校のクラブで何人もいるということではなくて、基本的には１つのクラブで１人いるというのが現状です。具体的に昨年度ですが、導入しているさまざまな学校の部の中で、延べ人数ですけれども３７人の方に品川区の子どもたちのためにご協力をいただいております。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"先ほど質問をいたしました、クラブと部活動の違いについてお願いします。","respondent":"大関教育総合支援センター長","answer":"大変失礼いたしました。小学生の場合にはクラブ活動として行っております。中学生は部活動として、これは学習を終えた後の放課後等に行っている一般的な部活動をイメージしていただければと思います。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"これは指導員の数が減ってしまったという事なのか、決算額が減ってしまった原因について伺いたいと思います。それから、外部指導員の方が３７名ということなのですけれども、１人当たりの費用は大体どのくらいなのですか。時給換算にするとどのくらいの金額になるのかも、合わせて伺いたいと思います。","respondent":"有馬学務課長、大関教育総合支援センター長","answer":"単価は外部指導員につきましては１回４,０００円ということで対応をしています。先ほど３７人と申し上げましたのは運動系の部活動でございまして、それ以外に文化系の部活動では延べ３４人の方にご協力いただいているところです。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"１回につき約４,０００円ということで、例えば夏休みなどの部活動で１回指導すると４,０００円という形になるのでしょうか。時間に換算すると、ちょっとそれではどうかなとは思うのですけれども、その辺について伺いたいと思います。","respondent":"有馬学務課長","answer":"基本的にはこの外部指導員について、現状の取り決めでは１回４,０００円ですので、２時間の場合もありますし４時間の場合もあるとは思いますけれども、その全額で対応しています。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"子どもたちのためにぜひよろしくお願いいたします。次にクラブまたは部活動の指導について伺いたいと思います。都教育委員会で２０１７年６月に２０１６年度において都内の公立小・中・高等３３校の教職員、３４人が児童・生徒に体罰を加えたとする調査結果が公表されました。そこで今年度、本区において部活動や授業中などにこうした体罰事例があったのかを伺いたいと思います。","respondent":"熊谷指導課長","answer":"昨年度の体罰の実態把握の調査結果ですけれども、品川区におきましては０件です。ですので、全く体罰にあたる案件はございませんでした。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問・要望","question":"こうしたことが他自治体で起こっている中で、品川区はないということで安心しました。ただ、こうした事例はいつ起こるかわかりませんので、しっかりと子どもたちの健全育成に取り組んでいただきたいと思います。そこで質問いたしますが、もしこうした動画のような証拠がない場合、教職員から、生徒からいじめられていると言われた場合、どのような対応をされているのかお伺いします。","respondent":"大関教育総合支援センター長","answer":"現段階におきまして、教員から生徒にいじめられているという相談は受けてございませんが、万が一あった場合に、考え方といたしまして、まずその教員の指導力がどういう状況なのか。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"ここで教育委員会に伺いたいと思うのですけれども、今回の教職員の対応というものはこれが正しかったのか、それとも他の対応があったのか、本区では、こういう事例が現状ないと思うのですけれども、もしこういうことが起こった場合に、教師としてこういう対応が正しかったのかを改めて伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"その状況をそのままにしておくのは適切ではないと思いますので、当然、そこに至る前の段階で、学校全体でまず校内体制の工夫等をして、そういったいわゆる学級崩壊のような形にならないよう取り組んでいきますし、教育委員会としても指導・支援してまいります。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ学校に関してはＩＣＴ化も進んでおりましてタブレット端末も配布されていると思います。そういったところもきちんと丁寧に進めていただきたいと思います。時間がなくなりましたので、１８９ページの結核検診について質問いたします。その二次検診についてですが、例えば保健センター、医師会検査センターを利用してＱＦＴ検査の採血を集約して実施してみてはどうですか、区のお考えをお聞かせください。","respondent":"有馬学務課長","answer":"基本的には医師会が指定した日、数日間はとっているのですけれども、その決められた日になかなか行かれないということもありますし、今委員が言われたとおり、夏休み中に本国に１回帰ってしまうなど、やはり言葉の壁なども含めて、いろいろ背景はあると思います。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"私は１７８ページ、教育指導費についてお伺いいたします。学校選択制についてメリット・デメリットをお聞かせください。そして現在、品川区は学校選択制を実施して相当期間が経っています。実際に著しい学校間格差、子どもの児童数の格差が広がってきた。これに対してどう思われるかもお聞かせください。","respondent":"有馬学務課長","answer":"平成２７年度から平成２９年度を見ますと、全学年合わせて６クラスしかない学校がこの２年間で６校だったものが３校に減ってきているというようなこともありますし、それらの学校ではもう既にその学年において。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問・要望","question":"それでいいのですか。品川区の教育ってそんなものなのですか。やはりみんな平等で、どこへ行っても品川区の教育は大丈夫だということが、私はやはり求められているのではないかと思うのです。学校選択、自由ですから皆さんに任せている。どこの学校へ行っても安心で安全だという気持ちを持たせるということが、私は教育委員会に求められていると思いますが、もう一度ご見解をお聞かせください。","respondent":"有馬学務課長","answer":"それから実際に現在通学区域の学校に通っている子どもというのは、大体今で言うと、平成２９年度は７７％ぐらいを占めているというような、そういった実態もあるです。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、特色とおっしゃいました。でも現実論、教員の皆さんにそこまで求められるかと、各学校平等に、それは難しいかもしれない。では学校選択制とうたっていて、全員が入れるのですかということですよ。これでは学校選択制って言わないほうがいいではないですか。一部選択制という名前に変えるべきですよ。ではどうするのですか。これも大きな問題ではないでしょうか。その辺についてご見解をお聞かせください。","respondent":"有馬学務課長","answer":"目の前の学校に行けないではないかというようなところの問題は指摘はいただいておりますので、学事制度審議会の中でもその辺の問題については検討はしていただいているところです。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"品川区ではさまざまな長期計画、またいろいろ事業の見直しを進めています。ですけれども、ではこれは完全に見誤った、自分たちの考えていた構想と違っていたということなのでしょうか。だったら早く私は修正すべきだと思います。現実、違うのですよ。ですから、その辺は考えてほしい。地域の町会も困っています。でも現実こういうふうな状況に対して、どのようにお考えでしょうか。お答えください。","respondent":"有馬学務課長","answer":"ですので、各学校が切磋琢磨しながら、今年のパンフレットにも出しましたけれども、３.１１以降の防災の面、生徒の安全の面ですとか、今学校は地域とともにある学校を目指していますよと、地域との結びつきも考えながら学校を選択してくださいというような文面を入れて、現状。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"それはわかりますが、先ほど申し上げたのですが、やはり品川区がこれだけ子どもたちの指導と教育として、これだけの事業費を使っているならば、根本は先生という形になるのだと思うのですが、先生がしょっちゅう異動してしまう、３年たったら異動してしまうので、また新しく構築しなければいけない。そういうご苦労もわかります。ではその学校はどうなったのですか。最後に一言お願いいたします。","respondent":"有馬学務課長、熊谷指導課長","answer":"その意識の高まりによって、それが子どもたちにも伝わっていっているということになっていると思います。ということで、教員の意識が子どもにも伝わっているということではないかというふうに考えております。まさに地域の中で、地域の方々とともに子どもを育てていくという取り組みが始まったところですので、次年度の全校展開、そこでさらに地域とともにというキーワードを大切に学校づくりをしてまいりたいと思います。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"１８８ページ、２項学校教育費３目学校給食費、給食食材放射性物質検査費、１８６ページ、１目学校管理費、校庭人工芝生化と監査報告について、１７８ページ、１項教育総務費３目教育指導費、教職員人材育成経費、いじめ防止対策費、いじめ等防止プログラム経費について伺います。給食食材放射性物質検査費について伺います。来年度予算について現状ではどのような検討がされているのかお知らせください。","respondent":"有馬学務課長","answer":"給食食材の放射性物質の検査につきましてですが、次年度につきましてはまだこれからということで、予算編成についてこれから検討していく形になります。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"リスクがある限り検査を継続することが必要であり、検出せずを確認することが重要です。その確認を行っているからこそ、もし検出されたときには因果関係が特定できます。通常、監査で指摘を受け、措置報告を受けるのは、監査で指摘を受けた学校だと思いますが、その措置報告のとおり、指摘された点が改善されたというのはどこが確認をしているのでしょうか。","respondent":"品川庶務課長","answer":"指摘が出てきた時点におきましては、教育委員会として校長連絡会等で指導をしまして、そこで学校等に指示を出しています。それから各学校につきましては、指導主事等が訪問をしています。その訪問の時点で直接理科室を見て確認をするというような業務を行っております。","id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"校長連絡会に指示を出して、その後職員などにより全校の状況の確認をとることができたということですか。","respondent":"品川庶務課長、大関教育総合支援センター長","answer":"校長連絡会等で指示をしまして、校長から各学校の理科主任という理科の先生がいるのですけれども、そこに指示が行き、そして理科準備室のほうを再度点検を行い、整理をしているところです。教育委員が定期的に訪問をした際にも、鍵もあけて実際にグラム数をはかって正しく記録されているか、そういった部分の確認もして、徹底していますので、ご安心ください。","id":"exchange-035"},{"speaker":"田中委員","kind":"確認","question":"今の答弁ではしっかり確認されていたということなのですけれども、ではなぜ２０１６年にまた毒物・劇物管理で監査報告が出てしまったのかということを聞きたいです。２０１５年のときにきちんと監査報告が他の学校でも共有されて確認されるべきだったと思いますが、そのことを伺います。","respondent":"品川庶務課長","answer":"こういう点につきましては、教育委員会としても徹底して指導をしていきたいと、このように考えております。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"本当にぜひ再発防止を徹底してください。時間がないので次に行きます。いじめ防止対策費に含まれるＣＡＰについて伺います。この事業をこれからも継続してほしいという立場で質問をします。子どもたちと大人に向けたＣＡＰプログラムの導入の目的をどのように区は捉えているのか伺います。","respondent":"大関教育総合支援センター長","answer":"これはやはり子どもたちのいじめ、虐待、性被害に遭わないための対処法の１つとしてこれまでも取り組んできたところです。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"先日、大人向けＣＡＰに参加しました。ＣＡＰの授業である権利教育は大変すばらしいものです。しかし、このＣＡＰの授業が２０１６年から縮小されていると伺いました。３年生と５年生で行っていた授業が３年生だけになったということです。どのような判断でＣＡＰの授業が縮小となり、いつ決定がされたのでしょうか。ＣＡＰの縮小について子どもたちや保護者に意見を聞く機会はあったのか伺います。","respondent":"大関教育総合支援センター長","answer":"そして平成１８年度から３年生と５年生を対象に行ってまいりました。その間、いじめ対応につきまして学校の取り組みもさまざま変化してきてあります。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"普通の授業もそうですが、何度も復習することにより身につきます。いじめ予防の実効性を高めるには、繰り返し授業を実施する必要があると考えます。子どもたちが子どもの権利について学び、自らが命を守る方法を学ぶことができる大切な授業です。ＣＡＰの授業の継続を望みますが、見解を伺います。子どもたちの命を守っていくためにも、ＣＡＰプログラムの今後の方針をお知らせください。","respondent":"大関教育総合支援センター長","answer":"子どもたちの発達段階も踏まえながら、そのとき何が最も効果的であるかを十分学校と共通理解を図りながら、今後もＣＡＰにつきましては適切な学年で実施してまいりたいと考えます。","id":"exchange-039"},{"speaker":"田中委員","kind":"確認","question":"ぜひ継続実施をお願いいたします。では、次に行きます。発達障害に対する教員の学びについて伺います。発達障害と言っても個々に症状が違います。発達障害は一見わかりづらく、周囲が気づきにくい障害です。確か以前の答弁では、教員への発達障害の研修を行っていると伺っていました。しかし、教員等の研修計画を確認しましたが、普通学級の教員向け研修において読み取ることができませんでした。","respondent":"大関教育総合支援センター長","answer":"そのほか特別支援教育研修会といたしまして、各校の特別支援コーディネーターを複数指名していますが、そちらが参加する内容を研修会でも扱い、全ての学校において校内研修会として共通理解を図るように伝達講習会を求めているところです。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもたちの近くで接している先生たちには、特に発達障害への理解を深め、それぞれに合った対応で接し、発達障害を持つ子どもが孤立せずに済み、多様性を認め合える環境をつくってほしいです。しかし教員への研修計画には載っていませんでした。発達障害、そしてＬＧＢＴなど多様性への理解が広がる、学べる場の提供を区へ強く要望したいのですが、区の見解を伺います。","respondent":"大関教育総合支援センター長","answer":"各職層別において、先ほど申し上げました校長研修会、副校長研修会、あるいは生活指導主任会、そういったものを通じてＬＧＢＴについて相談のあった場合に適切な対応をするよう全ての学校に対して求めている、そのように扱ってあります。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"その校長研修会でＬＧＢＴや発達障害について学んだ後に、きちんと教員へその研修内容が受け継がれているのかなども伺いたいと思います。多様性を認め合える学びの場の提供というのは大事なものです。今後のためにもぜひお聞かせください。","respondent":"大関教育総合支援センター長","answer":"リーフレットとして東京都教育委員会から出されたものを全校に配布しましたので、必ず発達障害等に対する、発達の偏りのある子どもへの対応に関する内容も、校内研修会を行いましたし、あるいはＬＧＢＴ等に関しての扱い等についても管理職より全教員に対して周知徹底しています。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"次に行きます。校庭の人工芝生化について伺います。人工芝生化の目的は転倒時のかすり傷の軽減や水はけや汚れにくさ、近隣への砂ぼこりの抑制などと伺っています。人工芝生化に伴いこれらの企画を再び行うことは少し難しくなるのかなと考えられますが、今回の人工芝生化は学校や学校に通う子どもたち、そして地域の要望を受け実現したものなのでしょうか。どのような経緯から人工芝生化に至ったのか伺います。","respondent":"品川庶務課長","answer":"そういった点から人工芝にしていくという計画になっております。それから静電気等のお話がありましたが、水等をまいて対応するというようなことも対応策としています。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"成果報告書、教育指導費、１７９ページ、まちの人々に学ぶ授業経費、１８３ページ、社会教育費の中の子ども地域活動支援経費、１８５ページ、学校環境整備事業について質問をします。初めに１８３ページ、子ども地域活動支援経費に関連した質問をします。町会等行事参加カードについて、その事業についてご質問をさせていただきたいと思います。よろしくお願いします。","respondent":"品川庶務課長","answer":"行事参加カード事業ですが、今年から、委員お話しのように１年生から６年生まで全てカードを配布しまして、事業を進めているところです。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"やはりなかなかこの制度は、非常にいい部分もあると思うのですけれども、例えば、荏原第四地区には１４町会あるのですが、その町会に関しても、児童が行事参加カードを持参して来た町会というのは１町会程度ということをお聞きしております。こういうカードをつくったのですから、改めて学校の先生のほうからも、保護者に対して啓発もやっていただきたいと思います。そのことについてお聞かせください。","respondent":"品川庶務課長","answer":"この町会スタンプカードを始めた当時から、ほぼ毎年のように１３地区の町会長会議に参加いたしまして、毎年内容変更がありましたので、その説明ということでお話をしているものです。","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、区政協力員の方々、そして地域の方と話をしていただいて、継続するのか、もしくはやめるのかについて検討していただきたいと思います。続きまして１７９ページ、まちの人々に学ぶ事業経費のご質問をさせていただきたいと考えています。市民科についてご質問します。これは社会保険労務士にご協力をいただき市民科の授業を平成２８年度に計３回行っていると思います。","respondent":"大関教育総合支援センター長","answer":"冒頭ご紹介いただきました社労士団体の方等の協力を得て、どのように増やしていけるかにつきましては、各学校の状況も踏まえながら関係団体の方からもアドバイスをいただきながら、今後検討してまいりたいと思います。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして１８５ページ、学校環境整備事業に関連した質問をします。そういった中で学校公開があるときに来校される方々、そして子どもたちのためにもやはりこれは生き物が生息しているわけですから、透明度のある池を、また、池だけではなく、植物にしても剪定にしてもそうだと思うのですけれども、学校における、近隣に対しての配慮というか取り組みを改めてお聞きしたいと思います。","respondent":"品川庶務課長","answer":"ですので、こういう近隣に対するスタンスとしては、とにかくお声を聞いて対応のできるところは全てやっていく、とにかく前向きな姿勢で取り組んでいっているというような考え方です。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問","question":"私からは１７９ページ、プラン２１推進事業に関連いたしまして、まず１点目がプログラミング教育について伺います。２点目は品川区の教育ということで、ＳＤＧｓと教育について伺ってまいります。時間があれば１８２ページ、人権尊重教育推進経費に関連いたしまして、アール・ブリュット展の子どもたちの鑑賞について伺います。一方で教育現場では２世代ぐらいおくれた議論がされています。","respondent":"大関教育総合支援センター長","answer":"今後につきましてもそのような積み重ね、情報収集も含めて、例えば各教科以外に本区独自の教科である市民科の中で、プログラミング教育は何年生でどのような単元を全校で行うべきかなどについても現在検討を進めているところです。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"当然進められているというお話がありまして、Ｐｅｐｐｅｒを活用するという話は初めて聞きましたけれども、今やっているのですか。非常に興味深いなと思いました。率直なお考えだと思うのですけれども、そこで伺いたいのが、先ほど理科の例はあったのですが、国語、算数および理科の教員がプログラミング教育を授業に取り入れることについて、今どのようにお考えになって、どのように対応をされているのか。","respondent":"大関教育総合支援センター長","answer":"これは全ての学校でもう既に取り組み始めているところですので、実際に今やっている内容が直接つながっていくよう各教科検討部会の中で教育内容、単元を考える際に、プログラミング教育という視点も今後の研究の１つのテーマになっていこうかと考えています。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"」ちなみに土曜日にまた再放送があるみたいです。これは本当に、いわゆる保護者、区民、議会も含めてなのでしょうけれども、これは今、教育において激変が起きているということを理解をして、またこういうことについて心を寄せていかなければいけない、しっかりと見守っていかなければいけないということは、今後もまた議会質問等を通して確認をさせていただきたいと考えています。","respondent":"大関教育総合支援センター長","answer":"そういった取り組みを、その学校の特に例えば環境学習に力を入れる学校であったり、あるいは国際貢献に力を入れる学校であれば、そのような国際的な経験をなさった方を講師に招いて、特色ある教育活動として行っていく、そういったことも可能かと思いますので。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"国に言われなくても、おそらく品川区は既にこういった環境教育であるとか、またこういう持続可能な開発目標につながる教育というのは行われていると思いますけれども、今後またそれが２０２０年度から方針として出てくるというところで、ぜひ拡充をしていただきたいと思うのですが、そこでこのＳＤＧｓを推進する国の方針の中に、ちょっとまたこれがややこしいのですが、ＥＳＤという。","respondent":"大関教育総合支援センター長","answer":"学校のほうで申請がある場合には、教育委員会としても応援してまいりたいと考えております。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"最後に、関連して人権尊重教育推進経費というところで、子どもたちのアール・ブリュット展の鑑賞について伺います。本当にすばらしかったです。それで伺いたいのが、予算特別委員会のときに、学校のほうにぜひ声をかけてください、子どもたちに鑑賞の機会をお願いしますということを申し上げましたら、教育次長のご答弁では、「なるべく早い時期に情報提供をしていく」と、各学校にですね。","respondent":"大関教育総合支援センター長","answer":"教育委員会といたしましてもアール・ブリュット展については話題とさせていただきまして、日野学園の例えば美術部の生徒が今週部活動の一環として見に行くというような情報を得ておりますので、またその後の感想等については聞きたいと考えています。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"１８３ページ、図書館経費、１８５ページ、御殿山小学校西側敷地図書館建設工事費負担金および大崎図書館について伺います。解体後の跡地活用について、区は補助２９号線とする考えなのかどうか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"解体に向けてというところで今準備の状況に入っているところです。その後ですけれども、道路の関係で協力をと、東京都のほうからそういったお話もあります。そういったところに活用できるかについては考えているといったところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"老朽化は移転の理由になりません。ならば建てかえればいいのではないのですか。ゆたか図書館は老朽化を理由に改修、大崎図書館は改修も建てかえられもせずに移転・廃館とはどう考えてもおかしいのではないでしょうか。伺います。この判断、建てかえでなく移転が地域のためになると判断したのはどこの部署ですか。建てかえは技術的に不可能なのですか。そういう検証をしたのですかどうか伺いたいと思います。","respondent":"横山品川図書館長","answer":"大崎図書館の移転につきましては、以前に文教委員会でご説明させていただきましたとおり、老朽化がひどく、またビジネス支援図書館としても機能しておりました大崎図書館につきましては、産業支援交流施設ＳＨＩＰの開設によりまして、多くの機能がそちらのほうに移りました。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"総合的に判断したとか、区全体というのは曖昧過ぎるのです。どこで判断したのか、誰の責任で判断したのか、しっかりとお答えください。それと、私が聞いたのは、今、建てかえは可能だという意味なのですか。ちょっとわからなかったのです。技術的に建てかえは不可能なのですか、また、そういう検証をしっかりしたのですかということを伺ったので、お答えください。","respondent":"横山品川図書館長","answer":"１つ１つの補修や改修につきましては個別で判断をしておりますので、総合的に建てかえは不可能ということでの検証はしておりません。１つ１つの工事を積み上げた結果、移転のほうが合理的だと判断しています。繰り返しになりますが、決定は区全体でしています。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"建てかえ、現地ですればいいのではないかという話なんです。今回の区の勝手な総合的な判断というのは、松原さんの思いも裏切る行為になるのではないですか。伺いたいと思います。裏切りではないのですか。伺います。伺いたいと思います。それと、現地での建てかえできるというならば、移転ではなく現地での建てかえを検討すべきだと思いますけれども、いかがでしょうか。","respondent":"横山品川図書館長","answer":"そういう意味では現地での建てかえというのを検討するのも１つの方策ではありますが、先ほど申しましたように、大崎図書館にはビジネス支援の機能もございまして、そちらにつきましては、これも先ほどご説明させていただきましたが。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"くむと言うのであれば現地での建てかえを強く求めたいと思います。今からでも間に合います。ぜひ判断を変えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"本多委員","kind":"質問・要望","question":"関連で大崎図書館について伺います。今の現在の場所に残してほしいという、それは気持ちは気持ちでわかります。積み上げてきたものを、もっと正面から見てほしいと思います。どうなのですかと言われるので、その方たちはやはり御殿山は遠くて困る。その区の考え方と、あと移転、図書館が移転になりますというもともとの経緯とを説明するのが、区政運営に求められている事だと思うのです。","respondent":"横山品川図書館長","answer":"今ご質問いただきました新しい大崎図書館の展開につきましては、現大崎図書館が１,３２５平米であるところ、今度新しい図書館は１,５００平米、芳水小学校の分館は６００平米、大崎駅西口に取次施設については１５０平米で、施設的にも充実し。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問","question":"私からは品川図書館運営費のうち、１８４ページ、デジタルサイネージ導入費、１８１ページの品川英語力向上推進プラン、１８２ページ、帰国児童・生徒等支援費についてお伺いをいたします。デジタルサイネージについてなのですけれども、私も直接見せていただきました。そして、なぜ品川図書館に設置したのかという理由をお知らせください。","respondent":"横山品川図書館長","answer":"デジタルサイネージにつきましてご質問いただきました。導入の目的につきましては、利用者の利便性の向上、また図書館情報の発信の媒体を新しく探しておりましたところから、試験的に導入させていただきました。品川図書館での検証を経て、各館に導入を拡充させていく予定です。","id":"exchange-059"},{"speaker":"筒井委員","kind":"質問・要望","question":"例えば、お知らせページなどは新しく更新されると思うのですけれども、そうしたお知らせのページを強調するなど、継続的に利用していただくような取り組みをぜひしていただきたいのですけれども、いかがお考えでしょうか。","respondent":"横山品川図書館長","answer":"今、お知らせにつきましては、使い勝手について改良の余地がございまして、更新が月に２回しかできないような制約がありますので、これをリアルタイムに更新できるような形にできないかというようなところで改良を重ねてまいるつもりでおります。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"ぜひともそうした工夫、仕組みづくり、よろしくお願い申し上げます。款をまたがってしまうかもしれませんが、このデジタルサイネージを今は区役所の庁舎と品川図書館に設置していると思いますけれども、今後拡大のご予定というのはあるのでしょうか。","respondent":"横山品川図書館長、中元広報広聴課長","answer":"品川図書館での検証と改良の状況を見まして、各図書館に拡充していきたいと考えています。来年１月末から２月頭を目処に本庁舎のほうの３階のあたりに置かせていただこうということで、今計画、準備を進めているところです。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問・要望","question":"続けて、品川英語力向上推進プランについてなのですけれども、１年生から６年生の英語科、そしてイングリッシュキャンプ、外国人英語講師など、相当品川区も力を入れられているのですけれども、これだけ英語に力を入れられていますが、その成果、いわゆる数字が客観的にはっきりあらわれる学力試験、英語のペーパーテストの成績というのは、成績向上が見られているのでしょうか。","respondent":"熊谷指導課長","answer":"平成１８年度から１年生からの英語教育を行ってまいりました。その成果と申しますと、１年生からやってきた子どもが９年生になった平成２８年１２月１日、昨年度、文部科学省が英語教育実施状況調査というものを行いました。","id":"exchange-062"},{"speaker":"筒井委員","kind":"質問","question":"２３区ではどのぐらいの順位なのかということと、またこの英語力向上推進プランに当たって課題もあるかと思うのですけれども、課題は何かということと、あわせてその対策としてどういったことをお考えでしょうか。","respondent":"熊谷指導課長","answer":"課題なのですけれども、そうは言ってもペーパーだけでははかれないものというのがあります。ですので、いわゆるコミュニケーションの部分、対話の部分、そういったところを児童・生徒に今後一層つけていきたいというふうに考えているところです。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問・要望","question":"帰国児童・生徒等支援費なのですけれども、全体の児童・生徒数のうち、何人がそうした帰国児童・生徒なのか、その割合とどこの国から来られているのが多いのかということと、その支援内容、そして英語圏から来た児童・生徒さんは英語力が当然あると考えておりますけれども、品川区の英語教育において、一般の生徒との兼ね合いというか、関係性というのはどうなっているのでしょうかお伺いいたします。","respondent":"大関教育総合支援センター長","answer":"さまざまな国から、ロシアですとかモンゴルですとか、いろいろな国から品川には子どもたちが来ている状況ですので、まずは日常生活において日本語で対応ができるよう指導をしています。","id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は１７８ページ、３目教育指導費の品川学校支援チーム経費に関連して、品川学校支援チーム「ＨＥＡＲＴＳ」についてと、１８８ページの３目学校給食費に関連して、学校の食物アレルギー対応についてと、１８９ページの４目学校保健費に関連して、性教育についてお尋ねいたします。不登校などにＨＥＡＲＴＳがかかわったことによる具体的な成果などはいかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"例えば不登校の子どもへの対応においてですが、朝起きることがなかなか難しい、学校の時間に間に合うように登校できない、いわゆる昼夜逆転してしまって生活リズムが整っていない、そういった中学生のケースにおいて、ＨＥＡＲＴＳが介入してまいりますと。","id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問","question":"いろいろと大変だと思いますが、事務事業概要によればＨＥＡＲＴＳはスクールソーシャルワーカーが４名、教育心理指導員が２名、学校生活指導専門員が１名の体制のようですが、例えば臨床発達心理士だとか、小学校の元教諭などの職種の方もいらっしゃるのでしょうか。お答えをお願いします。","respondent":"大関教育総合支援センター長","answer":"教員経験者につきましては、ＨＥＡＲＴＳの中で直接は雇用はしてございませんが、学校担当の指導主事がおりますので、指導主事とＨＥＡＲＴＳで連携して対応しております。","id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私も実際にクリニックで不登校の子にかかわっているのですが、この問題に関しては今後も質問を続けたいと思います。次に学校のアレルギー対応についてお尋ねします。この間一貫して取り上げている学校における食物アレルギー対応について、平成２８年度の小学校・中学校・義務教育学校における食物アレルギーの事故ないしニアミスの事例はあったのでしょうか。お示しください。","respondent":"有馬学務課長","answer":"平成２８年度の学校のアレルギー対応のヒヤリハット、ニアミスの件ですけれども、昨年度は小学校で３件、中学校で１件、合計４件発生しております。きちんと配膳はしたのだけれどもおかわりのときに間違えて配膳してしまったとかいう例もございました。","id":"exchange-067"},{"speaker":"鈴木（博）委員","kind":"質問","question":"むしろ負荷試験をやって、少量でも少しずつ食べさせて体をならしたほうがいい。したがって、そのように今背景が、バックグラウンドが変わってきているので、しっかりエピペンを常備していつでも打てる体制にしながら、負荷試験で食べられるものに関しては少しずつでも生徒に食べさせるというように、いずれ方向転換していくと思うのですが、それに対して今、教育委員会の認識というのはいかがでしょうか。","respondent":"有馬学務課長","answer":"そういった点からも、いわゆる少しずつ食べさせるというようなことはまず家庭でやっていただくことを第一義的な対応とし、今までどおり取り組んで、安全第一をまず考えていきたいということを現時点では考えているところです。","id":"exchange-068"},{"speaker":"鈴木（博）委員","kind":"質問","question":"性感染症予防教育についてお尋ねします。第三回定例会の一般質問で教育次長より本区における性教育の実施学年と学習内容についてご答弁をいただきました。性教育の重要性について区はどのように考えているか、再度ご答弁をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"新しい学習指導要領においても、ＡＩＤＳ及び性感染症の予防について扱うことがしっかり明示されておりますので、引き続き対応してまいります。","id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"意見","question":"平成２０年の中教審答申では、心身の成長・発達に対しての正しい理解という項目があり、ここから引用です。「しかし、近年、性情報の氾濫など、子どもたちを取り巻く社会環境が大きく変化している。教育次長は先の答弁で、性感染症予防教育として９年生を対象に性感染症とその予防について、梅毒をはじめとする主な性感染症の特徴や予防の方法、具体的な内容を３時限学ぶと答弁されました。","respondent":"大関教育総合支援センター長","answer":"７年生になりましたら具体的に思春期状態での生殖機能については個別具体的な内容を集団で指導する場合、あるいは男子生徒、女子生徒を分けて指導する場合など、適切に対応をしながら６時間行っております。","id":"exchange-070"},{"speaker":"鈴木（博）委員","kind":"提案","question":"養護教諭の研修として日本学校保健会等の主催する公開講座への参加をしていると先にご答弁がありました。このような公益団体が主催する研修への参加もご検討すべきではないかということはご提案します。梅毒の流行という状況の中で、性感染症予防教育の重要性はますます高まっています。今後も一層の性感染症予防、不幸な子どもをなくすための予防に関する教育の充実をお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"木村委員","kind":"質問","question":"私からは１７８ページの下から１３行目、いじめ防止対策費４,０１８万円余から質問します。いつの時代も学校でのいじめはなくなりません。お聞きいたしますけれども、陰湿ないじめとは、例えば無視をし口をきかない、また仲間外れにするなどがありますけれども、これはごく一部だろうと思いますが、それ以外の陰湿ないじめとはどのようなことがあるかお聞かせください。","respondent":"大関教育総合支援センター長","answer":"陰湿ないじめにはどのような内容が考えられるか、そしていじめの４層構造について、いじめる側の子ども、いじめられる側の子ども、その対応について学校がどのように対応すべきかというお問い合わせであったかと認識しております。","id":"exchange-072"},{"speaker":"木村委員","kind":"質問・要望","question":"お願いをしたいと思います。次に１８０ページの上から６行目にありますけれども、特色ある教育活動経費５,５０９万円余についてお聞きいたします。そして各学校において何らかの取り組みをしておりますけれども、各学校の生徒たちが話し合って、学校ぐるみでそういうものを決めるのでしょうか。","respondent":"熊谷指導課長","answer":"子どもたちの意見をもとにこういった事業が行われているかですが、そういった部分もあろうかと思いますけれども、校長が我が校においてこういった形で、こういった人物に子どもたちを育てたいといった思いが特色ある教育活動経費として申請されてきているところです。","id":"exchange-073"},{"speaker":"木村委員","kind":"質問","question":"学校ぐるみで決めると思っていたのですけれども、校長先生が決めるということですけれども、それでは校長先生の趣味や考え方に偏ってしまうおそれがあろうかと思いますけれども、それでいいのでしょうか。生徒の声や意見が反映されないのか、そしてまた校長が変わるたびに事業内容も変わっていくのか、例えば１年毎に変わっていくのかについてもお聞きいたします。","respondent":"熊谷指導課長","answer":"ただ、品川コミュニティ・スクールができまして、校区教育協働委員会でどういうふうに子どもたちを我が校で育てていこうかということについて校長や地域の方も一緒になって考えていく中で、体験授業、体験学習。","id":"exchange-074"},{"speaker":"木村委員","kind":"質問","question":"しながわドリームジョブですが、子どもたちが将来の自分と出会えるかもしれない大変よい事業だと思っています。そして、生徒に夢を見せるわけですから、インパクトのある講師探しをしなければなりませんが、どのようにして選考していくのか、これもお聞かせください。そして、体験授業が小学校１校となっていますけれども、どのような授業を行っているのか、これもお聞かせください。","respondent":"熊谷指導課長","answer":"最後のご質問で、体験授業の小学校１校ではどのような授業を行ったのかというお尋ねだと思いますけれども、これは浜川小学校で行った授業でございまして、今年度も実施しております。ジャズコンサートと陸上競技体験です。","id":"exchange-075"},{"speaker":"木村委員","kind":"意見","question":"この田植え体験学習ですけれども、田植え体験学習は立会小学校で取り組んでおりますけれども、何のための田植えの体験なのか、生徒には何を学んでほしいのか、また体験後に生徒にこのようなところが変わったなという変化があったかどうかについてお聞かせください。","respondent":"大関教育総合支援センター長","answer":"５年生の社会科で農業について学ぶ学習と結びつけて、実際に毎年５年生が立会小学校では農家の方と交流しながら実際の活動を行うことによって、栽培に関する体験を通して農業への理解を高め、例えば給食の残飯率が低くなるというような成果もあります。","id":"exchange-076"},{"speaker":"塚本委員","kind":"質問","question":"私からは１７９ページ、教育総合支援センター運営費と、１８２ページ特別支援教育費に関連して特別支援教室等に絡めての話と、あとは１８０ページの学校地域連携推進経費、いわゆるコミュニティ・スクールについてお伺いしたいと思います。その原因としてどこに、どういうことがあると考えておりますでしょうか。お聞かせください。","respondent":"大関教育総合支援センター長","answer":"したがいまして、各小学校に特別支援教室を配置して対応したり、あるいは学習支援員を学校に一定の時間ごとに配置いたしまして、あとは校内の中で工夫をして、必要な学級に学習支援員を配置していただくというような対応を進めているところです。","id":"exchange-077"},{"speaker":"塚本委員","kind":"意見","question":"教員・担任の指導力というところをまず一義的な対応として言われることが多かったかなと思いますけれども、その意味でまずこの教員・担任の指導力強化、こういったことについてどういった対策が今されているかお聞かせください。","respondent":"大関教育総合支援センター長","answer":"今後とも研修とともに充実してまいりたいと考えております。","id":"exchange-078"},{"speaker":"塚本委員","kind":"質問・要望","question":"それと、教員の指導力というところと、もう１つは先ほどご答弁もいただいた特別支援教室がこの平成２８年度から全国的に展開をされておりまして、その成果と言うのですか、通級指導が各学校で受けられるようになったということで、学級運営等を阻害する問題行動等への効果というか、解決に至っているような実態というか。","respondent":"大関教育総合支援センター長","answer":"増えているのは、後期課程においてでして、実は前期と後期で年２回申請を受け付けておりますが、後期である２学期以降の申請の部分が昨年度は急激に増えた関係で、３学期ぐらいに予定していたよりも多くの児童に対応せざると得ないという課題がございました。","id":"exchange-079"},{"speaker":"塚本委員","kind":"質問・要望","question":"特別支援教室が多くの方に利用されているというところをお伺いしたのですけれども、これがいわゆるさっき言った学級運営等にどのような効果が出ているかについてお伺いしたいのと、合わせて介助員のお話もありました。介助員についてはそういった大切な学級の運営に尽力していただいているところですが、これまで他の委員からも指摘があったと思いますけれども、人材難ということです。","respondent":"大関教育総合支援センター長","answer":"ただ、特別支援教室ができたから要らなくなるということには直結いたしませんが、そもそも支援というものはずっとということではなく、その子どもの成長に応じて少しずつ支援を軽くして、自分の自立する力を高めていくように、そのように考えているのが特別支援教育です。","id":"exchange-080"},{"speaker":"塚本委員","kind":"質問・要望","question":"最後に就学前の幼稚園・保育園等、あるいはまた今度できます障害児者総合支援施設等との教育総合支援センターの連携によって、早い段階から情報を連携していく、これは前々からいろいろなところで指摘されていることだと思いますが、この点も大変に重要なところであるというふうに捉えております。情報共有につきましてどのように図っていくのか、具体策等ありましたらお知らせいただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"小学校に入学する以前の就学前の段階での情報共有につきましては、これまでも就学支援シート、就学予定の全家庭に配布をして２割近くの回収率ということですが、各学校では情報を共有してきたところです。","id":"exchange-081"},{"speaker":"塚本委員","kind":"質問","question":"続きまして学校地域連携推進経費ですけれども、予算の執行が大体６０％台であったかと思いますけれども、一応実績としては当初予定の小学校６校、小学校３校、義務教育６校が実績としては出ておりますが、この辺の予算と実績の差についてお伺いしたいのと、それから、学校地域支援本部の活動についてどのようなものが具体的にあるのか、幾つかご紹介いただければと思います。","respondent":"熊谷指導課長","answer":"学校地域連携推進経費の執行率がよくなかったというご質問ですけれども、実際に始まったのが昨年度で、１年目、最初の年ということで５月からというふうになりまして、全体的に経費が想定よりも抑えられたということがあります。","id":"exchange-082"},{"speaker":"塚本委員","kind":"確認","question":"ご紹介いただきありがとうございました。それで、学校支援ボランティアの募集ということが今言ったような活動の１つの支えになるかと思うのですが、このボランティアの募集状況というのはどうでしょう、比較的順調に行っているのか、それともやりたい活動に比べて少し人手が足りないというような状況があるのかについてだけ最後確認をさせてください。","respondent":"熊谷指導課長","answer":"は学校単位でやってきたところですけれども、これからは中学校単位であったり横の連携ということでコーディネーター連絡会がありますので、そういった中でボランティアを共有していきましょうという動きをただいまとっているところです。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１８７ページから１８８ページの就学援助費について質問します。就学援助は親の経済力に左右されずに子どもの教育機会を保証するための仕組みの１つです。準要保護者の認定基準について伺います。今後も生活保護費の引き下げに連動させないように求めますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"この基準をどう取り扱っていくかは、今後適切に検討・判断していきたいと思っておりまして、今の段階で何か変えるとか変えないとか、そういうものを決めているものではございません。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまでも引き下げに連動されずにやってきましたので、ぜひ今予算組みもしていると思いますので、生活保護の引き下げに連動させて認定基準を引き下げないようにしていただきたいと要望いたします。次は、いわゆる入学準備金の入学前からの支給についてです。準要保護者についても入学前からの支給をすべきだと思いますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"確かにこの平成２９年３月末で要保護児童生徒援助費補助金の交付要綱が改正されまして、今までの児童又は生徒の保護者に加えて、就学予定者の保護者も対象にするという改正がされたです。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"今後も検討はしていきたいということでしたので、ぜひ深めていっていただきたいと思います。既に最近では新宿区でこの要綱の改正趣旨を踏まえて、小学校についても前倒しで支給をしていくということが発表されました。今回の改正で要綱上も可能になりましたので、ぜひ進めていただきたいと思いますがいかがでしょうか。合わせて、先進事例については情報収集もしているのかどうかも伺いたいと思います。","respondent":"有馬学務課長","answer":"転出してしまったらどうするかとか、そういったところはまた細かいところは今後詰めていこうですとか、そういった検討上にあるということで、私どもは今のところ把握しております。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"今まさにご説明されたとおり準要保護の方にも広がっておりますので、できるだけ早く実現していただきたいと思います。それともう１つ私が危惧しているのは、生活保護を受けていないけれども保護基準にある方もいるかもしれないと。本来受けられる支援が受けられないというこの制度のすき間に落ちてしまっている方がいるのではないかと考えています。そういった方への対応はどうしているのか伺います。","respondent":"有馬学務課長","answer":"学務課で準要保護というか就学援助を認定するのは前年度の所得というのがベースになっておりますので、生活保護に該当するかしないかのような、財産や預貯金などを別に調べるわけではありませんので、そういう意味ではこちらからあなたは生活保護に該当しますよとか。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"こういった制度のすき間に落ちてしまうような方たちを支援するためにも、入学前からの入学準備金の支給が必要だと思いますので、ぜひ実現していただきたいですし、実現するまでこの配慮もぜひしていただきたいと思いますので、要望しておきます。次は、入学準備金の額の問題です。準要保護者についてもこの要保護者と同じように増額していただきたいと思いますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"この金額を準要保護に適用するかどうかですけれども、他の自治体の動向も確認しながら、合わせて検討してまいりたいと思っているところです。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区単独でもいいですし、他自治体と連携して準要保護者への補助金の復活を求めていただきたいと思いますし、これは国に対してです。あわせてこの間、準要保護の就学援助の額については都の財調で加算されているということでしたので、都へも加算してほしいということを求めていただきたいと思いますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"就学援助の補助金に関しましては、平成１７年度の三位一体改革のときに税源移譲ということで準要保護のほうについては外されてしまったというような経過があります。これを新入学学用品のみでなかなか要求していくのはまだまだハードルが高いかなと考えています。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"入学準備金だけでは難しいということでしたけれども、この財調単価については求めていくことを検討するということですか、ぜひ求めていただきたいと思います。","respondent":"有馬学務課長","answer":"この準要保護の新入学学用品については、やはりこの１年ぐらいでいろいろと注目を浴びてきたというふうに捉えております。さまざまな動きが各自治体でもあるということを踏まえまして、検討は進めてまいりたいと思います。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"検討していきたいということなので、ぜひ検討していただいて、できるだけ早く実施していただきたいと思うのですけれども、次の問題に行きたいと思います。これまで区は公立に入学したことを確認してから就学援助を支給しているとの説明がありましたが、国の平成２９年度要保護児童生徒援助費補助金についての通知には、国立や私立についても記述がありました。なぜ私立や国立を対象にしないのか伺います。","respondent":"有馬学務課長","answer":"最近では、私立につきましては、この平成２９年４月からですけれども、ある一定の所得以内の方には年額１０万円の支給があるというようなこともあります。そういったこともありますので、今のところは私立は対象にはしていないです。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"教育機会均等について考えれば、私立を除く必要はないと思いますので、ご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"１７８ページの教育指導費に入るのでしょうか、政府がキッズウィークというものを示しているのですが、どういう内容なのかご説明をいただきたいと思います。２つ目は、１８８ページの給食食材放射性物質検査費です。これは毎回言わせていただいておりますけれども、まだ必要なのですか。なぜこれをやっているのでしょうかお答えをお願いします。","respondent":"大関教育総合支援センター長、有馬学務課長","answer":"基本的には３学期制で学校は進んでおりますので、９月から登校してすぐにまた秋休みになってしまうという部分は新たな課題もあろうかと思いますので、もしそのような状況にせざるを得ないということであれば。これまで５年間やってきまして検出されていないということもございまして、今年度につきましてはストロンチウムの検査回数を減らしてきたというような経過もあります。","id":"exchange-093"},{"speaker":"西本委員","kind":"質問","question":"ただ、それでも私は反対でした。ですから今も影響が残っていて、風評被害ということに直結しております。市場価格の半分もしくは３分の２ぐらいにやっと戻ってきたところで、そのような状況を誘発するような検査は必要ないと考えていますし、また市場に出回っている食品等につきましては、そのチェックは品川区ではなくて国がしっかりとやるべきなのではないでしょうか。","respondent":"大関教育総合支援センター長、有馬学務課長","answer":"現時点におきましては学習指導要領に定められた時間でしっかりと子どもたちに学ばせるために土曜授業も設定して学習を行っているところですので、次年度におきましても急激な変化等については現段階ではまだ予定してございません。それらも踏まえつつ、また、さまざまなご意見を受けながら、次年度以降については総合的に判断してまいりたいと考えています。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問・要望","question":"キッズウィークの件ですが、いろいろこれから考えていきますよということなのですが、やはり考えていただきたいのは、教育機関ですから、子どもたちの教育に資するのかということです。そもそも出てきた理由が働き方改革ですから、やはり観光や経済をどのように循環していったらいいかなどというところから来ているのです。ただ、生産者はしっかりと調査をしています。キッズウィークだけお願いします。","respondent":"大関教育総合支援センター長","answer":"品川の子どもたちのことを第一に今後も検討してまいります。","id":"exchange-095"},{"speaker":"大沢委員","kind":"質問・要望","question":"１８０ページの言語能力向上推進事業を質問します。国のほうでも文部科学省で特別チームが編成され、この言語能力についてさまざまな話し合いが行われているということですけれども、ここについてまず起きてきた背景、今、話の初めに携帯社会だ、ネット社会だとお話をさせていただきましたけれども、まずこの特別チームができるに至った社会的な事情、背景について聞かせていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"やはり子どもたちの会話能力という部分として、きちんと発信する力と受け止める力の２つが重要である、そのために取り組みを充実させていくという考えのもとにこの事業はこれまで取り組んでまいりました。","id":"exchange-096"},{"speaker":"大沢委員","kind":"意見","question":"スキルの部分で今課長からお話をいただきましたけれども、発信力、受信力はそもそも言語を発するということは自らの経験、知識あるいは情緒に基づいて相手に対して自分をコミュニケートする、要は対話をする、これが言語力だと思うのですけれども、先ほど別の説明をされていましたけれども、それを踏まえてもう１回説明してください。","respondent":"大関教育総合支援センター長","answer":"この説明という部分は、例えば京陽小学校が取り組んでいた中ですと、自分を含めて３、４人で取り組んでつくった作品についてクラスの中で発表する、どのようにどういう工夫があるのかを説明する。","id":"exchange-097"},{"speaker":"大沢委員","kind":"質問","question":"ただいま私がお話をさせていただいた、子どもたちの経験、知識、情緒に基づいてコミュニケートをするということで、京陽小学校の取り組みということでこの１８０ページの予算４９万円余の取り組みについて課長からお話をいただきましたけれども、では具体的なものに入っていきましょうか。相手にうまく自分の意思を伝える、要は会話力をより高めるためにはまず何が必要と考えますでしょうか。","respondent":"大関教育総合支援センター長","answer":"表現力としましては語彙もたくさんあったほうがさまざまな表現につながりますし、それを発信する、人前で話そうとする意欲がまず何よりも大事だと考えます。","id":"exchange-098"},{"speaker":"大沢委員","kind":"質問","question":"ちょっと話が私の伺いたい内容とかみ合っていないような感じなのですけれども、要は相手の話を聞くということ、それで話すということ、相手のことを的確に自分自身で理解して指摘をする、それは相手から聞くという以前に、聞き上手になるということ、その上で的確に捉えて相手に伝える、そのためにはメモすることが私は大事だと思うのですけれども。","respondent":"大関教育総合支援センター長","answer":"実際に友達のグループの発表を聞く際には、他のグループの子どもたちはワークシートに要点をまとめて、自分が感じたことなどについても合わせて書いておくことで、後から感想を述べたり、お互いに意見を交換し合うような授業場面がございました。","id":"exchange-099"},{"speaker":"大沢委員","kind":"意見","question":"まさに文部科学省の特別チームの中でお話をされているようなことも実施しているということですけれども、まず思考なくして言葉は出ないわけであります。思考をして初めて言葉というものが出るわけでありまして、この一連の作業において思考のないところには１つの言葉も出ない、具現化しないわけです。何が必要だとお考えになりますか。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"それを１段階さらに深めると、うん、うん、なるほどとうなずくことで、相手はもっと自分を発信をしやすくなる、自分も理解をさらに深めていくというような会話の話法についても小学校では学んでいるところです。そのために古典の暗唱、そして世界の名作、これは国語だけではなくて英語でも言語能力向上推進事業を高等学校で行っていますけれども、やはりさまざまな文化、残してくれた財産などを学ぶことで情緒力を育て、そして自分の考えを持ち。","id":"exchange-100"},{"speaker":"大沢委員","kind":"質問","question":"高校１年のときに大修館の漢文の国破れて山河在りという「春望」の句はまだ覚えています。ただ現代文におきましては現代の作家ですから、こんなことを言ったら作家の方に申しわけないのですけれども、やはり、漱石なり鴎外なりの古典の文章に親しませるということがより効果的に言語能力を高めるものだと思うのですけれども、そこのところはどういうふうにお考えになりますか。","respondent":"熊谷指導課長","answer":"ですので、今も三木小学校や浅間台小学校では暗唱をとり入れた授業を行っていますので、そういったことが子どもたちの情緒を育てる第一歩になると考えています。","id":"exchange-101"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこのところを、今まで以上に意識をして授業に取り組んでもらって、子どもたちの情緒を大いに育むような効果を上げていただきたいと思うのですけれども、今の２点についてご感想なりお考えをお聞かせください。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"あるいは音楽等、国語や算数だけではなく、その他のさまざまな教科を通じて情緒を育めるように今後とも連合作品展の充実も含めまして、教育委員会としても進めてまいりたいと考えております。小さいうちからいいものを見たり聞いたり感じたり、そして暗唱したり、そういうことをしていく中で、子どもたちの豊かな心が育まれるよう、学校教育を一層推進してまいりたいと思います。","id":"exchange-102"},{"speaker":"大沢委員","kind":"質問・要望","question":"貴重な１分が残っているのでお願いだけ最後にしますけれども、１８１ページに英語力向上についてのいろいろな事業があります。それと外国語活動を通じていかに連携をとりながら、自分の国以外の方とコミュニケートする能力を養うかについては、この次のところの事業に出てまいりますので、そこのところも今お話しをしたことに加味をしながら、この事業がさらに飛躍するように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"浅野委員","kind":"質問","question":"私からは１８３ページの図書館経費、１８５ページの非構造部材耐震化点検調査、同じく１８５ページの老朽体育器具取替について質問します。そのような中で、このカセットテープについてですけれども、図書館で保管をする場合にはそれなりの設備があって、保存できるような環境を整えているのかどうか、特別な対応をされているのか伺います。","respondent":"横山品川図書館長","answer":"カセットテープ、ビデオの保存についてお尋ねいただきました。カセットにつきましては、通常のやり方とあまり変わらないのですが、ラックに保存させていただきまして、ただあまり振動などが加わらないような形で保存しています。ビデオテープについても同様です。","id":"exchange-104"},{"speaker":"浅野委員","kind":"質問","question":"非構造部材耐震化点検調査ということで、小学校が３６校で中学校が１５校となっております。非構造部材の耐震化につきましてはよく質問していますけれども、具体的な調査の内容です。どのような形で調査をしているのかについて教えていただければと思います。調査が終わった後、次の非構造部材の耐震化をやるまでの間なのですけれども、その間にまた検討するようなことがあるのかどうか教えてください。","respondent":"品川庶務課長","answer":"平成２７年に工事を進めていたのですが、平成２７年の工事は基本的には体育館を中心としてガイドブックが出る前に基本的なところを設計していたというところで、なかなか平成２７年３月に出たガイドブックへの対応というのがとれていない状況でした。","id":"exchange-105"},{"speaker":"浅野委員","kind":"質問","question":"それともう１つ質問をしますけれども、１８５ページ、同じですけれども老朽体育器具取替という項目があります。この老朽体育器具取替をする理由は多分事故防止とかそういうことのためだということがぱっと思いつくわけですけれども、例えばこの体育器具につきましては、使える期間と言うのでしょうか。","respondent":"有馬学務課長","answer":"ですのでものによって年数の違いというのはありますけれども、一応メーカーで耐用年数は一定程度定めているものがあると認識しております。今ここで跳び箱は何年か、マットは何年かということは資料の持ち合わせがないので、年数というものは申し訳ありませんがわかりません。","id":"exchange-106"},{"speaker":"浅野委員","kind":"質問","question":"今、データがないということを伺いました。そのときに天井からつるしているロープ、これをのぼったりおりたりする、なかなかスリリングでおもしろいと言うのでしょうか、そういうものがあったのですけれども、私の友達がすべり落ちまして、ちょっとしたけがをしたということがございました。何点かで結構ですので、安全対策としての取り組みについて教えていただければと思います。","respondent":"大関教育総合支援センター長","answer":"例えばマットの耳の部分をきちんと折って使用すること以外に、破れはないかとかなどを日ごろから点検を行うとともに、学校では毎月１回安全点検日を設けておりますので、教員がチームを組んで安全な状況が確保できているかどうか。","id":"exchange-107"},{"speaker":"浅野委員","kind":"質問","question":"毎月安全点検の日を設けてということで、これをぜひ続けていって、子どもたちの安全を確保していただければと思います。このような中で、例えば子どもたちの遊びというものについて、教員の方が指導する場合もあるのでしょうけれども、そのような取り組みというものは、少し質問から外れるかもしれませんけれども、あるのかどうかも含めて教えていただければと思います。","respondent":"大関教育総合支援センター長","answer":"多くの学校では、特に小学校では、例えば１５分休み、それから昼休み等に子どもたちが実際に体育館、あるいはグラウンドに出て一輪車に乗ったりうんていで遊んだり、さまざまな体を動かす活動をしているところもありますので、どの小学校でも監護当番を決めまして。","id":"exchange-108"},{"speaker":"浅野委員","kind":"質問","question":"安全を守る役割が学校の先生にある意味託されているということかと思います。これからも子どもたちが安全に遊べる環境、そして子どものころから危険を感知する、そのような能力をこれからもつけていっていただきますようお願いを申し上げまして、今回の質問とします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"成果報告書の１７７ページ、学事制度検討経費でお伺いをします。よろしくお願いします。今後の取り扱いについてまず伺います。今後についてですが、パブコメを受けて区民意見が反映される最終答申になるのかどうか伺います。パブコメ期間が１５日間しかありません。短いです。３０日に延長を求めますがいかがでしょうか。最終答申の前には区民への説明会をぜひ行ってほしいのですがいかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"最終答申におきましても、まだこれから検討する余地はありますし、検討していくことになりますけれども、基本的にはきちんとした形で区民の方々に対しても周知をするという形ですので、説明会を開催するという方向性は今のところ考えていないところです。","id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問","question":"委員長、済みません。ちょっと語尾がよく聞こえなかったので、考えていないとおっしゃったのですか。","respondent":"篠田学校計画担当課長","answer":"説明会に関しましては、今回、それから最終答申の場におきましても、きちんとした周知を図っていくことで説明会にかえていきたいというふうに考えているところです。","id":"exchange-111"},{"speaker":"飯沼委員","kind":"質問・要望","question":"周知をしていくからしないと聞こえたのですけれども、私は折に触れて、やはりこの区民に説明をする、そして意見を求めるというスタンスに区は姿勢を変えていただきたい。区民の声が届く区政に変わっていただきたい、このことは強く求めていきたいと思います。説明会は本当に大事です。質問をします。選択制に対する区教委の評価と、特に子どもにとってどうであるのかという点において、４点お伺いをします。","respondent":"篠田学校計画担当課長","answer":"そういった意味では、この学校選択に対する評価といったところですけれども、確実にそれまでと比べて学校は大きく変わっていると、地域との結びつきも強くなっておりますし、各学校もただ単に児童・生徒の方が来るのを待つのではなくて。","id":"exchange-112"},{"speaker":"飯沼委員","kind":"質問・要望","question":"各学校の特色とは一体どういうものなのか、具体的に幾つか挙げていただきたいと思います。保護者の方々の７割が学校選択制を肯定しているとアンケート結果が出ておりますけれども、なぜよいと思っているのか、保護者の意見を直接聞いているか、そこを聞かせていただきたいのと、保護者の皆さんは個々の学校の特色を選んで学校選択をしていらっしゃるのか、つかんでいるところで教えてください。","respondent":"篠田学校計画担当課長","answer":"各学校の特色につきましては、それぞれ学校において、例えば英語に関して力を入れている学校ですとか、あるいはクラブ活動で力を入れており、そして結果を出している学校などそれぞれさまざまな形で個性が発揮されているものと認識しております。","id":"exchange-113"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特色ですが、英語やクラブ活動、私はこれを特色とは言わない。どこの学校でもここの部分はぜひ充実をしていただきたいものであると思っています。共産党はこれまで選択制の弊害を幾つも指摘をしてきましたが、本日は２点指摘いたします。一般質問でも取り上げましたけれども、選択制によって地元の児童の３割、小学校で３割が地元から転出をしています。理解できませんので見解をぜひお伺いしたいと思います。","respondent":"篠田学校計画担当課長","answer":"一般的に中学校の場合は３割が私立に行かれて３割が学校選択をしているという状況にありますので、必ずしも学校選択により６割が転出しているわけではないということはご説明させていただきたいと思います。","id":"exchange-114"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回載っている見直し案は、根本の改善にはなりません。大きな問題がもう１点あります。格差を特色ある学校と言って選ばせるのではなく、学校選択制はきっぱりやめるべきと思います。教育委員会がやるべきことは、建物、校舎の格差をなくす、好きな部活ができるように、中学生なら近隣校との連携を組むなど教育環境の整備を行っていくことが教育委員会に求められることと思いますが、いかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"今、結果的に小規模校になってしまっている学校に対しては、これまでもＩＣＴの優先的な導入ですとか、さまざまな形で援助をしております。そういった形で教育環境が劣ることがないように、教育委員会としても最善の努力をしています。これは今後とも行っていくことです。","id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"質問","question":"よろしくお願いします。他自治体でも多学年で実施された学校が多いと伺っています。全校でやったということです。これは文部科学省の調査とは別にやられた、この結果についてお尋ねします。ただ時間がありませんので、点数などは結構ですので、実施されたのが民間のテストだと思いますが他の学校等と比較して平均点よりも非常によかった教科、逆にちょっと足りなかった教科をお尋ねいたします。","respondent":"熊谷指導課長","answer":"今年度の学力定着度調査は全国規模のものです。その中で全体を通してよかった教科は国語、算数、数学、英語です。反対に残念ながら社会、理科について課題が各学年で見られました。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこでこの理科の点数が他の自治体より低かった原因として考えられるのは、１つは理科という教科の特色にあると思います。そうすると残念ながら教員経験が少ない、理科の経験が少ないという方がその学年の、小学校であれば３クラス、２クラスの理科を持つことになるということで、その点で理科の定着が少し弱いのではないかというふうに思うのですが、この２点についてどうお考えでしょうか。","respondent":"熊谷指導課長","answer":"準備等が必要なので少し、理科のほうが大変ということもあろうかと思いますが、そういったことにつきましても、若手であったとしてもやはり理科教育をこれから進めていかなければいけませんので、しっかり研修を行っていくと同時に校内事情も加味しながら。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"体験が少ないというのは、確かに学習指導要領のほうでもそういうことをもっと体験しようという形で随分記述が増えているということですので、ぜひ学校では扱っていただきたいと思います。理科教育については今後も少しお話を伺っていきたいと思います。次に、義務教育学校のほうです。義務教育学校では中学校の教員が小学校、つまり５、６年生などの授業を持つ例があるでしょうか。","respondent":"熊谷指導課長","answer":"実際のところは配置を中学校にするか小学校にするか、前期課程にするか後期課程にするかというところがありますので、そのまま持ちあがりでというのは１年間の中ではあまりありません。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問","question":"済みません。私の説明があれだったのですが、例えば先ほどの理科の先生が５年生、６年生の、あるいは６年生、７年生の理科の授業を持つということが行われているでしょうかということです。","respondent":"熊谷指導課長","answer":"そのように持ちあがりでということはやってあります。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"持ちあがりではなくて、１年間の中で６年生の理科と７年生の理科を持ちますかということです。それで持っていることが大変少ない、あるいはないのではないかと思います。それも無理だったら、区費で講師をそこに充てて、中学校の理科の先生が小学校６年生の理科と中学校１年生の理科を担当して、その円滑なつなぎをやるということを実現していただきたいというのですが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"最後に区として何とか指導助手や講師の配置ができないかというご意見だと思いますけれども、それにつきましても指導助手の配置等を学校からの要望に応じてつけているところです。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"せっかくの義務教育学校で小学校・中学校の連携を行うために、そういった現行の課題は、義務教育学校になっても解決されていないのですね。そこをぜひカバーして、貴重な小中一貫校の教育の仕組みを活用するようにぜひ東京都のほうにも要望していただきたいし、その足りないコマのところの対応をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"伊藤委員","kind":"確認","question":"この当時の担任の指導が適切であったのかということの確認と、また今後、保育園・幼稚園等を卒園して希望を持って入学してくるであろう新１年生に対して初めて指導される小学校教師の指導の内容、人格、言葉、非常に重要です。ですからこういうことについて今現在どのような指導を行っているのでしょうか。答弁をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"したがいまして初任者研修では子どもへの対応の仕方についても必ず指導しています。あわせて初任者に関しましては、学校担当指導主事が月２回訪問した際に、初任者の授業の様子等も見ながら指導・助言を行っているところです。","id":"exchange-122"},{"speaker":"伊藤委員","kind":"確認","question":"幼稚園・保育園とは全く違った環境に子どもが来るわけですよ。だからそのとき初めて会う担任の先生の指導や人格や言葉の内容というのは非常にその子の成長に影響しますし、その後の生活にも影響を与えるのではないかということを確認したかったので、今の答弁も正しいですけれども、そういうもっと具体的なことに対して、どう指導していくかということについての答弁をお願いいたします。","respondent":"熊谷指導課長","answer":"ですので、やはりそういった教員を育てていくというのが教育委員会の使命であると思いますし、また研修等も通じて、また体罰等もしっかり見過ごさないというところでやっていきたいというふうに思っております。","id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問","question":"だからこれは構造的な問題なのかな。しっかりとＰＤＣＡサイクルをやって、問題点を把握をした上で再発防止をしていかないと、また同じことになりますよという思いを大きくしたのだけれども、改めて学校の薬品の管理について、１７年間たっていまだに改善されていない現実についてどう考えていますかということと、それからＰＤＣＡについてどうお考えですかということをお聞かせください。お願いいたします。","respondent":"大関教育総合支援センター長","answer":"残念ながらそれが徹底できていない学校がございましたことを、我々も重く受けとめ、全校に対して指導を行い、さらに確認にも行っている最中です。","id":"exchange-124"},{"speaker":"伊藤委員","kind":"意見","question":"今の答弁は、正しいです。監査で指摘されているのだから。なので、そのことに対して何が問題なのかをさらにもう一歩原因を追究していって、具体的な改善プランを立案し行動していくというところまでしないとこの問題は解決していかないと、最終的な解決にはならないと思うので、もう一言答弁をお願いいたします。","respondent":"品川庶務課長","answer":"そこで学校長の管理のもとで理科教員に指示をし、徹底をさせていきたいと考えております。チェックのほうですが、指導主事が適宜学校のほうを回っておりますので、そういう段階でしっかりと確認をしていくという体制をとっていきたいと考えております。","id":"exchange-125"},{"speaker":"伊藤委員","kind":"質問","question":"それは正しい答弁です。だけど薬品の管理というのは、先生が変わろうが、やり続けなければいけない話であって、だからそういう人事異動の体制の中で指摘がされてきた、一方で指導もしてきているけれども変わっていない現状があるので、そこはさらに検討していくべきではないでしょうかということを指摘をしております。さらに前に進んだ原因究明と対応策の検討をお願いしたいのですが、いかがでしょうか。","respondent":"品川庶務課長","answer":"こういったところは当然徹底していかなければいけないところではありますので、しっかりと学校教員間の引き継ぎを徹底していくということを教育委員会からも十分指導していきたいと、このように考えております。","id":"exchange-126"},{"speaker":"伊藤委員","kind":"確認","question":"他の質問もあるのでこれでこの質問は終わるけれども、でも問題は根深いと思います。しっかり対処をお願いしておきます。来年４月から小学校で全面実施、それから平成３１年４月から中学校で全面実施。確認したいのは、この市民科の授業の中でどう展開していくのかということ、それから住み分けと整合性をどうしていくのでしょうかというのを確認いたしますのでお願いいたします。","respondent":"大関教育総合支援センター長","answer":"市民科教育に関する検討部会を教育委員会が主導いたしまして、現在新たな道徳の教科書も活用しつつ、品川区としては市民科の教科書をしっかりと学ばせながら、その中で従来と変わりなく道徳の内容も扱うという方向です。","id":"exchange-127"},{"speaker":"伊藤委員","kind":"確認","question":"これに対して品川区は道徳は市民科の中で展開していくという、それは一部理論的に合うことはあるのかもしれないけれども、では道徳の教科書の扱いはどうなのかということ、それから評価の形態、数値での評価はしないことを確認できたのだけれども、やはりその整合性について少し疑問があるので、また改めて別の機会に聞こうと思うのだけれども、今現在で品川区の考えている範囲で結構ですから。","respondent":"大関教育総合支援センター長","answer":"内容が重なる部分等がありますので、そういった部分につきましては市民科の教科書は今後改訂をしていき、さらに両方を品川としてはより活用しやすい方向に改善していけるよう検討を進めている最中です。","id":"exchange-128"},{"speaker":"伊藤委員","kind":"質問","question":"教科書を２つ使っていくなどしっくりこない部分もあるので、また別の機会に質問していこうと思います。それから最後に人権尊重教育についてです。これはＬＧＢＴのことだけがどうも先走っているので指摘をしますけれども、例えば国籍、学歴、職業、外見、障害の有無、それから生活環境等々、さまざまな観点で、やはりいろいろな思いを抱えてらっしゃる方はたくさんいらっしゃるわけです。お願いいたします。","respondent":"大関教育総合支援センター長","answer":"さまざまな人権課題を扱いながらＬＧＢＴだけではなくて障害者、あるいは高齢者に対する対応等も含めまして、さまざまな角度から子どもたちにはいろいろな人がいる、それがこの世の中だということは指導してまいりたいと思います。","id":"exchange-129"},{"speaker":"石田（し）委員","kind":"提案","question":"１７７ページ、教職員出退勤システムに関連して、教職員の働き方について、１７８ページ、生徒指導対策費について、１８１ページの英語教育の中の効果検証テスト実施についてと、ページがわからないのですが先ほどの人権に関連してダイバーシティ教育についてお伺いをいたします。これは他業種より格段に高い割合でありまして、特に小・中とも５０時間未満の教諭はいなかったという調査結果であります。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"ですので、どのぐらいいたかということを私どもで把握することができない状況です。ＳＮＳ、メール等でどのようにいじめへの対応ができるかというご質問ですが、昨今新聞報道等でＳＮＳの会社と自治体が連携をして。ですが、やはり今求められている必要な学力をつけるための授業ですので、教員については研修等を行いながら丁寧に取り組んでいるところです。","id":"exchange-130"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望です。そういった部分に関してはぜひ教育委員会が、そこは教師を守るのだという思いでぜひ取り組んでいただきたいと思います。私は決して体罰がいい悪いではなくて、やはり指導をするに当たってどのようにしていくかというのは、いわゆる保護者ともしっかりと話をするべきなのかなと思います。現に保護者の方で、自分の子どもがたたかれて、先生ありがとうと言う方もいるのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"南委員","kind":"質問・要望","question":"そこで３点にわたって質問したいと思います。１点目は漢字の問題です。学習指導要領では６年生までに習う漢字は１,００６文字だというふうに思っていますが、その点の確認をしたいと思います。この点で、学習指導要領では国と、１年程度の差があり得るというふうに思うのですが、やはり国以上に詰め込みを求めているのではないかというふうに思っておりますが、その点についてまず伺いたいと思います。","respondent":"熊谷指導課長","answer":"実際に中学校段階においても漢字が増えていくという状況がありますので、現在、品川区立学校教育要領の改定に伴い、国語部会等でこの漢字のあり方についても、どうしたら子どもたちにとってよりよいものになるか、教材の開発等も含めて検討しています。","id":"exchange-132"},{"speaker":"南委員","kind":"質問・要望","question":"そういう方たちに対してはどういうふうに教育委員会としては捉えているのか、その辺についても伺いたいと思います。そういうことが求められるわけです。過度な負担、過度な詰め込み、こういうものによって子どもの成長・発達、脳だけではなくて子どもの発達にも大きなゆがみを生じさせるのではないか、そういう問題意識は持っていないのかどうか、この点についての認識を伺います。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"早くやってしまったので忘れてしまう。そうならないように７、８、９年生では繰り返し繰り返し漢字ステージに取り組んでいくということをとっております。算数につきましては習熟度別に、子どもの発達段階だけではなくて、習熟度にも焦点を当てまして、単元ごとに理解をした場合には発展的な内容に取り組めるよう学習の集団を編成して、学習を進めております。","id":"exchange-133"},{"speaker":"南委員","kind":"質問・要望","question":"やはりこれは詰め込み教育、あるいはそういう状況にあると言えるのではないかというふうに思っているのですけれども、やはり子どもの受けとめられるキャパ、発達に応じた教育と指導のあり方、内容の設定の仕方を本当に考慮するべきだと、私はこの点でも思っているのですけれども、授業時数が増えているのは、品川区で実際にしているわけですから事実なのですけれども。","respondent":"熊谷指導課長","answer":"平成２３年度の家庭学習の実態状況調査ということなのですけれども、これにつきましてもやはり家庭学習は重要ですので、保護者と連携しながら進めてまいりたいと思います。","id":"exchange-134"},{"speaker":"南委員","kind":"質問・要望","question":"私は、できない子どもを引き上げるというのは教師として当たり前のことだというふうに思うので、しかしやり方、そこの工夫は必要だと思います。劣等感を持たせるようなやり方はやめていただきたい。それから詰め込みはやめていただきたいということ、そして勉強ができないとかやりたくないという子どもをつくらないような工夫をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"こんの委員","kind":"確認","question":"そこで、先ほども品川区でも業務改善などはしているというところで、教員の意識の改革、タイムカードでの勤務実態の把握などということですが、改めてもう１回確認ですけれども、今後さらに働き方改革を進められていくと思いますが、今後の改善として今どのようにお考えでしょうか。","respondent":"熊谷指導課長","answer":"出退勤システムもしかりです。そして、やはり意識の改革ということで、９月５日に学校働き方改革、品川働き方ルネサンスの実施についてという通知を教育長名で出しました。","id":"exchange-136"},{"speaker":"こんの委員","kind":"提案","question":"いろいろな対策をとられているということで、それを進めていくということがよくわかりました。そこで今年の５月に安倍総理に直接教員の働き方改革を求める緊急提言を申し入れいたしました。ですので、こうした国の動きをぜひ注視していただいて、ぜひこの概算要求が通った暁には、品川区として国からの補助金に手を挙げて使っていただいて、働き方改革を推進していただきたいと思いますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"そういったものを活用しながらぜひ取り組んでいきたいというふうにも思いますし、また私どものできることは何なのか、品川区としてできること、例えばコミュニティ・スクール等を通じた学校支援なども含めながらやっていきたいと考えております。","id":"exchange-137"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。次にまいります。現在、学校における防犯対策や不審者対策としてどのような対策をとられていますでしょうか。あわせて、現在の防犯対策、不審者対策の設備についてはこれで十分と思われているのか、それともまだ不十分で、今後も対策をしていかなければいけないと思ってらっしゃるのか、その辺の評価はどのようにしてらっしゃるのでしょうか。","respondent":"品川庶務課長","answer":"この警備体制でどうかという評価ですけれども、現在のところは学校においてこの警備体制で十分な体制がとれているのではと感じます。ただ、事例等によって今後新たに加えていくもの等もあるかもしれませんが、現在のところでは十分ではないかと考えております。","id":"exchange-138"},{"speaker":"こんの委員","kind":"質問","question":"現状はわかりました。今ご説明いただいた内容のほかに、各学校で校内にさすまたが設置をされていると思いますけれども、それは現在どのような形で使われているのでしょうか。いろいろなタイプのものがあると思いますが、こうしたさすまたも出ている中で、今学校に設置をされているさすまた、いわゆる校内での防犯対策が十分とはなかなか思えない感じがしますが、その点はいかがでしょうか。","respondent":"品川庶務課長","answer":"効果としては後に出されたさすまたのほうが高いのではないかというふうには感じるのですが、コスト面等いろいろ考えますと、そのあたりの導入については少し検討をしていきたいというふうに考えております。","id":"exchange-139"},{"speaker":"こんの委員","kind":"質問・要望","question":"今のご答弁で、確かに財政的なことは考えてしまうのでしょうけれども、子どもの安全が第一ですので、ぜひその点を念頭において考えていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"石田（秀）委員","kind":"質問","question":"１つ目は、なぜ今なのか。５点目が特色校や兄弟枠、それから中学校の選択というのももちろん引き続き議論をするとなっているわけでありますけれども、あまり個々の対応をするあまり、全体の目的、これは全体の目的が必ずあるわけですけれども、それが達成されないなど、本末転倒なことにならないように注意をしてほしいなと思っておりまして、その辺もどうお考えかということです。","respondent":"篠田学校計画担当課長","answer":"逆にそれがまたあまりにも長くなってしまえば、なかなか施策として出していくタイミングが難しくなると思いますので、こちらのほうはまだ確定はしてございませんけれども、答申をいただいた後にできるだけ速やかに事務局として施策として具体化をしていく中で。","id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１９０ページの障害児保育介助員費で、これは間違っていたら言ってください。先にこういうふうに言います。だけれども回数を増やしてほしいとか、カウンセラーを増員してほしいという要望があるのも事実です。しかしながら、ここは１０８万円対ゼロということになっているので、そうするとどういう話が来たかというと、全園児の診断をやってほしいという話もあった。","respondent":"佐藤保育課長","answer":"この辺に関しましては我々のほうとしても特別支援の関係で、保護者に対する相談業務をやっていますので、その中で保護者の方とまず第一義的に話をして理解をしていただいて、早期発達を促す点について頑張っていきたいというところを基本と考えております。","id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひここの部分は、本当に１０８万円対ゼロみたいなところがあると、やはりそこは大変ご苦労されている、今も保育園の部分もそういう介助員などいろいろ含めると時給がすごく高くなっている部分も考えると、やはりもちろんカウンセラー等の増員、巡回も回数も増やしていただくのはもちろんそうなのでありますけれども、その辺についてぜひ再度お考えをいただきたいと思いますので。","respondent":"佐藤保育課長","answer":"区内の全ての乳幼児が健全に健やかに育っていけるようにする事が私どもの使命と考えておりますので、私立幼稚園協会等とも相談して、さまざま検討していきたいと考えております。","id":"exchange-143"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/830551?Template=document&Id=1446#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":113464,"voices":335}},{"id":"h29-20171016-4","meetingId":"h29-c-settlement","date":"2017年10月16日","dateIso":"2017-10-16","committee":"決算特別委員会","time":"午前１０時００分～午後 ４時５３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を112件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"健康について、教育について、子育て支援について、お伺いしてまいります。１点目に、しながわデータヘルス計画の取り組みについてお伺いいたします。自民党より国に対する平成３０年度予算概算要求として、データヘルス改革の推進に９２億円を要望しています。平成２８年における品川区第二期国保基本健康診査等実施計画の現状と課題、しながわデータヘルス計画の現状と課題をそれぞれお聞かせください。","respondent":"西田健康推進部長","answer":"この目標達成には、行政だけでは難しい面もありますので、関係部署や関係機関にもご協力を仰ぎながら進めていきたいと考えております。","id":"exchange-001"},{"speaker":"横山委員","kind":"質問・要望","question":"課題として目標値に近づけるということ。国の目標が６０％であり、大分、目標値が高い状況かと思うのですけれども、現在の品川区の状況を見据えながら、国の目標値に近づけていくよう努力をしていただきたいと思います。それで、今も少しお話しいただきましたけれども、しながわデータヘルス計画の成果と、今後の国・都・区の方向性、そして区の進め方について教えてください。","respondent":"西田健康推進部長","answer":"区の進め方につきましては、今年度、この策定委員会を４回開催し、品川区第二期国保基本健康診査等実施計画とデータヘルス計画の改訂に向けて検討を進めている最中です。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"各地域ごとの分析結果についてもお知らせいただきたいのですけれども、いかがでしょうか。厚生労働省のデータヘルス計画の在り方に関する検討会におきまして、他の自治体と比較して、品川区はどのように評価されておりますでしょうか。他の自治体の好事例というのも公開されているかと思うのですけれども、品川区に共有できるような事例はありますでしょうか。お聞かせください。","respondent":"西田健康推進部長","answer":"このデータヘルス計画の在り方に関する検討会の中で品川区の事例が取り上げられていまして、医師会・歯科医師会・薬剤師会・栄養士会・関係団体との意見交換を行う中で、みんなで計画をつくろうという機運が盛り上がっているところ。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"高齢者医療、保健衛生、介護、財政、企画、生活保護など、他の部門との連携について教えてください。データヘルス事業による品川区の健康施策全体に対しての影響と、今後、どのような見直しがされ、平成２９年度・平成３０年度以降の各施策へと反映されていくのでしょうか。お願いいたします。","respondent":"西田健康推進部長","answer":"それから健康施策全体に対しての影響につきましては、データヘルス事業において、レセプトの分析に基づいた評価などを実施しておりますが、品川区全体の１指標として捉え、今後の健康施策全体にも関係してくるものと考えております。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問","question":"２点目に、款別審査でも我が会派より質問いたしましたが、区内の公衆浴場の状況についてお伺いいたします。総務省の平成２０年の住宅・土地統計調査によりますと、住宅の浴室保有率は９５.５％、また都内では９１.４％ということです。品川区内と２３区の公衆浴場の現状を教えてください。公衆浴場の地域での役割をどのように捉えておりますでしょうか。","respondent":"西田健康推進部長","answer":"出会いの湯の会場使用料に当たる委託料を１回２万５,９２０円から２万７,９４０円に増額しているところであります。それから今年度、当初予算で、品川区公衆浴場商業共同組合に対し、ＡＥＤの設備補助を行いました。今後とも支援を継続していきたいと考えております。","id":"exchange-005"},{"speaker":"横山委員","kind":"質問","question":"これまでもさまざまな支援策を講じていただいている中で、今後の支援の課題というところ、また区民の健康づくりの拠点としての公衆浴場のあり方について、オリンピック・パラリンピックの観光資源という視点からも聞かせていただきましたけれども、どのように捉えているのでしょうか。区のご見解をお伺いいたします。","respondent":"西田健康推進部長","answer":"今後は公衆浴場への現状分析や経営支援といった観点から支援が必要となってくることもあるかもしれません。関係各課ともしっかり連携して、引き続き全力で支援してまいりたいと考えております。","id":"exchange-006"},{"speaker":"横山委員","kind":"質問","question":"現在の課題を分析していただきまして、経営支援等の関係各課との連携もさらに深めながら、早急で、かつ適切な支援の構築をお願いいたします。３点目に教育についてお伺いいたします。日々、教育に対して期待を抱く区民の方々のお声をお聞きしております。そこで、品川区における教育とは何でしょうか。区民が教育に対して最も期待している内容について、区はどのように捉えておりますでしょうか。","respondent":"本城教育次長","answer":"教育委員会といたしましては、そのような期待を踏まえまして、次代を担う子どもたちに必要な力をしっかり身につけることの重要性を地域や社会と共有しまして、今、品川教育ルネサンスとして進めている品川教育の推進をさらに進めていきたいと考えているところです。","id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"品川教育ルネサンスを通して、保護者の方々の期待ですとか、また品川区の教育というところで挙げている、地域の形成者として大人になったときに責務を果たしていくような子ども、また生き抜く力など、子どもの力を育てていくということをお伺いいたしました。それは実施していただきたいのですけれども、同時に、その背景では何が起きているかということを分析していらっしゃいますでしょうか。","respondent":"本城教育次長","answer":"今後はそのような認識に立って、品川教育をさらに推進するための１つの大きな契機としていきたいと考えているところです。","id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"教育委員会で、課題が発生したときに、しっかりとそのサポート体制を敷いていただいているということが確認できまして、安心しております。児童生徒、保護者のみならず、学校や教員の方々にも一緒に成長していただきたいと私は考えております。そして次の質問にまいります。４点目に、子育て支援と児童虐待の防止についてお伺いいたします。","respondent":"福島子ども未来部長","answer":"それが、今回の改正により、特に都市部におきまして、児童相談所を中心に、児童虐待や困難ケース、あるいは複雑なケースの対応について、きめ細やかな対応を求められているということがありまして、大都市であります特別区にも児童相談所の設置が可能となったものです。","id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"５点目に、児童相談所についてお伺いいたします。平成２３年１２月の都区のあり方検討委員会において、児童相談行政のあり方については、都と区が協力し、都区間の連携や体制など幅広く検討すべき課題となることから、都区のあり方検討委員会とは切り離して、別途、整理していく必要があることが確認されています。金沢市を視察先として選定されました経緯につきましてもお聞かせください。","respondent":"福島子ども未来部長","answer":"東京都におきましては、多くの児童相談所が一時保護所と分かれておりまして、品川区で設置する際には、このような点にも配慮しながら、施設のあり方について、併設のメリットや意義についても十分検討していきたいと考えております。","id":"exchange-010"},{"speaker":"横山委員","kind":"質問","question":"そこで今後、設置を進めていく品川区の児童相談所が目指す姿を教えてください。区が児童相談所を担うことにより、部分だけでなくケース全体を見渡すことができるようになりますが、他の部門へ、どのような影響が出てくるでしょうか。予測可能な範囲で教えてください。現時点における、５年先、１０年先を見据えた計画の見通しと、短期・中期・長期の目標についてご所見をお伺いいたします。","respondent":"福島子ども未来部長","answer":"子育て支援から要保護児童施策まで、一貫した児童福祉施策の実施が可能となりまして、また保健所、保健センターをはじめとした、保健・福祉にわたる総合的なサービス等の提供が可能となってまいります。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"児童相談所の設置を希望する区に対しての東京都の支援状況についてお伺いいたします。多方面からの協力と支援を受けることはできないのでしょうか。早期開設のために東京都に対して十分な協力と支援を求めつつ、他の先進的な取り組みをしている県・市・モデル３区などとの情報共有、人材交流、特別区での合同研修会など、多方面からの協力と支援を受けていただきたいと考えておりますが、いかがでしょうか。","respondent":"福島子ども未来部長","answer":"最後に諸外国で行われております、さまざまな子育て支援に関する取り組みにつきましては、成功事例から学び取りまして、区の課題解決に努めてまいりたいと考えています。","id":"exchange-012","title":"議員研修会の内容と所要時間"},{"speaker":"横山委員","kind":"質問","question":"児童相談所開設への道のりは決して簡単ではないこともまたわかりました。しかし、児童の権利に関する条約の精神である子どもの最善の利益の実現のために、今、品川区が児童相談所を持つという意義は非常に大きいと考えております。以上で私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"横山委員に引き続きまして、総括質疑をします。初めに、品川駅南地域と京急連続立体化、それに関連して観光施策について伺います。初めに、品川駅・田町駅間の新駅の整備計画と品川駅の再整備計画をタイムスケジュールも含めて、改めて詳細にお知らせいただきたいと思います。京急連続立体化も同様にお知らせください。","respondent":"藤田都市環境部長","answer":"京急の立体化等につきましては、リニア中央新幹線が平成３９年に開業の予定になってありますけれども、これに向けまして整備を進めていきたいということで、現在、都市計画の手続を進めているところです。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"提案","question":"再度伺います。この辺が合っているのかどうか。それに伴って、区は駅前広場というものも、今、提案している。この辺の情報は、やはり区としてもしっかり捉えて、私が今、質問した中で、詳細に順を追ってと言ったので、再度、その辺を含めて、新駅の設置、品川駅の改装、そして、区画整理事業も行われるわけです。新駅は１００万平米となるわけです。もう一度、詳細に順を追って教えてください。","respondent":"藤田都市環境部長","answer":"発表されているものと、それから発表ではなく新聞報道等によるものとが、複雑に絡み合った説明でございました。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"大変壮大な計画だと私は思っております。こういうことをどう考えていらっしゃるのかを伺います。それから、具体的に言うと、例えば５分に位置づけられるのは、今は北街区だと思っていますけれども、それでは最初に案として出されたものについては、ではオフィス、それからホテルの誘致はあったとしても、この辺のところの北街区について、区はどうお考えなのかを聞かせていただきたい。","respondent":"藤田都市環境部長","answer":"このような中で、もちろんその計画の中では、歴史や水辺といったものをしっかりと評価して、事業として取り組んでいくとしているものの、品川駅周辺のまちづくりの中での水辺あるいは歴史といったものを取り込みながらやるような場所が。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、アジアヘッドクォーター特区のお話がありました。北街区をどうしていくのか。そうなってくると、これはいろいろな方に聞いた中で、新駅には５棟のオフィスビルで１００万平米という話がありました。ただ、先ほども何度も言っているように、私は、北街区に人を呼び込むのであれば集客施設をつくっていくべきだろうと思っています。こういう形で１つのまちをつくっていく。もう一度お伺いしたいと思います。","respondent":"藤田都市環境部長","answer":"どのようなにぎわい、集客施設が必要なのかは、さまざまな可能性の中で検討していく必要があると考えています。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはどうしてかというと、立体化は素案が年末ぐらいに多分出てくるでしょう。さっき言ったように、住宅棟でいいのですか、テナント、オフィスビルでいいのですか。そうなってくると、先ほど言った、５分の立地の地区をどうしていくのか、区が大きな判断をしていく。その辺のことを踏まえた答弁をしっかりしてくれないと、このまま流れてしまうような形になるので、再度答弁していただきたいと思います。","respondent":"藤田都市環境部長","answer":"この再開発協議会ですけれども、今年度、鋭意検討を進めまして、年度内には再開発のコンセプトをつくる予定だと聞いてあります。こうした中で、現在、区では東京都とともに、この地域の基盤整備等についての検討会議を立ち上げる予定です。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど言った３０年後のことを考える。つまり、住宅棟やオフィスビルでいいのですかという話を何度もしているのだけど。そうではなくて、５分のところにあって、そこに大きな行政判断がないと、事業性のことも考えれば、それは地域の方の意見というのは必ず出てくるし、私もしょっちゅう聞いています。だから、そこを踏まえて答弁をしていただきたい。一問一答みたいですみませんが、もう一度お願いします。","respondent":"藤田都市環境部長","answer":"区といたしましても、もちろん地域の考え方がまずベースにあるべきだと考えていますけれども、しっかりと一緒になって考えていく必要があると考えています。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこのところは、本当に来年の３月ぐらいまでに考えていただきたいと思いますし、協議会が今、街区ごとに３つできて動いている。ではどういうふうに舟運等をしていくのか。それで、今のイベントの評価を改めて伺いたいと思っています。この１歩が今、踏み出された。舟運も含めて、４カ所を結んで、いろいろな規制等あるけれども、その辺も含めてどう捉えていらっしゃるのか。これも改めて伺いたいと思います。","respondent":"濱野区長、安藤文化スポーツ振興部長","answer":"それが何なのかというのは、またこれからいろいろ研究していかなければなりませんが、ＪＲのこれからの動きをしっかりと捉えて、それに対応できるような策を考えていくべき時期に来ている。そんな認識でいるところであります。ですから、品川区の都市型観光プランの一つには、事業者や企業だけではなくて、地域のまちづくり観光と申しましょうか、そういうものも１つの大きな課題になっています。そんなものがなされてきたと考えています。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"意見","question":"２つあると思います。イベントをしっかり育てていって、品川区の一大イベントにしていく。これはイベント型の浅草方式かもしれません。こういうことも１つの考え方。それを実験としてやっていくということも１つの考え方で、舟運、舟運といっても、今のあの状況ではなかなかうまくいかない。こういう部分をどう考えてやっていくのか。これは、再度答弁をお願いしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"そういうものは、区の関係各課と連携して、品川区の観光振興のためにクリアしていくか、協議して検討していきたいと考えています。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問","question":"質問の１点目は、いつまでも安心して暮らせる品川区についてです。高齢者の住宅支援について伺います。事業開始時期の昭和５４年の品川区の人口は、１月１日付の住民基本台帳によると、３４万５,８３１人、６５歳以上の高齢者人口は２万９,５６０人、高齢化率は８.６％、同じく平成２９年１月１日付の人口は３８万２,７６１人、高齢者人口は８万８３６人、高齢化率は２１.１％と大きく増加しています。","respondent":"永尾福祉部長","answer":"連帯保証人が見つからず契約できない場合は、保証会社を紹介するとともに、保証料を助成するものです。相談件数と実績についてですが、相談件数は年間約延べ７００件程度です。実績ですが、平成２８年度の実績でいきますと礼金等の助成件数は２１件となっております。","id":"exchange-022"},{"speaker":"新妻委員","kind":"質問・要望","question":"私はこれまで高齢者の住宅相談を受け、一緒に物件探しや内見を行うなどしていますが、その都度、高齢者の住宅の借り難さを痛感しております。この状況を区はどう認識されているのか伺います。さらに、我が会派が求めてきた居住支援協議会の設置に向けての検討が進められていますが、現在の進捗状況とスケジュールを伺います。改めて居住支援協議会とは何かを教えてください。","respondent":"永尾福祉部長、藤田都市環境部長","answer":"住宅が見つかったとしても、手続の仕方がわからない、あと、昨今の消費者被害等に対する不安もあるということを認識しています。現在、都が主催いたします東京都居住支援協議会に参加いたしまして、国や都あるいは他区の情報収集などに努めているところです。今後、品川区の実情に合いました居住支援協議会について、引き続き検討を進めていきたいと考えています。","id":"exchange-023"},{"speaker":"新妻委員","kind":"質問・要望","question":"居住支援協議会の設置に向けて品川区が動き出していることが確認されました。しかし、時期的なスケジュール感について、今ご答弁がなく、具体的な時期がまだ見えておりません。先ほど、高齢者の住宅に関して延べ７００件のご相談があるとのご答弁がありましたとおり、今現在、お困りの方がいらっしゃるわけです。この居住支援協議会の設置までの間に品川区として支援の拡充を求めますが、いかがでしょうか。","respondent":"永尾福祉部長","answer":"現在、さまざまな相談を受けている中で、それらの声を整理しておりますとともに、貸し主である大家に対してもヒアリングを行っているところです。そのあたりの状況を見ながら課題を分析し、また区として何ができるかということについて、現在検討しています。","id":"exchange-024"},{"speaker":"新妻委員","kind":"質問・要望","question":"具体的な検討とともに、早急な対応を求めたいと思います。どうぞよろしくお願いいたします。次に、終活について伺います。我が会派のつる副委員長が、本定例会の一般質問で、横須賀市のエンディングサポート事業、いわゆる終活支援を取り上げて質問をいたしました。身の回りの整理はどうすればいいのかなど考えることがあります。講座の内容や講師もあわせてお聞かせください。","respondent":"安藤文化スポーツ振興部長","answer":"内容と講師についてですが、１コマが２時間、１０回の講座として実施し、そして講師は、終活講座で実績のあります一般社団法人日本エンディングサポート協会に依頼しまして終活を専門とした講師を派遣いただいたところです。","id":"exchange-025"},{"speaker":"新妻委員","kind":"質問","question":"質問の冒頭に品川区の高齢者数を申し上げましたが、そのうち、ひとり暮らし高齢者数と高齢者世帯数を教えてください。日本は既に６５歳以上の高齢化率が２７.７％で、２０２５年の日本は、団塊の世代が７５歳を超えて後期高齢者となり、国民の４人に１人が７５歳以上と予測されています。品川区における２０２５年の団塊世代の予測数と高齢化率をお知らせください。","respondent":"永尾福祉部長","answer":"団塊世代の予測数ですけれども、２０２５年の後期高齢者の人数は５万１,７６７人、高齢化率は２２.５％と予測されているところです。","id":"exchange-026"},{"speaker":"新妻委員","kind":"提案","question":"品川区の高齢者が住みなれた地域でどのようにお過ごしになられるのか。よりよい生活を送っていただきたいと望みます。そこで、高齢者が終焉を迎えていくという視点で、区の支援は何ができるのか、終活にかかわる事業展開や事業化に当たってはどのようなお考えがあるのか、お伺いいたします。その意識啓発の方法の一つとして、品川区版簡易エンディングノートの作成を提案いたしますが、いかがでしょうか。","respondent":"永尾福祉部長","answer":"品川区では、品川成年後見センターで、今、あんしんの３点セットというのをやっております。こちらは、１つ目が、定期的な訪問や、入院時の手続、現金などの引き落としなどを行う、あんしんサービス契約、任意後見契約、公正証書遺言作成支援をやっております。","id":"exchange-027"},{"speaker":"新妻委員","kind":"質問・要望","question":"区役所での窓口サービスについて伺います。平成２８年度の予算は、机や椅子、仕切り板等の備品購入費のみで、平成２９年度の予算は発生していません。配慮があってほしいと言われたことがあります。品川区でも、このようなワンストップサービスを求める区民のニーズは高いと思われます。健康保険や介護保険の資格喪失など、亡くなられた際の手続にはどのようなものがあるのか教えてください。","respondent":"堀越地域振興部長","answer":"区役所以外でも、年金事務所での国民年金の手続、それから２３区の場合は固定資産税が都税事務所という形になってございまして、このような手続の内容となっているものです。","id":"exchange-028"},{"speaker":"新妻委員","kind":"質問・要望","question":"３,０００人を超える方がお亡くなりになられています。ご遺族の方は、普段することがない、お悔やみにかかわる何かしらの手続をしなければなりません。このような方への住民サービス向上の必要性をどう受けとめているか、見解を伺います。そこで、業務改革の一つとして、別府市のようなワンストップサービスの窓口設置を要望いたしますが、区の見解をお示しください。","respondent":"堀越地域振興部長","answer":"現在までのところ、より円滑に手続を行っていくため郵送で行える手続もありますので、そのようなご案内とあわせて、より丁寧なご案内に努めてまいりたいと考えているところです。","id":"exchange-029"},{"speaker":"新妻委員","kind":"提案","question":"質問の２点目は、２０２０年の東京オリンピック・パラリンピックについてです。オリンピック開催時には、商店街のにぎわいの創出の一つとして、坂本龍馬像の前から足跡をつけ、浜川砲台への案内をしてはどうかと再度提案いたしますが、いかがでしょうか。さらに、国内外の多くの観戦者や観光客を迎えるためのおもてなしとはどのようなことが考えられるのか、区の見解を伺います。","respondent":"安藤文化スポーツ振興部長","answer":"坂本龍馬像など歴史的な資源の有効活用を図っていくことは、とても重要なことだと認識しており、しながわ観光協会においては、坂本龍馬と品川区の歴史マップというものも発行しております。","id":"exchange-030"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、優しさと思いやりのおもてなしというご答弁がございました。立会川駅から会場の大井ふ頭中央海浜公園へは、約３０分の道のりです。この動線に、クールスポットやミストシャワーの設置で、一呼吸入れて会場へ向かえるおもてなしや、温度が下がる効果のある遮熱舗装を歩道に施すなど、暑さを和らげるおもてなし等をあわせて要望いたしますが、ご見解を伺います。","respondent":"安藤文化スポーツ振興部長","answer":"東京２０２０大会における猛暑対策につきましては、国や大会組織委員会も検討を進めているところです。区といたしましても、オリンピック・パラリンピック競技施設周辺の無電柱化事業に合わせて、道路を遮熱舗装することになってあります。","id":"exchange-031"},{"speaker":"新妻委員","kind":"質問","question":"東京都と連携しながらも、品川区としてのおもてなしを、ぜひよろしくお願いいたします。最後に、八潮のまちづくりについて伺います。八潮は、他地域よりも高齢化率の高い、高齢者の多い地域です。建設から３０年が過ぎ、建物の維持や少子高齢化が進み、他地域より早く人口が減少していくことが予想されることから、これからの八潮をどうするのか、大きな課題があります。現在の進捗状況をお知らせください。","respondent":"藤田都市環境部長","answer":"今後、庁内検討会あるいは都、５つの住宅を供給する事業者との意見交換、２８の自治会長との意見交換などを進めまして、まちの課題の共通認識、解決に向けた目標、あるいは、ともに取り組むための仕組みといったものを整理していく考えです。","id":"exchange-032"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後の人口推移を見据え、少子高齢化の進む中での新たな取組みです。そこで、今後の八潮地域での子ども食堂開設についての可能性と、八潮の特徴を活かした多世代の交流をあわせた運営についての見解を伺います。ぜひ連携しながら進めていただきたい」と要望いたしました。今後の子ども食堂の開設に当たっては、この食品ロス削減も視野に入れた運営が必要と思いますが、いかがでしょうか。ご見解を伺います。","respondent":"福島子ども未来部長","answer":"八潮地区での開設を検討されている方はいるものの、開設場所でのさまざまな課題、例えば拠点としての食堂やカフェなどが八潮地区にはほとんどないというようなこともございまして、今後は区としましても開設に向けて支援していきたいと考えています。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問・要望","question":"昨年４月の熊本地震や、昨年末に発生した新潟県糸魚川市での大火災、先日のメキシコでの大震災など、国内外を問わず災害が多発する中、品川区における災害対策のさらなる充実が求められています。そこでまず、平成２８年度において実施されたさまざまな防災対策のうち、新たに実施された対策について、主な内容と実施の経緯、またそれぞれの成果と課題についてもお伺いいたします。","respondent":"曽田災害対策担当部長","answer":"平成２８年度、新たに実施いたしました主な防災対策としては、感震ブレーカーの設置助成、避難行動要支援者の支援体制づくり促進、地域防災計画修正の事前検討があります。","id":"exchange-034"},{"speaker":"浅野委員","kind":"提案","question":"予算の件数に届かなかった原因について教えてください。しながわ防災体験館についてですけれども、さきの代表質問におきまして、簡易水道消火装置、いわゆる街かど消火栓について、新設された防災機材整備助成金での購入などを視野に、防災区民組織の関係者や幅広い区民への普及啓発を図るため、館内での展示を提案しました。その後の設置状況についてお伺いします。","respondent":"曽田災害対策担当部長","answer":"現時点での申し込みは５５件であります。街かど消火栓のしながわ防災体験館への展示につきましては、業者への調整を現在、進めているところでありまして、間もなく発注の予定で、早期に展示できるよう努めているところであります。","id":"exchange-035"},{"speaker":"浅野委員","kind":"提案","question":"以前にも提案しましたが、助成対象地域を区内全域に広げるなどの拡充を要望しますが、いかがでしょうか。街かど消火栓については了解しました。ぜひとも早急にできるようにお願いしたいと思います。平成２８年第２回定例会で、会派から、女性の視点を取り入れたしながわ防災学校での講習の実施について提案した際、検討するとの答弁がありましたが、その後の実施状況についてお伺いいたします。","respondent":"曽田災害対策担当部長","answer":"女性の視点を取り入れた講習の実施状況でありますが、防災カフェのコースがありますけれども、その中で、「ママの立場で考える防災・減災」というテーマで３回実施いたしました。このとき作成しましたパンフレットを、子育てメッセなどで配布しているところであります。","id":"exchange-036"},{"speaker":"浅野委員","kind":"提案","question":"ただ、やはり、なかなか費用もかかるということもあるわけですので、この点についてはなるべく早期に進められるように、普及に努めていただきたいと思います。そこで、しながわ防災学校とあわせて重層的な人材育成を図るため、以前に会派からも提案させていただきましたが、改めて防災士の資格取得への助成制度の創設を検討していただくよう要望いたします。それぞれご所見をお伺いします。","respondent":"曽田災害対策担当部長","answer":"しながわ防災学校の運営、感震ブレーカーの設置助成等につきましては、先ほど答弁申し上げたように、当面、現在のやり方で行いながら、進捗状況を踏まえて、今後、考えていきたいと思います。","id":"exchange-037"},{"speaker":"浅野委員","kind":"提案","question":"そこで備蓄についてですけれども、これまでの３日分から１週間程度の必要性を周知するという話も伺っております。その中で、ローリングストックの考え方もあわせて周知するよう要望いたします。このように聞いておりますけれども、本人や保護者等に混乱が生じないよう、福祉部門と連携して、関係の障害者団体などへの事前の周知・説明を十分に行うよう要望いたしますが、それぞれご所見をお伺いします。","respondent":"曽田災害対策担当部長","answer":"避難行動要支援者の個別計画につきましては、要支援者本人と避難支援等関係者が事前に十分な協議をしながら、最適な避難ができるよう作成するものであります。引き続き、福祉部門との密接な連携のもと、対策に取り組んでまいりたいと考えております。","id":"exchange-038"},{"speaker":"浅野委員","kind":"質問・要望","question":"弱者の方をしっかりと支えていくということも進めていっていただけるということですので、ぜひとも今後ともよろしくお願いいたします。そして、関係する障害者団体の方々への事前の周知・説明につきましても、事前に十分説明を行っていかなければならないと感じており、要望いたしますが、この件につきましてもご所見をお聞かせください。","respondent":"曽田災害対策担当部長","answer":"施策の実施に当たりましては、その都度、関係するところには理解を求めてやっていきたいと考えております。","id":"exchange-039"},{"speaker":"浅野委員","kind":"質問・要望","question":"さて、話は変わりますが、私はさきの第２回定例会で、大田区や世田谷区などで、避難所に紙の簡易間仕切りを設置する協定をＮＰＯと結んでいる取り組みを紹介しました。プライバシーの確保策を求めた際、区では、私の紹介したＮＰＯ法人と協定締結に向けて協議中との答弁がありましたが、協定は締結されたのでしょうか。その後の締結状況についてお知らせください。","respondent":"曽田災害対策担当部長","answer":"簡易間仕切りに関する協定の締結状況でありますけれども、紙筒の骨組み、布製カーテンによる簡易間仕切りと、段ボールベッドの提供を発災時に受けるという内容で協議を進めておりまして、今月末には協定締結が完了する見込みであります。","id":"exchange-040"},{"speaker":"浅野委員","kind":"質問","question":"精神障害者支援についてお尋ねします。品川区議会公明党として、団体懇談会などで、精神障害者の家族会や当事者の会の皆様から切実なお声を伺いました。こうしたお声を含め質問いたします。現在品川区で行っている精神障害者支援の事業概要と取り組み状況および課題についてお知らせください。","respondent":"永尾福祉部長","answer":"こちらは、精神障害者地域生活支援センター「たいむ」において、相談や居場所等の支援を行っております。２つ目としては法内サービスですけれども、精神障害者の方が多く利用されているサービスといたしましては、ホームヘルプ、就労移行、就労継続支援などがあります。","id":"exchange-041"},{"speaker":"浅野委員","kind":"意見","question":"なかなか難しいところがあるというご答弁をいただきました。確かに、社会に出て仕事をすることは非常に大変なことかと思いますけれども、障害者の方へさらに支援をぜひこれからも進めていただければと思います。そこで、まず個別ピアカウンセリング事業の内容と、カウンセリングに当たっている方の人数、同様に民間等での取り組みについてお知らせください。","respondent":"永尾福祉部長","answer":"ただ、課題といたしましては、精神障害者の当事者の方ですので、ご本人自身が精神面での安定がないと、カウンセラーの役割ができないということで、なかなかできる方を見つけるのが大変なのが実情になっております。","id":"exchange-042"},{"speaker":"浅野委員","kind":"質問・要望","question":"ご答弁から、カウンセラーの体制が課題であるということで、今、１人ということでありますけれども、そこで平成２７年の決算特別委員会で、会派の同僚議員からも要望させていただきましたが、よりよい精神保健福祉体制をつくるために「たいむ」で行っている同事業に、区内の当事者会の方にピアサポーターとしてご協力を依頼することの検討状況をお知らせください。","respondent":"永尾福祉部長","answer":"当事者の会の中で、ピアサポーターとしての活躍をご希望されるということであれば、やはりこういう研修をきちんと受けていただいて、１人でも多くのピアサポーターができればと考えているところです。","id":"exchange-043"},{"speaker":"浅野委員","kind":"質問","question":"精神障害の特殊性もありますが、当事者の会などを中心にぜひ検討を進められることを望みます。次に、精神障害者のご家族のレスパイトケアについてお聞きします。精神障害者のご家族の世帯数とご家族への支援策をお知らせください。","respondent":"永尾福祉部長","answer":"ご家族の支援策ですけれども、「たいむ」での相談支援のほか、精神障害者相談員を区が委嘱しておりますので、そこの中で悩みをお聞きしながらアドバイスをしているという状況です。具体的なサービスの支援というのは、現状では行ってはおりません。","id":"exchange-044"},{"speaker":"浅野委員","kind":"質問","question":"なかなか難しい面があるということについては認識させていただきました。そこで、当事者を１人自宅に残すことでの不安要素もあるとのご意見も伺っていますが、こうしたケースでの当事者やご家族への支援策について、現状の対応をお知らせください。家族が避難する場所や宿泊費の助成は、区として支援ができるのか、伺います。","respondent":"永尾福祉部長","answer":"家族への支援で、宿泊の助成等についてですけれども、家族の避難場所の確保やホテル代の一部負担というのは現状としてはなかなか難しいところであるとともに、家族会の中でも、そういうふうに家族が避難するということに対してやはり賛否両論あるように伺っているところです。","id":"exchange-045"},{"speaker":"浅野委員","kind":"質問","question":"現在はなかなか難しいということを伺いました。宿泊費の問題というのは、なかなか難しいかとは思います。病院への入院ということが基本になるということでありますが、ぜひとも一歩でも踏み出していただければと思いますが、この件についてはいかがでしょうか。さらに、レスパイトケアのために、精神障害者居宅介護等事業や精神障害者短期入所事業の実施についてのお考えをお知らせください。","respondent":"永尾福祉部長","answer":"施設に短期入所するよりは入院あるいは居宅介護よりは訪問看護というような支援がふさわしいと考えております。ケアプランに基づく定例的な支援だけではなくて、緊急時の訪問体制について、今後検討していきたいと考えております。","id":"exchange-046"},{"speaker":"浅野委員","kind":"質問・要望","question":"今後につきましても、精神障害者への支援が拡充されることを要望いたしまして、品川区議会公明党の総括質疑を終了とします。どうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私からは、羽田新飛行ルートについて伺います。安倍政権は、羽田空港機能強化のため、飛行経路の見直しを計画し、２０２０年までに実施するとしています。南風時、午後３時から７時の間、品川区上空を巨大旅客機が１時間に４４機も超低空で飛行する計画です。重大インシデントとは何か、伺います。最近報道されている重大インシデントを区は把握しているのか、どのような事故だったのか、ご説明ください。","respondent":"藤田都市環境部長","answer":"しかしながら、１件あったことは事実でございまして、最近では重大インシデントに含まれない部品の落下あるいは紛失というものもありますのも事実です。国には、区民の不安の払拭に向けた説明が必要ということを強く求めているものです。","id":"exchange-048"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"大阪市で走行中の車に落下物が直撃したと、今、ご説明がありましたけれども、この映像はニュース等でも流れていますが、もうご覧になったでしょうか。私は見ましたが、衝撃でした。航空機から１メートル掛ける６０センチのパネルが落下しました。これが品川区で起きたらどうなるのか伺います。そして、この１件をとっても、都心上空を飛ぶルートは撤回すべきと思いますけれども、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"区といたしましては、しっかりと落下物対策、未然防止の対策を、国としてしっかりとるべきだと思っていますし、これについては区民の不安払拭に向けてしっかりと説明すべきと考えているところです。","id":"exchange-049"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"このようなことが品川区で起きたらということで、あってはならない、未然防止をということでした。区は、こうした落下物が落ちた際にどう対応するのか。あってはならない、未然防止というのではなく、あった際にどうするのか伺いたいと思います。私は、住民の命が危険にさらされると思います。事故が起きる前に計画撤回を求めるべきだと思います。いかがでしょうか。","respondent":"藤田都市環境部長","answer":"国といたしましても、しっかりとその辺の対策について、今、検討を進めているところです。しかしながら、国も検討を進めるというような発言までで、その後の具体的な対策というのがまだまだ示されていない状況と考えています。","id":"exchange-050"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この事故を受けて、新宿区は区長名で国土交通大臣宛てに、安全性や教室型説明会を各地で開くことを求めた要望書を提出しています。濱野区長は国に対してこのような要望書を出したのか。出していなければ、出す予定はあるのか、伺います。","respondent":"藤田都市環境部長","answer":"その他の項目については、区からさまざまな形でこれまで申し入れをしている中で、昨年８月に、品川区への環境影響への配慮事項というような形で国から文書をいただいておりますので、しっかりと、これに基づいて国に対応してもらえるように。","id":"exchange-051"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"先ほども、「未然防止を図る。説明を求めていきたい」ということでしたので、やはり教室型説明会はやっていただきたいと私は思います。羽田空港と同じくして首都圏空港機能強化が進められている成田市では、１００回以上の教室型説明会が開催されていることをご存じでしょうか。それを、今回の機能強化で朝の５時から深夜１時まで、３時間の飛行拡大が提案されています。なぜ出さないのか伺います。","respondent":"藤田都市環境部長","answer":"これは２３区総意のものですけれども、住民が納得する説明とは、この間の各区とのお話の中で、やはり教室型の説明会だと考えられていますので、しっかりとそのような形でも要望しています。","id":"exchange-052"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この間、区は、教室型説明会を強く要望していると。今も、区長会として、住民が納得できる説明を求めている。その後、相談はあったのか伺います。どのような相談だったのか、国土交通省が区に出向いてきたのか、電話なのか、文書なのか、どういう形だったのか伺います。","respondent":"藤田都市環境部長","answer":"そのような中で私どもとしては教室型の説明会について、「前回そのようなお話がありましたよね」というようなことでお話もしたところですけれども、国としては、これから控える４回目のオープンハウス型の説明もありますので。","id":"exchange-053"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、教室型説明会を開いてほしいということを放置しているのではないかと私は考えます。本気で教室型説明会を開いてほしいという区民の思いは、区に本当に届いているでしょうか、伝わっているでしょうか。今後も求めていくのでしょうか。どのように求めていくのでしょうか。新宿区のように、区長名の要望書を少なくとも出すべきです。どのようなものなのか、ご説明ください。","respondent":"藤田都市環境部長","answer":"国に対しての申し入れですけれども、先ほども申したとおり、特別区区長会としても、課題に対して十分な説明を行うように求めており、また区といたしましても、この間、国や都との個別の話し合いの場面、あるいは羽田空港の機能強化に関する都及び関係区市連絡会幹事会の場面でも。","id":"exchange-054"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私たちは、この国土交通省への聞き取りで、羽田空港に着陸する航空機からの部品脱落は７年間で４３７件と報告されました。これが品川区で起きたらどうなるか。伺います。これだけの部品脱落を起こす航空機が都心上空を飛ぶリスクを、どう考えているでしょうか。私は必ず事故が起こると思いますが、いかがでしょうか。今までどおり海の上を飛ぶことしかないと思いますけれども、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"安全対策等を、しっかりとした予防対策として確実に行うことが必要であると考えています。こうした中で、国はしっかりとした対策をとり、それについて区民にしっかり説明していくというふうにしているものです。","id":"exchange-055"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"計画をとめる決定打は区長の反対表明です。かつての品川区、そして浦安市など、その取り組みで示されていますけれども、当時の羽田空港の沖合移転を実現させた品川区と、２００４年のＤ滑走路新設時の浦安市で、当初の計画がどのように転換されてきたのかご説明ください。そして、それが、首長が反対すれば国も計画を押し切ることはできないという実例だと私は思うのですけれども、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"飛行機ですけれども、基本的には、国際基準にのっとりまして整備され、つくられ、それに基づき空を飛んでいるというような状況ですので、その辺は、そのような基準をしっかり遵守していただくべきと考えています。","id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"品川区が深刻な事態になると認識していないような姿勢なのですけれども、なぜなのか。市長を先頭に、市の上空を飛んだらどうなるかということで、私たちの真上を航空機が通過する。２０２０年までに、あと２年ほどしかないのです。今、この時点で反対しないということは、区長はこの計画を進めたいのでしょうか。品川区上空を巨大旅客機が低空飛行する計画を進めていくという立場なのでしょうか。伺います。","respondent":"藤田都市環境部長","answer":"特に部品の落下が相次いだことに対しましては、地域の皆様の落下物に対する不安の声があるということは国としても、認識しておりまして、落下物へのさらなる対策を講じ、総合的に未然防止策などの対策を充実させ、皆さんの理解をいただくことが重要であるという。","id":"exchange-057"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"当時も、国からの提案を、区や市がどう考えるかということだったと思うのです。なので、区が推進する立場ではないということですけれども、国が推進するものに区がどういう立場で向かっていくかということを聞いたのです。なので、この計画に、区長は要は賛同し、どんどん進めてくださいという立場なのか、もう一度伺います。そして、区長が反対すれば計画をとめることができます。伺います。","respondent":"藤田都市環境部長","answer":"区内では、これまで説明会が３回実施されてきてあります。４回目も今、計画されているところです。","id":"exchange-058"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"本当に、やはり今のご答弁も、国の立場で物を言われているのかと思うような発言ばかりなのです。そして、住民の不安を払拭していかなければならないと。こういったことを国も言っているのであれば、教室型説明会は少なくとも開くべきですし、ここはぜひ区長に答えていただきたいのですが、品川区の安全、区民の安全、命が、区長の決断にかかっていると思いませんか。反対表明すべきです。いかがでしょうか。","respondent":"藤田都市環境部長","answer":"これまで区民の皆様の不安の払拭に向けて、国に対して繰り返し具体的な説明を求めてきたところですが、国から示されるものは、検討していきたい、検討している、あるいは予定であるなど、具体的でなく、また不十分であると考えています。","id":"exchange-059"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"２０２０年には飛んでしまうのです。本当に今、決断をしていただきたいと思いますし、その決断が、そして反対表明するという決断が、３８万人の品川区民の命を守るということにつながっていくと思います。区長の反対表明を強く求めて、私からの質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、国民健康保険について質問したいと思います。初めに、国民健康保険の問題点をずばり３点述べます。国民健康保険料の引き下げと、無慈悲な滞納制裁をやめ、命と健康を守る国民健康保険への改善を求め、質問したいと思います。初めに基本的なことを伺います。３つ目に、来年度から実施される国民健康保険の都道府県化によってどう制度が変わるのか、伺います。","respondent":"西田健康推進部長","answer":"納付金の額は、市町村ごとの医療費水準と所得水準が考慮されるということです。都道府県化により区は大きく変わるかといいますと、区の負担や被保険者の負担が増えるものではなく、また、区の窓口業務の大部分は現行どおり実施することとなります。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高過ぎる国民健康保険料の問題について伺いたいと思います。改めて、国民健康保険料は高過ぎると思いませんかということを伺いたいと思います。なぜこんなに高くなったのかということですけれども、１つは計算の仕方を変えたことです。平成２８年度の高額療養費分は幾らなのか、その金額を教えていただきたいと思います。なぜ国民健康保険料引き下げに使わなかったのかについてもお答えください。","respondent":"西田健康推進部長","answer":"国民健康保険料は高過ぎると思わないかという点ですけれども、高いか低いかということにつきましては感じ方によるものと思いますが、健康をみんなで支えるという国民皆保険制度という制度の一つですので、制度の内容をご理解いただいて、皆様にご説明を丁寧にして。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"全国知事会も、もう国民健康保険料の重さは被保険者の負担の限度を超えているということで提言を出して、国に対して、しっかりと財政支援をしなさいということを求めているのです。４年前から削減した、来年１００％廃止する高額療養費分の税金投入をもとに戻すことで１万６,０００円。ぜひ、この２万円を引き下げていただきたいと求めたいと思いますが、いかがでしょうか。","respondent":"西田健康推進部長","answer":"高額療養費の賦課総額への算入や、保険者支援金分を保険料軽減に投入することにより、保険料１人当たり２万円余り引き下げることができるのではないかというお話と、なぜそれをやらないのかというご質問です。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"解消・削減すべき赤字だと繰り返し述べて、区市町村国保財政健全化計画を策定して、計画的に赤字を、つまり法定外繰入金をなくすことを求めています。私は、東京都と品川区が一緒になって、この高過ぎる国民健康保険料を引き下げるどころか、都道府県化させることで、さらにとてつもない値上げを強行していくことになるのではないかと大変心配しているのですけれども、いかがでしょうか。","respondent":"西田健康推進部長","answer":"今、制度改正の中で、区長会、部長会、担当課長会などもはじめとして、検討を進めているところですので、もう少し経緯を見守っていただいて、新たな制度改革に向かってまいりたいと考えているところです。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということで、法定外の繰入金を入れるか入れないかというのは、区が判断できるのです。できるので、ぜひやっていただきたいと思います。区民はこれ以上の保険料値上げは耐えられません。まして２万円も３万円も値上げとなったら、私は国民健康保険は制度維持どころか崩壊していく。改めて、保険料負担を軽減させるという立場で、今までどおり法定外繰り入れを行うよう強く求めますが、いかがでしょうか。","respondent":"西田健康推進部長","answer":"繰り返しの答弁になって大変申しわけございません。２３区統一保険料方式の中で、今、制度改正に向かって着々と準備しています。品川区独自でそういう決定をするべきものではございませんので、もう少し経過を見ていただきたいと考えております。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、保険料軽減の方向でお願いしたいと思います。滞納整理・滞納処分について伺います。滞納世帯数、短期証・資格証の発行件数、差し押さえ件数、平成２８年度の収納率、それから滞納理由として多いものを順番に５つ、お答えいただきたいと思います。東京都の収納率向上に関わる取組成績別交付算定表による交付金が幾らか、実績と交付額、それから合計の交付額についてもお答えください。","respondent":"西田健康推進部長","answer":"それから次のご質問の、東京都の収納率向上にかかわる取り組みについて交付金をいただける制度があります。平成２８年度に品川区へ交付される金額は１億６,８００万円です。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"品川区の収納率は５年前、８５.２７％で、２３区で７位でした。それが、平成２８年度、９１.６８％です。私が受けた相談です。３点お聞きします。子どもの保険証を人質にとって、無理な分納計画を強制するのは、厚生労働省の通知にも反するのではないでしょうか。直ちに、子どもの保険証は郵送すべきではないかと思いますが、いかがでしょうか。これをこれからも続けるのか、改めて確認したいと思います。","respondent":"西田健康推進部長","answer":"来年３月までの分納計画ですが、基本的には会計年度内の３月が１つの目安とはなりますが、個々のご事情もあると思いますので、ぜひ相談に来ていただければ、そういう状況を勘案し、柔軟な対応も考えていくところです。ただし、原則は３月です。","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"子どもの保険証は、２００９年１２月１６日の厚生労働省の通知にあるように、やはり速やかに発行するということが、その通知で求められておりますので、速やかに発行して手元に届くようにということで、改めてお願いしたいと思いますけれども、その点もお聞かせください。","respondent":"西田健康推進部長","answer":"差し押さえについて、今までも判例・法令等を無視して取り立てていることは全くございません。それはもう、私は誓って申し上げます。そういう方についても、その方の生活・生命を第一に考えてご相談に乗りますので、ぜひ窓口にいらしていただければと思います。","id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、子どもの保険証は速やかに届けていただきたいと思います。改めて求めておきます。ぜひこれをやめるよう、強く求めておきたいと思います。悲劇を招くのではないかと心配です。国民健康保険は値上げではなく引き下げこそすべきです。そして区の一般会計からの法定外繰入金も、子どもの均等額の軽減なども行い、払える国民健康保険料に改め、命守る国民健康保険にすることを求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"いながわ委員","kind":"提案","question":"民進党・無所属クラブを代表して、総括質疑を行います。防災まちづくり、未接道宅地、最低敷地面積、旧同潤会地区の整備、それぞれについてお伺いしてまいります。今回の質疑では、防災まちづくりの推進を通して持続可能な居住空間の創出について、問題提起と提案を行ってまいりますので、よろしくお願いいたします。初めに防災まちづくりについてであります。","respondent":"藤田都市環境部長","answer":"不燃化特区における助成ですけれども、こちらはさまざまありますが、木密地域の改善の大前提となる木造建築物の除却助成でご説明しますと、受付件数は平成２７年度が７１件と、対前年比では１.９倍となっています。","id":"exchange-070"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ここで１点、先ほど申し上げましたように、また新たな助成金の創設という部分についてご所見をお伺いしたいと思いますので、よろしくお願いします。","respondent":"藤田都市環境部長","answer":"制度の拡充につきましては、平成２８年度より、建物解体に伴い引っ越しをする費用の一部を助成する住替え支援といったものや、新たに、火災に強い建物構造にする費用の一部を助成する不燃構造化支援といった制度の運用を開始したところです。","id":"exchange-071"},{"speaker":"いながわ委員","kind":"質問・要望","question":"鋭意、努力をしていただきたいと思います。総合的な防災まちづくりは、先ほどお伺いいたしました特区内における不燃化とともに、耐震化にかかる取り組みも重要であると考えております。改めて、耐震化の取り組みの成果をどのように評価して、今後どのように展開していくのかをご答弁いただきたいと思います。","respondent":"藤田都市環境部長","answer":"区内の住宅の耐震化の支援につきましては、平成１６年に事業を開始いたしまして、これまでに耐震診断助成が１,２２６件、補強工事助成が２２８件、除却助成が５９１件など、合わせて２,５６９件の支援を行ってまいりました。この支援を通じて耐震化を進めてきたところです。","id":"exchange-072"},{"speaker":"いながわ委員","kind":"質問・要望","question":"しかし、未接道宅地の場合、既存建物の除却費は助成対象でありますが、建築基準法上、建築が困難でありますので、除却後、更地であれば、固定資産税の上昇に加えて、宅地、更地というのですか、その管理の必要性など、マイナス面が多くあり、一方、売却しようにも建物を建築できなければ宅地を売却することもできない。そして急務な行政課題の一つであると考えますが、区のご所見をお伺いしたいと思います。","respondent":"藤田都市環境部長","answer":"いずれにしても、スピーディーにこのような課題を改善していくために、区としてもしっかり取り組んでいきたいと考えているところです。","id":"exchange-073"},{"speaker":"いながわ委員","kind":"質問","question":"建て替えたいが建て替えることができない。このような現状を打破すべく、未接道宅地における建て替え要件の緩和は必要不可欠であると考えますが、ご所見をお伺いいたしたいと思います。この費用の一部というのは、土地を買うために行政がそれに公金を入れるというよりは、むしろ登記費用なのかは別にしても、何かしらの助成が必要ではないかと考えていますが、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"個別のケースでも共同化の場合でも、制度をしっかり周知して、地域の皆さんのさまざまなケースに対応できるように、全体としてしっかりと支えていくような形で支援をしていきたいと考えています。","id":"exchange-074"},{"speaker":"いながわ委員","kind":"質問","question":"１.８メートル以下だと、家を建て替えることが基本的にはできないけれど、隣がたまたま縁があって購入でき、あえて２メートルにして建築ができるような状況にし、建物を建て、そこに何世帯かで住むということをしている方も多くいらっしゃると思うので、そういう部分に関してしっかりバックアップができるような助成金の創設を行ったらいかがですかというニュアンスで、私はお伺いしたので。","respondent":"藤田都市環境部長","answer":"これについて、現在の区の考え方としては、その未接道の宅地についてですが、その土地を購入することで財産価値が相当変わってくるということもありますので、なかなか個人の財産への支援というのは難しいかと感じているところです。","id":"exchange-075"},{"speaker":"いながわ委員","kind":"質問・要望","question":"もう、おっしゃるとおりで、個人のところでそういう投入をするというのは難しいかもしれない。そこをきれいにしないと、やはり密集地域における危険度が拭い去られることはないのではないかというところを私は危惧しているので質問させていただきましたので、ぜひその辺は、そういう土地がどれぐらいあるのかということぐらいは、少なくとも所管として把握していただきたい。","respondent":"藤田都市環境部長","answer":"除却をすれば減免を受けられるというような制度もあり、そのような側面も含めまして、いずれにしても、地域の課題解決に向けてはスピーディーな対応が必要だと考えています。","id":"exchange-076"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ご存じのように、戦時下の空襲で、多分、荏原区、品川区の多くの家屋は焼失した。それで、その人たちはおそらく苦しんでいる可能性もありますので、しっかりそういうことを調査していただきたいと思います。次に、最低敷地面積についてお伺いしてまいります。今回お伺いしたいことは、最低敷地面積を定める過程と、大体６０平米とは聞いておりますが、その平米根拠をお知らせいただきたいと思います。","respondent":"藤田都市環境部長","answer":"平成１４年に、建築基準法の改正によりまして、全ての用途地域で敷地面積の最低限度を定めることが可能となり、区といたしましては、用途地域等の指定方針あるいは指定基準を策定いたしまして、良好な居住環境の区域。","id":"exchange-077"},{"speaker":"いながわ委員","kind":"確認","question":"まちづくり検討会というのは、実際にどういう方で組織されているのか。おそらく有識者も入っていて、区の所管の職員も入っていると思うのですが、そこの中に例えば地域の不動産関連というか、関係の方が入っているのか、大手ディベロッパーは入っているかもしれないですけれど、地元の方が入っているかどうかというのを確認したいと思います。","respondent":"藤田都市環境部長","answer":"地域の検討会のメンバーですけれども、経歴などの詳細については区として把握してございませんが、町会のメンバー、参加希望のあった方、あるいはこのような地区計画等に関心の高い方などに参加いただいており、私どもが考える上では。","id":"exchange-078"},{"speaker":"いながわ委員","kind":"質問","question":"ただ、まち場で、どういうまちなのかという、本当の最初のイロハのイの部分でいろいろ決めながら、こうしたほうがいいと議論する中に、地元の方というのですか、地元の不動産会社とか、そのような方が入っているのかという質問だったので、もし何かあればお答えいただいて。デメリットを最小限にする仕組みも必要だと考えますが、ご所見をお伺いしたいと思います。","respondent":"藤田都市環境部長","answer":"まちづくりの中で、あるいは地区計画を策定する中で、規制を進めるだけでは地域の皆さんの賛同は得ることはできないと、私どもも考えてあります。","id":"exchange-079"},{"speaker":"いながわ委員","kind":"提案","question":"新しい施設の建設により、大きくまちが変わろうとしていますが、従前のまちを知る地域の方々に対し、従前のまちの記憶を残すため、また、これから新たに居住される方にも知っていただくため、建設される施設内には、旧同潤会地区が持っていた、歴史を感じさせるしつらえ、いわゆる景観や意匠を設けていただければと思っておりご提案いたしますが、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"まさに、都市環境が良好になることであると思ってあります。このような中でも、地域の皆さんの声をしっかりと聞き、ご理解をいただきながら進めることが、品川区におけるまちづくりであり、引き続き、さまざまなまちの課題に向けて地域の皆様と取り組んでいきたいと考えています。","id":"exchange-080"},{"speaker":"いながわ委員","kind":"質問・要望","question":"地域の発案で決めたと言いながらも、そういう方が入っていない可能性もありますので、それをしっかりと、それこそフィールドワークを通して、どういう地域にしたらいいのか、実情に合ったまちづくりを、ぜひしていただきたいと思います。以上をもちまして、民進党・無所属クラブの総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"須貝委員","kind":"質問","question":"無所属品川を代表して、平成２９年決算特別委員会の総括質疑を行います。長期基本計画と、品川区の未来像、まちづくりについて企画部にお聞きいたします。区は、平成２１年度から平成３０年度の１０カ年にわたる品川区基本構想を策定しましたが、平成２６年４月に改訂しています。この基本構想とは何ですか。なぜ中途の５年で改訂する必要があったのですか。教えてください。","respondent":"中山企画部長","answer":"区で策定した、平成２１年から平成３０年度、品川区長期基本計画の改訂のことのご質問と認識していますけれども、平成２１年から１０年間の計画ということで策定したわけですが、その間、とりわけ東日本大震災が起こり。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問","question":"天変地異、天災、経済大転換などの変化もあります。やはりこういう目まぐるしい変化の中、経済情勢も、まちの中もそうですが、中途で改訂するぐらいなら、１０年ではなくて５年計画で策定したらどうなのでしょうか。１０年では、あまりにも長過ぎるのではありませんか、また長期基本計画は一部の事業だけにして、長期・中期・短期の３本の事業計画にするべきではありませんか。教えてください。","respondent":"中山企画部長","answer":"さらに言えば各年度の予算も、これは計画で言えば単年度の執行計画です。こういう中で、きちんと変化に対応しながら区の施策を着実に実施するという考え方を持っているものです。ただ、今のような動きを踏まえて、今後どのような計画に力点を置くのか。","id":"exchange-083"},{"speaker":"須貝委員","kind":"質問・要望","question":"今お聞きしましたが、確かに、目まぐるしく変動する中でも、長期基本計画というのは必要でしょう。この長期基本計画というのは、要は、区民、企業を含めて、品川区に、一体、何を求めているのか。その中で、今回、５年で多くの項目が改訂されたというのは、どうなのか。なので、そういう区分けは必要なのではないかと思うのですが、もう一度だけお答えください。","respondent":"中山企画部長","answer":"したがって、根本的な事象の変更がない中で、一定期間で、はなから変更する前提ということは、本来考えるべきではなく、実施の中でいろいろ対応するのが本来だと思います。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問","question":"品川区のあり方、未来像について、少し教えてください。そして、品川区は今後、どのようなまちづくりを考えているのか教えてください。","respondent":"中山企画部長","answer":"ただ、私どもが考えているのは、やはり区民の方々が安心して、また誇りを持って住み続けられるということと、外からは、品川区に訪れてみたい、住んでみたいと思っていただけるまちづくりを、さまざまな計画の観点の中から、どのように展開していくか。","id":"exchange-085"},{"speaker":"須貝委員","kind":"質問","question":"今、そういうお話でしたが、もう少し具体的にお聞きしますと、現在、学校の都心への回帰が進んで、企業の本社機能が都心に移っている。区内小中学校、保育園、幼稚園の収容能力は足りるのでしょうか。私はここでおのずと答えが出ていると思います。観光やにぎわいを訴える方もいますが、この品川区のどこに世界に誇れる観光地や観光資源があるのでしょうか。今の質問に対してご見解をお聞かせください。","respondent":"中山企画部長","answer":"そういう点では、地の利を活かしながら、なるべくその弊害を減らし、よさをさらに伸ばしていく。これを具体的にどういうふうにやっていくかについては、冒頭お答えいたしましたけれども、それぞれ計画の検討の中で、強みを伸ばすよう進めていきたいと考えています。","id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"まち並みをきれいにする、水辺資源を大事にするというのはわかりますが、私は少し違うのではないかと。そして、これについて少しご見解をお聞かせ願いたいのと、また魅力あるまちやお店があれば、自然と人の足は向くのではないですか。私は、やはりまちづくり、この品川区のことを本当に考えたら、何がこの品川区に役立つのかということを考えるべきだと思うのですが、もう一度ご見解をお聞かせください。","respondent":"中山企画部長","answer":"ですから、本来あるものをいかに、さらに活かすかという点はありますけれども、これを無理やりに進めようというようなものでは決してないと考えます。","id":"exchange-087"},{"speaker":"須貝委員","kind":"質問","question":"教育改革について質問します。品川区では、平成１１年に教育改革「プラン２１」を策定し、これに基づき学校経営の改善・向上と、教員の意識改革・資質向上を図るとともに、平成１８年度より小中一貫教育を全ての区立小中学校で実施しています。そして、平成２８年度に新たな取り組みとして品川教育ルネサンスを開始。お聞きします。教えてください。","respondent":"本城教育次長","answer":"それとともに、独自といいつつ基盤となるのは、全国あるいは東京都全体の共有の資質というところで、ウエートが高いところもありますので、そういうこともあわせて、しっかり研修、あるいは実践等を通じ、力をつけてもらい、それに基づき。","id":"exchange-088"},{"speaker":"須貝委員","kind":"質問","question":"次長、教員が転出入を繰り返している中で、区の教育制度はこうですよ、こうやってください、こういうふうに指導してくださいとしっかり教えていますが、３年たったらいなくなる。そういうことを繰り返していていいのでしょうか。こんなことを繰り返していていいのでしょうか。ですけれど、現実、こんなことをやっていたら、本当に事業費の無駄になるだけではないですか。２点についてお答えください。","respondent":"本城教育次長","answer":"そういう意味で、子どもたちに対する責任を果たすことでもありますし、あるいは現行の制度下においては、２３区相互にそれぞれ、ある意味ではお互いさまに、現にいる先生たちに対してしっかりフォローすることによって、東京都全体の教育の質を確保し、そして、その中で。","id":"exchange-089"},{"speaker":"須貝委員","kind":"質問","question":"それが教育ではないでしょうか。私はそう思うのです。それがしょっちゅう異動していたらどうなりますか。やはり違うでしょう。私立では、規模が全然小さいですが、１つの学校の中で、同じ教育制度をずっと習って、先輩から教わってやってきています。実際、現在のようなやり方をしていていいのでしょうか。そういうシステムをつくらなければいけないと思うのですが、その辺についてご見解をお聞かせください。","respondent":"本城教育次長","answer":"より一層、そのような実現に向けて、これからも粘り強く求め続けていくことが、基本的な考え方です。","id":"exchange-090"},{"speaker":"須貝委員","kind":"質問","question":"そこの地域で教育をしているならば、そこに人事権をあげるというのが基本です。それを東京都が離さない。これは、どうしても、私は尋常でないと思います。子どもが育っていくのですから。こんなことをやっていたら、子どもたちの教育はどうなのですか。そして、教員の教育も、やはりきちっとやって、いい教員を品川区に集めるということも必要ではないのですか。この２点についてお聞かせください。","respondent":"本城教育次長","answer":"現行の制度の枠内ではありますけれども、そういう意味で、品川区教育委員会の意向に配慮した形の運用上の中で、そのような措置を含めて私どもとしては活用しながら、教育、学校現場の質の向上に努めているところです。","id":"exchange-091"},{"speaker":"須貝委員","kind":"質問","question":"でも、実際に今後、小学校の免許と中学校の免許、両方持っている教員が、この義務教育学校を運営していかなければいけない、子どもたちを教育していかなければいけないということが、きちんと示されているのに、それをやれるのですか。第一に、先生を呼べるのですか。そして、その先生が異動してしまうのに育てられるのでしょうか。それについても少しご見解をお聞かせください。","respondent":"本城教育次長","answer":"それで、固有職員については６割強の職員が、現在でも両方の免許を取得しているものでございまして、これからも、その他の職員も含めて、可能な限り、両方の免許を取得している方を確保するとともに、現在、固有教員で、片方の免許しか持っていない教職員に対しては。","id":"exchange-092"},{"speaker":"須貝委員","kind":"質問・要望","question":"せっかく品川区が、いろいろ進み出して、やり出した。それまではいろんな諸問題もありました。でも、ここまでやはり築き上げて、教育委員会の人も一生懸命やられている。でも、そういう制度に阻まれて、なかなか前へ進めない。子どもたちだけではなくて教員も育てるということもすごく大事なことなので、私は、もう何とか早く、品川区に教員の人事権を持ってこられるように頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"吉田委員","kind":"確認","question":"品川・生活者ネットワークを代表して総括質疑を行います。障害者福祉全般からと、羽田増便計画による航路変更にかかわる問題について伺います。この理解でよろしいかどうか確認させてください。では、現在、障害者７団体に入っていない他の団体については、どのようにしたら、現在の障害者７団体と同様に、意見聴取や情報提供の対象になれるのか伺いたいと思います。何か具体的な条件はあるのでしょうか。","respondent":"永尾福祉部長","answer":"障害者の方の意見聴取についてです。障害者７団体についてですけれども、区では、障害種別全てを包括するということから、また、それぞれ国や東京都に上部団体があるというところで、７つの団体について、昭和５３年から、区と連携してさまざまな事業を実施しています。","id":"exchange-094"},{"speaker":"吉田委員","kind":"質問・要望","question":"障害者７団体については、上部団体があるとか、そういうことがあると理解しました。そういう団体にも情報提供が行われるということなのですけれども、まず区がそういう団体を把握しなければいけないと思うのですが、その辺の手続といいますか、そういうものが具体的に何かあれば教えていただきたいと思います。","respondent":"永尾福祉部長","answer":"こちらの登録申請をしていただくことによって、どういう団体があるかを区のほうで把握しています。受付の際、その団体の会長なり代表者とのお話の中で、情報提供についてのご依頼があれば積極的にやっていきたいと考えております。","id":"exchange-095"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひきちんと位置づけていただきたいのですけれども、今の福祉団体の登録には、何か要件というものはあるのでしょうか。その点を教えてください。それから、情報提供について伺います。例えば１つ例をとると、障害者福祉のしおりなどが新しく発行された場合に、発行されたということがどのように各団体に周知されるのでしょうか。それぞれの団体は、新たな仲間、参加者を求めていると思います。","respondent":"永尾福祉部長","answer":"会の案内ですとかパンフレットやチラシ等につきましては、本当に区民の方に広くお伝えできる内容なのかなどを精査し、またそういう内容になるようにお話をしながら進めていきたいと考えております。","id":"exchange-096"},{"speaker":"吉田委員","kind":"質問","question":"それがなかなか難しいのだというのを団体の方からも伺っていますので、その辺について、もう一回、今後どのように対応していくか伺いたいと思います。次に、これは昨年の決算特別委員会の総括質疑で伺った、品川区内の施設での虐待事件についてですが、当時の福祉部長は、そのご答弁の中で、改善指導等は現在も続いているとおっしゃっています。現在の改善指導の状況を教えてください。","respondent":"永尾福祉部長","answer":"ただ、こういうことというのも、終わったからいいということではなくて、やはり毎年やっていかなければいけないと区でも認識しておりますので、区では法人の指導検査もありますので、そういう機会を見て、きちんと指導していきたいと考えております。","id":"exchange-097"},{"speaker":"吉田委員","kind":"質問・要望","question":"本来、こういう事例が起きたときの区の報告の手順など、今ご答弁がなかったかと思います。民間事業者の方から、虐待のような大きな問題でなくても事故があったら、報告書を区に提出することが求められていると伺いました。書式も見せていただいたのですけれども、それが機能しなかった点も含めて伺いたいと思います。","respondent":"永尾福祉部長","answer":"区といたしましては、やはりまず第一報として、確認が全部済まなくても報告をするように、厳しく指導したところです。","id":"exchange-098"},{"speaker":"吉田委員","kind":"質問・要望","question":"もちろん、こういう事件がないことが一番なのですけれども、もし起こった場合の対応というのは、すごくその後のことを求められると思いますので、ぜひよろしくお願いいたします。現時点で何か、この点についての見解があれば伺います。それから次にいきます。こちらについては在宅レスパイトともあわせて、レスパイト事業全体としてどう考えているか伺いたいと思います。","respondent":"永尾福祉部長","answer":"こちらは、平成２８年度から通所者が多くなったということで、支援員を１人増やしております。その効果もありまして、平成２７年度のレスパイトの実績は０人だったところが、平成２８年度は８人という状況になっています。","id":"exchange-099"},{"speaker":"吉田委員","kind":"質問・要望","question":"ピッコロの延べ８６６人というのは、ピッコロ事業全体ということでしょうか。その中のレスパイトの延べ人数といいますか、そういうものがあれば伺いたいと思います。それから、今後のレスパイト事業全体の展開ということについて伺ったのですけれども、お答えいただきたいと思います。","respondent":"永尾福祉部長","answer":"やはり、送迎が多少、課題になっているというふうな認識を持っておりますけれども、今後とも通所の事業について拡大できればと考えています。もう一つ、医療の必要な方などに対する在宅レスパイト事業ですけれども、これは平成２８年７月から実施しているところです。","id":"exchange-100"},{"speaker":"吉田委員","kind":"質問・要望","question":"一番厳しいところから始めるのは、十分理解できますが、それで実績がこれだけですので、ぜひこれから条件を緩和していく方向で考えていただきたいと思いますが、その点について伺いたいと思います。次に、羽田増便計画に伴う航路変更について、続けて伺います。あくまで、それを求めているということで理解してよろしいでしょうか。その点を伺います。","respondent":"永尾福祉部長、藤田都市環境部長","answer":"在宅レスパイト事業のことですけれども、昨年の７月１日スタートというところで、まだまだ周知が不足しているところもあるかと考えています。羽田空港の機能強化についてですが、この間、９月ごろから、航空機からの部品の落下あるいは部品の紛失について報道が続いていると、区としても認識しています。","id":"exchange-101"},{"speaker":"吉田委員","kind":"質問・要望","question":"国土交通省は、昨年の段階ですけれども、落下物リスクはゼロにはできませんと明言しています。だから、落下物ゼロと国土交通省が言うまでは、認めないと考えていいでしょうかと伺いましたので、その点についてお答えいただきたいと思います。豊島区長は議会の中の一般質問の答弁で、９月の区長会で国土交通省航空局長が説明に来たときに、その方に対して強く教室型の説明会を求めたと発言しています。","respondent":"藤田都市環境部長","answer":"羽田空港の機能強化についても、その中で、騒音影響や安全管理など、懸念されている課題に対し、住民が納得できる十分な検討および説明を行うことを要望しているところでございまして、これは２３区総意の区長会の要望であるという認識をしています。","id":"exchange-102"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから、品川区はやはり落下物リスクはゼロにしてほしいと要望し続けるわけですよね。一方で国土交通省は、リスクはゼロにはできないと言っているわけですから、それを認めるまで主張し続けるということでよろしいですね。品川区長としても、こういう事態を受けて、意見書を出すとか、区長会の中で強く要望をされるとか、そういうことがあってしかるべきかと思いますが、その点についてご見解を伺います。","respondent":"藤田都市環境部長","answer":"こうした中でも、区民に対して丁寧な説明をしていくというようなことも申しておりますので、これについてしっかりと実現できるように、引き続き求めているところです。","id":"exchange-103"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、品川区長としても、豊島区、それから新宿区と足並みをそろえて、意見書、要望書を出していただきたいと思うのですけれども、その点について見解を伺いたいと思います。区としては、国土交通省の言い分をこのまま認めるのではなくて、挙証責任はやはり、大きな公害訴訟と同様に国土交通省側にあると主張するべきと考えるのですけれども、その点についていかがでしょうか。","respondent":"藤田都市環境部長","answer":"しかしながら、落下物が万が一発生した場合については、国が責任を持ち調査を行い、航空事業者とともに対応していくことを確認しています。","id":"exchange-104"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区もしくは品川区長として、何か意見書・要望書を出す意図はあるのかということを伺いましたので、その点についてもう一回お答えいただきたいと思います。それから、被害に遭ったときの補償です。その被害自体を誰が証明するかというのは非常に大きな問題です。区民が証明するのはなかなか難しいです。なので、ぜひこの点については認識していただきたいと思うのですが、その２点について伺います。","respondent":"藤田都市環境部長","answer":"補償についてですが、この間の報道で、補償の充実という観点の中では、はっきりと原因がわからないものについても対応を検討していくような内容もあります。いずれにしても、しっかりと対応できる補償の充実を国として検討していただきたいと考えています。","id":"exchange-105"},{"speaker":"吉田委員","kind":"質問・要望","question":"部長もご答弁でおっしゃっていますけれども、補償だけが、単独で示されるものではあってはならない。ぜひ、この点について、品川区として区民の命を守るという立場で発言していっていただきたいと思います。これは最後に強く要望して、品川・生活者ネットワークとしての総括質疑を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区議会自民党・子ども未来は、平成２８年度品川区一般会計歳入歳出決算、同品川区国民健康保険事業会計歳入歳出決算、同品川区後期高齢者医療特別会計歳入歳出決算、同品川区介護保険特別会計歳入歳出決算をそれぞれ認定いたします。品川区におかれましては、引き続き、区民の福祉・生活の向上に努められますことを要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"若林委員","kind":"提案","question":"事業執行においては、公園を活用した保育園整備など、総合的な待機児童対策、ネウボラネットワークやオアシスルームの拡充を図り、校舎やトイレ等の改築・改修、特別支援教室の全校設置など、子育て・教育施策、介護予防総合事業や支え愛・ほっとステーション、特別養護老人ホーム２カ所の開設・竣工など高齢者施策、耐震助成拡充や、リニューアルオープンした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-108"},{"speaker":"南委員","kind":"質問・要望","question":"共産党は安倍改憲に、区長が反対するよう求めましたが、区長は発言を拒否しました。区は、計画撤回を国に求めるべきです。引き下げこそするべきです。改善を求めます。今年度策定の障害福祉計画と障害児福祉計画は、当事者意見を反映させるよう求めます。サービス単価を現在の介護報酬まで引き上げることを求めます。非核平和都市品川宣言をしている自治体として、国に対して、署名するよう求めるべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"石田（し）委員","kind":"提案","question":"民進党・無所属クラブは、平成２８年度一般会計および国民健康保険事業会計、後期高齢者医療特別会計、介護保険特別会計の各歳入歳出を認定いたします。本特別委員会の款別審査や総括質疑での我が会派の指摘や提案を、次年度予算をはじめ今後の本区の施策に反映するよう強く要望して、民進党・無所属クラブの意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"須貝委員","kind":"質問・要望","question":"平成２８年度決算に対する無所属品川の意見表明をいたします。無所属品川は、平成２８年度の品川区一般会計、国民健康保険事業会計、後期高齢者医療と介護保険特別会計の各歳入歳出決算を認定いたします。平成２８年度の決算は、実質収支が４４億円の黒字、さらに７９億円の基金を積み上げ、健全で豊かな財政を維持しています。以上で、無所属品川の意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"田中委員","kind":"提案","question":"そのためにも、区の教育施策の中でも、一緒に学び育つ環境整備を進めることを要望します。事故を防げないのであれば、第一義に住民の命と財産を守る責任のある品川区は、都心低空飛行ルートには賛成できないと示すべきではないでしょうか。各款別審査で指摘・提案させていただいた意見を、予算編成に活かしていただくことを要望して、品川・生活者ネットワークの意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/830551?Template=document&Id=1448#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":99561,"voices":241}},{"id":"h29-20171018-10","meetingId":"h29-cm10","date":"2017年10月18日","dateIso":"2017-10-18","committee":"議会運営委員会","time":"午前１０時３４分～午前１０時５９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/560108?Template=document&Id=5244#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":8639,"voices":44}},{"id":"h29-20171019-10","meetingId":"h29-cm10","date":"2017年10月19日","dateIso":"2017-10-19","committee":"議会運営委員会","time":"午後 ２時５０分～午後 ３時２４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","topics":[{"id":"topic-01","title":"平成２９年第３回定例会","agenda":"平成２９年第３回定例会","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"案文の朗読をもって提案説明とします。平成２９年１０月１９日、提出者、大沢真一、渡部茂、本多健信、伊藤昌宏、横山由香理、鈴木真澄、渡辺裕一、鈴木博、高橋伸明、石田秀男。議長に対して、５月の臨時会前に、今回の提出者全員から議長と荏原消防団長の兼職はするべきではないとの意見が出されました。皆様にもご理解を頂き、議長不信任動議を可決して頂きますことをお願いし、提案説明とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"議長の選任というのは本当に議会にとっては大変重いことだと思います。それで今回の松澤議長選任に当たっては、第一会派の自民党のほうから推薦ということであって、私たちも松澤議長がもちろん消防団の団長をやっているということも、区議会議員皆さん知らない方はいないと思うのですね。議長と団長というのは兼任することが禁止されていることなのかどうなのかだけ、確認をさせていただきたいと思います。","respondent":"久保田区議会事務局長","answer":"私どもでもいろいろ調べたのですけれども、議長と消防団の団長を兼職してはいけないという規定は見当たりませんので、その旨ご報告をします。","id":"exchange-002"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"消防団長と議長を兼任してはいけないなどという、それはないですよ。個別の長をやってはいけないみたいなのは、ないではないですか。団長と議長をやってはいけないとかではなくて、そういうもの、ではほかのものはあるのですかという話で、例えば町会長と議長は兼任していいのですかとか、そういうところまで発展する話だと思うので、その辺も含めて、できたら教えていただきたいと思います。","respondent":"久保田区議会事務局長","answer":"「普通地方公共団体の議会の議員は、地方公共団体の議会の議員並びに常勤の職員及び地方公務員法第２８条の５第１項に規定」、そこは調べなければいけないですが「短時間勤務の職を占める職員と兼ねることができない」。","id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"先ほど石田委員が読み上げた文章の中で、以上のことからというところ、３段落目「従って、実質的に兼職は出来ません」というふうにはっきり書いてあるのですけれども、これは何をもって兼職はできないというふうに判断をしてこのように書かれたのか、自民党のその辺の判断を聞きたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういうことの中で、それは兼職はするべきではないのだろうという話があった。そこで耳に入った方がいろいろ確認をしたら、ここに書いてあるとおりの発言があったりもしているわけで、それは議長としての職責をしっかり全うしていないのではないのかと、ここに書いてあるとおりであります。だから自ら６月に消防団長はお辞めになるという発言をされたのだと我々は理解をしているということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"そしてしかも議長ご本人は、１２月末をもって辞めるというふうに表明しておられる、そういう状況でありながら今日最終本会議のこの場面で突如出してくるという、動議は誰だって出せる権利はありますけれども、しかし議会を止め、そして様々なところに大きな影響を与えるようなこういうやり方は、私は議会としては好ましくないと思っているのですね。そういう点についてはどうなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"兼職は、先ほど言ったようにできるのでしょうが、それぞれ長としてやっていくのであれば、それは片方が、両方の長として出るわけにいかないわけですから、実質的に兼職はできないというふうに我々は理解をしているということであります。５月のときに自ら約束をした、口頭での約束ではありますけれども、それを反故にされている状況が続いているというのも事実であります。","respondent":"松澤議長","answer":"今お話いただきましたけれども、６月２６日、これは私の７２歳の誕生日ですので、そこで辞表を実際に出しております。ただそれは副団長のところで留め置きというふうになっております。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"私は何回も石田秀男委員の説明を伺っても、やはり党内の問題だというふうなところから脱していません。そういうふうにしか理解できません。したがって、１２月に辞めると表明されているし、どうこうといろいろ説明されたけれども、これはやはり党内で解決すべき問題ですよ。これは人事の問題であると議長がそう説明されて、それは２ヶ月ぐらいはかかると思います。","respondent":"久保田区議会事務局長、松澤議長","answer":"その後、議場即決を諮りまして、採決の方法については、今事務局で考えておりますのは、無記名投票により実施をしたいと考えております。これは後ほどご議論いただければと思います。ただいま文書を配らせていただきましたけれども、ここにいらっしゃらない会派の方たち、文書をもらっていない方もいらっしゃいますので、それを配っていただいて、それを読む然るべき時間を与えていただければと思うところですが。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/560108?Template=document&Id=5248#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":10519,"voices":27}},{"id":"h29-20171106-6","meetingId":"h29-cm11","date":"2017年11月6日","dateIso":"2017-11-06","committee":"区民委員会","time":"午後 １時００分～午後 １時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","topics":[{"id":"topic-01","title":"第１８回 品川区中学生の主張大会","agenda":"第１８回 品川区中学生の主張大会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今年で１８回目ということで、ぜひ、中学生が自分の言葉で、地域の方や私たち大人社会が少しでも中学生の気持ちや思いを理解できるように進めていただきたいと思います。１８回目ということで、これが始まった背景、当初の状況について１点伺います。財源についてなのですけれども、区の一般財源なのか、国や東京都からの補助金なのか。そこら辺だけご説明ください。","respondent":"伊崎地域活動課長","answer":"当事業は平成１２年度に初めて行われました。","id":"exchange-001"}]},{"id":"topic-02","title":"オリジナル婚姻届の配布","agenda":"オリジナル婚姻届の配布","exchanges":[{"speaker":"田中委員","kind":"質問","question":"窓口での意見等を参考にということだったのですけれども、どのような意見を聞かれた結果、このような形になったのかをまず教えてください。","respondent":"提坂戸籍住民課長","answer":"どちらでもよいというご意見をおっしゃった方からは、戸籍とか住民票に記載されることが大事なので、こういう様式には特にこだわらない、あまり興味がないというご意見等をいただきました。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"今伺った意見の中でもあったように、婚姻届出を記念としてほしいという声がきっとあったのだと思います。ただ、これだと、婚姻届出とはまた別に自分たちで記入するものとなっているではないですか。交付予定数が４,０００部なのですけれども、４,０００部の配布の仕方と、４,０００部を超えた場合はどうなるのかを伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"４,０００部の配布の仕方については、先ほどもご説明申し上げましたけれども、婚姻届を私どもの窓口や夜間の窓口で出された方に、引き換えでお渡しする。","id":"exchange-003"},{"speaker":"塚本副委員長","kind":"質問","question":"非常に力を入れて、いろいろ工夫をされてつくられたと思うのですけれども、まず、見て、大変に興味を持ったのは、品川区の坂になじんで、金婚式と銀婚式ぐらいは私も知っていましたけれども、こんなにたくさん、節目節目にあるのを勉強しました。この形をつくっていく経緯、どこら辺からこういうアイデアが出たのかを教えていただければと思います。","respondent":"提坂戸籍住民課長","answer":"こちらのブルーの書式につきましては、品川区に２６の坂があるということで、ホームページの環境・まちづくりというジャンルがありますけれども、その中の道路という中にこれが記載されています。","id":"exchange-004"},{"speaker":"塚本副委員長","kind":"意見","question":"先ほど、４,０００部について、年間の婚姻届は６,０００件ぐらいということなので、概ね１年以内の方が取りに来られると考えても、おそらく４,０００部あれば足りなくなることはほとんどないという想定での４,０００部だと思います。","respondent":"提坂戸籍住民課長","answer":"今回、婚姻届の様式をつくらせていただいたわけなのですけれども、来年度に向けて、出生届についてもオリジナルのものをつくろうと計画して、予算要求をしています。","id":"exchange-005"}]},{"id":"topic-03","title":"しながわみやげの冊子改定","agenda":"しながわみやげの冊子改定","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"本当に地域の方が情報を求めて、それが定着している中で、このみやげのガイドは相当喜ばれるだろうし、すごく広がるような予感がしているのですが、１万部という作成部数。それと販売促進のところ。この中で選ぶのは先方だとして、まず、そういうところへのＰＲ活動というのは、すごく波及効果もある気がするので、踏み込んでもいいのではないかという意見を持っていますが、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"過去の３年間は、年に１度、コンペティションをして認定をしておりましたが、今年度からは年に三、四回程度、幾つか、ある程度の商品のエントリーが集まった時点で認定をさせていただいて、できるだけリアルタイムで反映をさせたいということもありますので、冊子としては比較的。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"例えば学校が２０２０年に向けて、各国の大使館とか料理とか、いろいろな交流がこれから広がっていく中に、とてもいいツールだと思います。品川区の情報発信の一環だったり、観光の促進であったり、いろいろな要素を取り交ぜれば、そのきっかけづくりには、支援策、知ってもらうための策があってもいいかという気がしているので、この施策自体が弾力的に広がっていくことを望んでいますが、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"現在でも、この冊子の冒頭に、先ほど申し上げたようにシティプロモーションとの連携とか、それから、大使館のほうもいろいろ会議のときに観光の情報も話していただいたりしていますので、今後、少しでも情報のＰＲの場を広げて、しっかりと知っていただくことと、それから。","id":"exchange-007"}]},{"id":"topic-04","title":"ユニバーサルスポーツ大会の開催","agenda":"ユニバーサルスポーツ大会の開催","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この緑色のチラシのことなのですけれども、参加費が１００円となっているのですが、これは何代でしょうか。","respondent":"池田スポーツ推進課長","answer":"こちらの参加費につきましては、参加された方の保険料が主なところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"これを有料にするのかという思いがあったのです、そこについて伺いたいと思うのです。例えば、１０００日前フェスタもふくしまつりも中小企業センターのセンターまつりも、参加することそのものは無料ではないですか。そこで何を買ったり、何を楽しんだり、何を感じ取ったり、交流したり。実態としては団体保険料だったとはいえ、少し工夫をしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"私どもでやっている生涯スポーツにつきまして、こちらのユニバーサルスポーツ大会につきましては参加費１００円ということで、これは保険料相当分をいただいているところですけれども、ほかにも、スポ・レク推進委員会、地域スポーツクラブ等でも教室を行ってあります。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"あくまで保険料であれば、保険料と書いていただきたいと思うのです。私が伺ったのは、その趣旨なのです。そういう意味では、参加費は無料にする。ただし、保険料は１００円かかるというのがユニバーサルスポーツ大会の趣旨に沿った形ではないかと思うのです。それについて、改めて伺いたい。そういう意味で、もっと工夫ができる点があるのではないかと思うのですけれども、改めていかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"委員のご指摘のように、ほとんどが保険料ということでやっておりますので、今のご意見のところは考えするようにいたします。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/681247?Template=document&Id=2794#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":11298,"voices":41}},{"id":"h29-20171106-7","meetingId":"h29-cm11","date":"2017年11月6日","dateIso":"2017-11-06","committee":"厚生委員会","time":"午後 １時００分～午後 ３時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","topics":[{"id":"topic-01","title":"地域福祉計画改定に伴う区民アンケート調査","agenda":"地域福祉計画改定に伴う区民アンケート調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、地域福祉計画とやさしいまちづくり計画の統合ということですが、この統合というのは、国からの方針があるのか、どうなのかということを１点お聞かせください。そのときのやりとりの中でも、１０年間というのは、結構スパンとして長いので、途中で見直したりしないのかとお伺いしたところ、随時見直していくようなことを言われていたのです。これは、もうつくられているのでしょうか。","respondent":"大串福祉計画課長","answer":"今回につきましても、社会福祉協議会では、それを予定しています。ただ、もしかしたら、同じスケジュールでというか、年度遅れという形はとらず、同時進行の形でつくっていこうといった意向も、社会福祉協議会から示されているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域福祉計画推進委員会というのは、介護制度とは全く関係ない別のメンバーで１年間に何回という形でされているのですか。１年ごとに検証しているということでしたら、その検証の中身みたいなものは、公開というか、まとまって私たちが見ることができるものがあるのかどうかということも、少しお聞かせいただきたいと思います。この母数が何なのかということをお聞かせいただきたい。","respondent":"大串福祉計画課長","answer":"いずれにしましても、新しい計画ができ上がりましたら、それは当然ホームページ上での公開するといったことも対応してまいりたいと考えているところです。それから、アンケートの母数です。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このアンケートのところには、「統計処理後の調査結果は、品川区の広報紙やホームページにて公開いたします」と書いてあるのですけれども、そのこととは違うのでしょうか。それが１つです。それから、これからつくられる地域福祉計画策定委員会というのは、ぜひ公開にしていただきたいと思うのですけれども、その点もあわせてお聞かせください。","respondent":"大串福祉計画課長","answer":"その形は、今検討している段階です。そのままを出すのか、それをもとにして、ご検討いただいた結論として、あるいは議論の結果として出すかというのは、来年度、少し考えていきたいと考えています。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このアンケート調査のお願いのところに書いてある「統計処理後の調査結果」というのは、アンケートそのもののことではなくて、全てのこと、計画そのものという意味なのですね。これを見たら、アンケートの調査結果なのかなと思ってしまったのですけれども、わかりました。策定委員会のほうは、ぜひ区としても公開という方向にしていただくよう要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今の質問に関連して、この地域福祉計画推進委員会についてですが、今回、高齢者、障害者、児童というところまで、地域福祉計画が盛り込まれてくる、そちらのほうまで波及していくものになってくるのかなと思うのです。それで、今、１０人いらっしゃるというところに、こうした高齢者、障害者、児童の部分に関連する方も、もう既に入っているということなのでしょうか。","respondent":"大串福祉計画課長","answer":"当然、我々といたしましても、これをつくるに当たっては、多岐にわたるものだと思ってあります。障害者、児童、高齢者といったところですので、庁内連携というところでは、そういった検討組織といいますか、検討する会議体はつくっていきたいと考えているところです。","id":"exchange-005"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"わかりました。そうしたら、地域福祉計画推進委員会とは別に、全庁連携した会議体がつくられるということになってくるのでしょうか。先ほど、スケジュールも聞かれていたのですけれども、全庁の連携会議体というものが先に開かれて、その後の地域福祉計画推進委員会という形になるのか。そこももう少し教えてください。","respondent":"大串福祉計画課長","answer":"したがいまして、その委員会が始まる前には、関連部署との検討組織、そういった会議体を開催させていただいて、その中で一定程度のご意見をもらいながら、策定委員会に諮っていきたいと考えているところです。","id":"exchange-006"},{"speaker":"若林委員","kind":"提案","question":"来年４月施行の社会福祉法の中で、これまで任意だったものが努力義務と国で定められましたけれども、この国の意図はどこら辺にあるのか。区はどのようにご認識されているか、１つお聞きします。「ご意見、ご提案」というものもありますけれども、なぜこのような問いにしたのかというところ。区の策定に当たって、区民の意見を反映するための問いの意図を少しお聞かせいただきたい。","respondent":"大串福祉計画課長","answer":"区民の皆様方に、その担い手という形、あるいは担い手に対してのイメージを聞かせていただいた上で、回答をいただきながら、区としては、そういったものをどのような形で共生社会の実現に向けて形づくっていけるか考えていきたいということで、設問をつくらせていただいたです。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"中身の問いは１７問、多岐にわたるというところで、フォーカスしている部分はわかるのです。これは、要望でお答えいただければ。全部言っているとあれですけれども、アンケートの２ページ。そこら辺をもう一回しっかり見直していただいて、せっかく５,０００名の方に送るので、いっぱい返送していただきたいし、そのためには、わかりやすいアンケートにしていただきたいという要望についてお答えください。","respondent":"大串福祉計画課長","answer":"ただ、設問につきましては、なるべくわかりやすいように、また、お答えしやすいようにといったところで、精査をさせていただいたつもりです。こういった形でご回答いただければなと考えているところです。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"もう一回言わせていただくと、５ページの３．「バリアフリー＊や」というところの説明文で、最初の２行、これこそ日本語としてどうなのかいうところを、もう一回読み返していただいて。そういう時代に入っていると思うので、そこはもう一回しっかり、課長だけの問題ではないかもしれませんけれども、これも要望になります。ご所見があればお願いします。","respondent":"大串福祉計画課長","answer":"確かに議論させていただいたところです。例えば、ご指摘いただいた５ページのバリアフリーです。これも、非常に悩んだところです。国の文献や他自治体の事例など、さまざま検討させていただいたところです。そうした中で、このアンケートの中におさめるというのが、まず１つ。","id":"exchange-009"}]},{"id":"topic-02","title":"障害児福祉計画策定実態・意向調査結果報告","agenda":"障害児福祉計画策定実態・意向調査結果報告","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは、３があるのか、それとも３を抜かして４にしてしまったという単純なミスなのか、その確認をさせていただきたいと思います。それから、１０２ページや２１５ページも、支援施策についてのご意見・ご要望というところも、「行政施策・体制について」という大きなくくりだけなので、どういうご意見やご要望があるのかという中身が、このままだと具体的にわからないと思うのです。もう一つ、６３ページ。","respondent":"飛田障害者施策推進担当課長","answer":"アンケートを送付する前に、質問の仕方について、相当内部で検討し、お子さんの様子についてお知らせくださいというところで、あまり障害について濃くしないようにしたのですが、なかなかそこのところは難しかったのかなと思います。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回は、アンケートの報告書（案）なので、もう少し自由記載欄の中身を具体的に書き込んで、どんな中身を要望しているのか、どんなことを心配しているのかという中身までわかるような形にぜひしていただきたいということで要望したいと思うのですけれども、いかがでしょうかというのが１点です。こういうニーズというのは、今度の計画の中に反映されていくことになるのかということがまず１点。もう一つ。","respondent":"飛田障害者施策推進担当課長","answer":"こちらについても、区内で調整しながら情報提供していく必要があるかなと考えております。最後に行政の職員体制のところですが、専門職のところなどは、今後また検討していく必要があるかなと考えております。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すごく簡単な答弁でよくわからないのですが、時間が押してしまっているということなので。この結果について、区としてどう受けとめ、どう改善しようとしているのかについて、先ほど少しご答弁がなかったのでお聞かせいただきたい。保育所等訪問支援にしても、周知の仕方というだけではなく、サービスの提供体制というのも求められていると思うのです。その点についてもお聞かせいただけたらと思います。","respondent":"中山障害者福祉課長","answer":"現在、障害児のほうは、指定特定相談事業所は５カ所あるのですが、実際のところは区１カ所で策定をしています。これについては、区から地域へ下ろしていく予定ですので、その手法、方法について、関連の相談事業所と連携をとりながら、具体的に考えていければと考えています。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/549442?Template=document&Id=3490#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":24345,"voices":42}},{"id":"h29-20171106-8","meetingId":"h29-cm11","date":"2017年11月6日","dateIso":"2017-11-06","committee":"建設委員会","time":"午後 １時００分～午後 ４時１６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","topics":[{"id":"topic-01","title":"大崎駅西口Ｆ南地区（大崎三丁目地区）再開発計画に関する都市計画案","agenda":"大崎駅西口Ｆ南地区（大崎三丁目地区）再開発計画に関する都市計画案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今後の予定というところでありますが、少しおさらいさせてください。それとあと都議会でも条例の議決などがあると思うのですけれども、それぞれどのような関係と手順になるのか、改めてもう少しご説明いただきたいということが１つです。それと、ここが大事な点だと思うのですけれども、区としては説明会を開いた結果、その地域住民から計画の理解を得たと考えているのかどうか、ご認識を伺いたいと思います。","respondent":"稲田都市開発課長","answer":"すみません、その１０月１０日の説明会の状況です。７７名の方がお集まりいただきまして、意見を活発に出していただきました。８時半に終了予定で考えておったのですけれども、意見活発に出まして９時過ぎぐらいまでかかったです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"これは数的に合わないのですけれども、それはどのように考えたらいいのかお伺いしたいということと、それと意見書が２４１通で賛成６１件、反対１８０ということで、圧倒的に反対のほうが多いということで、これで先ほど理解を得られたと考えているのですかと聞いたのですが、配慮はされていると思っていると言っていましたけれども、理解を得たということかどうかというのは全然答弁がなかったのです。","respondent":"稲田都市開発課長","answer":"すみません。条例の改正ですが、これは１定にかけていく予定です。都市計画の決定とはまた別物で、建築に伴う条例改正というところで、地区計画条例を改正していくです。それから署名と意見書の関係です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこは、日照の点では１点お伺いをしたい。なぜ１４９メートル、３９階建てにならないといけないのですかと、そういう観点で何度も何度も質問を出されていました。本日はたくさんのいろいろな方の立場の傍聴者もいらしていますけれども、当日答えがなかった、なぜ１４９メートルにしなくてはいけないのですかという質問に対して、ここでびしっと明確にお答えいただきたいのですが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"風環境や避難所等々の話ですが、風環境におきましても、風洞実験、シミュレーション等を行いながら、対策等も防風樹林、防風植栽ですか、そういうところも考えながらやってきており、その住宅地等々の今の範囲で抑えているということでございまして。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"それは伺いたいと思います。ここの大崎駅西口に５００戸相当の住戸をつくらなくてはいけない、そういう理由は何かあるのですか。でも私は、住民の方もそうだと思いますけれども、区報でお知らせすることを別に否定しているわけではないわけで、なぜそれ以外に周辺地域に、４月には区が指導して事業者にはやらせたというけれども、こうしたポスティングをやらないのですかというのを伺いたいと思います。","respondent":"稲田都市開発課長","answer":"それから広報です。私ども、この区報に載せまして、この１０月１０日の説明会、それから縦覧・公告の案内をするというところで進めております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと高さのところは、ちょっとこだわるようですけれども、繰り返し当日出ていた質問ですのでこだわってしまうのですが、今のご説明でも、大崎駅にふさわしいなどと言われましても、なぜ５００戸がふさわしいのかというのはよくわからないですし、率直に言って、地権者の方も含めて、地域の方がここに５００戸のマンションをつくってほしいという人はいないと思います。なぜ５００戸でないとだめなのですか。","respondent":"稲田都市開発課長","answer":"この第１７条の趣旨にかんがみまして、区民または利害関係がある方等への説明会を実施し、意見を聞いてきているというところで、地域の方々への意見というものはこういうところでお知らせをしながら意見を聞いているというところでやっているものです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"その５００戸ということにこだわっているというのは、超高層になるわけです。ですから耐震性も一応クリアできるということで、なおかつ周辺の地域への影響も随分抑えられるということだと思うのですけれども、これ２０階程度に減築をしていただきたいのですが、都市計画を変更しないとできないものなのか、都市計画を変更しなくても２０階程度に減築というのは可能なのかどうか伺いたいと思います。","respondent":"中村都市計画課長、稲田都市開発課長","answer":"規模の減築のほうから先にお答えします。行政におきましても、第１６条の権利者等にはやってきたですが、第１７条におきましても地域の区民の皆様への説明をしっかりと実施していくというところでございまして、現在のところ、公聴会を開く考えはございません。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"その中で上限をとるかどうかは事業者次第だと。ここは目標といえば目標ですから、目標だからねということで済まされればいいのですけれども、５００戸となると、どうしてもこれは高さになってしまうのではないかと思うので、この５００戸というものをぜひ外してもらいたいのです。その上で都市計画審議会にかけてほしいのですけれども、そのようなことはどうですか。お伺いします。","respondent":"中村都市計画課長","answer":"その建物の規模につきましては、にぎわいを確保するために人が多く住んでほしいエリアですとか、あるいはそれとは違って、また別の意味で低層住宅、そういったものしか建てられないように制限しているところ。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそういった意味では、やはりまちづくりの主人公は住民です。ですからこの規模に関しても、そうした住民の方々の思いというものを本当に踏まえた上での規模にしていくべきだと思いますし、そういうふうに指導していただきたいと思います。それと要望ですけれども、都市計画審議会はこういう段階ですので、私は開くべきではないと思いますし、延期していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"西本委員","kind":"確認","question":"この地区に関しては再三、幾度か委員会にかけて審議をしているわけですけれども、確認ですが、都市計画といいますか、いろいろな手順がありますよね。手順どおりにのっとった形で進んでいるという理解でよろしいのでしょうかというのが１つ。その比率というのはどのぐらいだったのかというのがわかれば、お聞きしたいと思います。","respondent":"中村都市計画課長、稲田都市開発課長","answer":"都市計画審議会へ付議するまでの手続につきましては、説明会等も開いて、そして意見書も募り、これから付議するというところで、現在手続については特に瑕疵はございません。当日の権利者と周辺の方々の割合というところですけれども、その権利者と周辺の方々の集計したデータは今ございません。ただ、権利者の方々は、全権利者数は２７人いるです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"７７人には権利者２７人、対象者が２７人ですから、圧倒的にそちらよりも多いという数が来ているわけです。順番から言うと。なぜこういうふうに住民の方々が反対だ、１８０通来るのかなと。同じ人が１８０通つくっているのかもしれませんし、それはわかりませんが。それはないと思いますけれども、ただ、賛成意見も６１件あるわけです。それについてのご見解をお聞きしたいと思いますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"この地区、防災性等に課題がございまして、この防災性の課題を解決していくことというのが大きな目標の１つです。そういう目標を達成するために、この地域の方々への理解も得ることは重要だと考えていますので、今後とも丁寧な説明等いたしていきたいと思います。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"ここをもう少し、ただ単に再開発、要は住宅の５００戸どうのこうのというような意見もありましたけれども、もっと夢のある再開発というものがあってもいいのかなと。本当にただ単にこれだけだと、何となく建物がボーンと建って、ああ、高いねと。高いとなると日照の問題があるし、風の問題も受けるしというようなことが必ずイメージ的にあって、まだ建っていませんからわからない。","respondent":"稲田都市開発課長","answer":"大崎駅西口のこのにぎわい等におきましては、地域全体での盛り上がりや特色等も出していくということも必要かと思いますので、今後の開発、また既存の開発等におきましても、その辺は考えていくです。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"この１８０という数字の反対というところに目をつけた場合に、住んでいらっしゃっていながら、この近隣で反対という方と、逆に全然住んでいないのだけれども、高層化というものに対して反対という意見をお持ちの方もいるとは思うのですが、１８０の数字に対して分析、どのように区は考えていらっしゃるのか教えてください。","respondent":"稲田都市開発課長","answer":"そういう観点での集計は、今手元にはございませんけれども、反対意見の方々の住所等を見ますと、大崎三丁目の方が多く占めているというふうには感じます。ただ、神奈川県の方だとか、北海道の方だとか、そういう方もちらほら中にはあるです。","id":"exchange-012"}]},{"id":"topic-02","title":"天王洲公園管理事務所増築工事","agenda":"天王洲公園管理事務所増築工事","exchanges":[{"speaker":"新妻委員","kind":"質問","question":"ごく初歩的なことをお伺いいたします。この増築ということですが、シャワー室も、またトイレも男性用ということなのですけれども、基本これは、ここの利用者は男性という前提なのでしょうか。","respondent":"溝口公園課長","answer":"それで既存の改修というか、既存の更衣室、そちらを今度逆に女子専用にするような形で、両方とも広いような形で、計画をしておりますので、あくまでも今回管理事務所の増築部分ということで男性ばかりになっていますが、今後予定しております既存の管理事務所の改築の中で。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問","question":"わかりました。そうすると、その後にまた、では女性用の既存のところの計画が出されてくるということですね。ちょっと時間差が出てしまうということですかね。今現在のところというのは女性が使えるように、同じタイミングで進むということですか。","respondent":"溝口公園課長","answer":"増築することによって、仮設の更衣室とか、そういったものをつくらずにいけるような感じで考えておりますので、一旦新しいものをつくって、そこを今度新たに使うことで、今既存の管理事務所を増改築していくという計画にしている、そういった形で少し今回タイム差があって。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"わかりました。不便がないように、またお願いをしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問","question":"今の増築部分と、あとは今後改築していく部分で少し細かいかもしれないのですけれども、この車いす使用者更衣室とシャワー室、こちらは男子専用ということで、現在はお考えなのでしょうか。最終的に増築が完了するまでの間は共用というか、女性も使えるような形になるのでしょうか。教えていただければと思います。","respondent":"溝口公園課長","answer":"今現在ですと、いわば人的対応とか、ほかのところを使っていただいたり、そういったところで対応していますので、ご不便をかけているところではありますが、そういったものも解消できるように、今回あわせて増築の工事の中で進めているところです。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらの、最終的に男子の方が通られるような動線になっておりますので、やはり防犯の面ですとか、女性のトイレが奥のほうにあったりするというケースも多いかと思うのですけれども、このケースの場合、車いすの方がご使用されるということで、多分手前に設計されたのだと思うのですが、そのあたりのソフト面での配慮ですとか、十分留意していただけるよう要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"今回増築の理由と、そして今回増築に係る費用をお知らせください。軽トラックがとめられるような場所だったのですけれども、その倉庫はどこに移動されるのでしょうかということと、あと、この多目的室の使われ方はどういったことを想定されているのかなと。スポーツチームのミーティングなどで使うものなのか、それとも一般的にも開放されるようなものなのかということ、以上４点お知らせください。","respondent":"溝口公園課長","answer":"２階に、既存の事務所にもミーティングルーム等あるのですけれども、エレベーター対応されていなくて、やはり全体的にまだまだバリアフリー対応が不十分なところがあった、そういったところもありました。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"女子トイレは、いずれは改修するということなのですが、広くなるという感覚でよいのでしょうかということと、それからシャワー室のほうの利用料金というものは取られるのでしょうか。これが２点目。","respondent":"溝口公園課長","answer":"既存の１３平米、シャワーブースが２基しかないものを、今回計画でいきますと、既存のクラブハウスの改修後になりますが、３３平米ほど、シャワーは５基、ですから倍以上の広さの規模にしていきたいというふうに考えて、今詳細をいろいろ詰めているところです。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"すみません。１点ありました。ここ、空調の整備はしていただけるのでしょうか。結構夏とか、非常に暑くなると思うのですが、その辺いかがでしょう。","respondent":"溝口公園課長","answer":"今のところ既存でも空調が入っておりますが、同じように増築部分にも空調を入れるように設定しています。","id":"exchange-020"}]},{"id":"topic-03","title":"平成２９年度舟運社会実験に伴う目黒川の橋梁ライトアップの実施","agenda":"平成２９年度舟運社会実験に伴う目黒川の橋梁ライトアップの実施","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。今回またライトアップ、違う場所で変えてということなのですけれども、何か全部やってほしいなという思いがあるわけなのですが、変えるわけではなく、前回のところもプラス、今年度もプラスということでやってほしいなと思うのですけれども、予算の関係もあろうかと思いますが、これはどうなのでしょう。","respondent":"持田河川下水道課長","answer":"ライトアップもなかなか、実際にライトアップする前の写真等でイメージを我々も湧かせて、それで実際に光らせてみて、ああ、ちょっとイメージと違うねというようなことも実際あるわけでございまして、やはりこういった形で少し実験的な形で、我々としても知見をしっかり重ねて。","id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"今、課長、将来的にはと言われた。大体将来的というのは、どれぐらいを見込んで、何でも言えますよ、将来的といったら。いくらでも変わってしまうのです。２年先だ、５年先だ、１０年先だといったら。いつぐらいを目標に将来的とおっしゃっているのか、ちょっと教えてください。","respondent":"持田河川下水道課長","answer":"こういった形で社会実験をしながら、ライトアップについても効果を見ながら、こういった舟運の活性化、水辺のにぎわいとあわせた形で、何とかこういったライトアップもできればいいなというような思いで。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"これ、コストはどれぐらいかかるのか。ＬＥＤを使っていますけれども、ある程度コストはかかると思うのです。去年幾らぐらいかかって、今年幾らぐらいかけようとしているのか、いかがですか。","respondent":"持田河川下水道課長","answer":"コストについてですが、昨年も今年もおおむね１,０００万円を少し超えるぐらいの金額という形です。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"要するに１,０００万円というのは、電気代と電球、ライト代ということでよろしいのですか。","respondent":"持田河川下水道課長","answer":"このライトをレンタルする費用ですとか、取りつける費用、電気代などを含めましての費用という形です。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"検討中という形で、河川をいろいろどう有効活用しましょう、水辺を利用しましょうというふうにやって、所管は違うのかもしれませんけれども、ただそこでほかの所管でやりたい、でもうちがどうのこうのというような状況だと、なかなかうまくいかないと思うのですが、既に効果があるということの結果で今年もやりたいということであるならば。","respondent":"持田河川下水道課長","answer":"実施期間、ちょっと費用的な部分も含めまして、今年度４橋という形にしているものです。今言われたように攻めのというようなお話ございましたが、やはり我々も舟運、一定の目標として２０２０年オリンピック・パラリンピックということも考えているところです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"にぎわい創出の効果を検証というと、どういう感じでにぎわい創出の検証というのは行われるのか、実際のところを教えていただければと思います。","respondent":"持田河川下水道課長","answer":"１つは昨年実施したのですが、船にお乗りになったお客様ですとか、事業者にアンケート、インタビュー等を行いまして、例えばそれはよかったのか、どうだったのかということを聞きながら、その効果を見るというのが１つになります。","id":"exchange-026"},{"speaker":"いながわ副委員長","kind":"質問","question":"このライトアップにしても、土木系のホームページというのですか、どういう形でこれをＰＲするのか、そうするとやはり観光協会とか。そもそも社会実験なので、これがどういう状況になるかわからない中で、余りお金をかけてＰＲしても、行ってみたらもう終わっていたということも中にはあろうかと思いますので、それを今後どういう視点で考えられていくのかということを教えてください。","respondent":"持田河川下水道課長","answer":"当然観光関連の部署との連携というものは大事でございまして、今回みんなのイルミネーションという１つのイベントと期間を合わせて我々も社会実験を行うということで、文化観光課のほうとも事前にこういった内容でやりますよというようなことは。","id":"exchange-027"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"先ほど申し上げたようにしっかりと連携をとって、何かイメージが土木だと、どちらかというとシールドマシンの話とか、そっちのほうがすごく合っているなと思うので、全然ハード面、ソフト面と全く、難しい部分があろうかと思うので、しっかりと連携をとって、わからないところはしっかりわかる部署に聞いてやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"平成２９年度区内一斉防災訓練の実施","agenda":"平成２９年度区内一斉防災訓練の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと避難所ですと、これ細かい話になってしまうのですけれども、やはり一人ひとりのスペース確保と、あと寒さ対策ということで、段ボールベッドのようなものというのがやはり必要だと思うのですが、その辺というのは区として現状としては用意しているのでしたかということを２点目お伺いします。","respondent":"古巻防災課長","answer":"それから２次避難所の開設の訓練、これちょっと具体的な中身、まだ詰め切れていないのですけれども、基本的には避難所の訓練と連動しまして、避難所からの名簿の受付の段階で２次避難所に避難する必要がある方が出て、それに対して本部のほうで対応して。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"必要な数用意できるように推進していただきたいと思います。それとあと２次避難所についてもかなり大事な点だと思いますので、毎年積み上げていく必要があると思いますし、こちらもぜひ経験を重ねていただければと思います。ですからその辺、連絡会議に入ってきた区の方々の情報というものを区の全体としてはどのように集約して把握して、現状分析していらっしゃるのかということをお伺いします。","respondent":"古巻防災課長","answer":"訓練の実施の状況につきましては、事後に防災協議会の会長連絡会というものを開いております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"さっき聞けばよかったのですが、すみません。避難所開設訓練のところで、区の職員の実際の動き方というもの、当日の。ちょっとお伺いしたいなと思います。","respondent":"古巻防災課長","answer":"当日の動きですけれども、まず参集する職員というものがあらかじめ動員計画の中で定められておりますので、その職員が避難所のほうへ参集をいたしまして、町会の方、避難所連絡会議の方々と連携しまして、開設の受付であるとか。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"今お話出ましたボランタリー・アーキテクツ・ネットワークとの協定のお話で、発災時には段ボールの設備を提供してくれることかと思うのですけれども、ベッドは今回やむを得ないとしましても、この委員会でも何回かお話が出た間仕切りの段ボールの設備を実際見てみたい、使いたいという区民の方もおられるかなと思うのですが、今回の訓練でその段ボールの間仕切りというものは導入はされないのでしょうか。","respondent":"古巻防災課長","answer":"具体的にはまだそこまで、協定を締結したばかりということもありまして話は進んでおりませんで、日頃からも幾らかそういった連携ということを進めていければということは所管としても考えておりまして、今後は努めていろいろ先方と話はしていきたいと思います。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"こういうことに気をつけて行ってください、おそらく訓練の、この４の(1)なのでしょうが、これだけではなくて、今までこういうことができていなかったので、今回こういうことをテーマにしてやってみましょう、それの結果はどうだったのでしょうかというような、いろいろマニュアル等々の整備もしなければいけない中で、そういうきちんとしたゴール、なぜやって。","respondent":"古巻防災課長","answer":"今回全体で５０カ所のうち４３カ所で実施をするということで、地域によって全部の避難所でやるところと、全部ではなくて一部でやるところというものがございまして、これは地域の考え方というものが１つあるのですけれども、まず今年で一斉防災訓練ですが、６年目になる。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"２日目以降の訓練の状況だということをある程度区分けしていかなければいけないのと、それが地域の人全員がここに避難できるわけではないわけですから、そこもきちんと押さえた形でやらないと、なかなかこれ、全部そこに行けば何とかなるのねというふうになってしまうので、自分たちで備えをしなければいけないですよということの前提の上に避難訓練というものがあるので。","respondent":"古巻防災課長、曽田災害対策担当部長","answer":"一斉訓練の意味というところですけれども、本部訓練との連携ということでいいますと、今年度については、先ほども避難所の開設といったところのための情報、こちら避難所のほうからもらうというような流れの訓練を予定しておりまして。そういうところで、あとは連携ですけれども、今回は要援護者、これの情報をそれぞれの避難所で確認をさせて、その情報を災害対策本部でとって、それでもって２次避難所、福祉避難所、今後どのようにしていくのだと。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"もう訓練は、品川区はかなり進んでいるなと思っていますし、これからもお願いしたいところですが、ただその考え方がいろいろあるということを隅々まで知っていただきたいと思うのです。いろいろな経過の中で、今年はこのようにやっていきたい、本部の動きとしてこのようにやっていきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"新妻委員","kind":"質問・要望","question":"すみません。１点だけ確認します。八潮地域の八潮学園が医療救護所になっておりますが、今回この一斉訓練の中には、ここは入っていないのですけれども、その八潮における医療救護所の訓練のところでは、今回はどのようにされるのか、教えていただきたいと思います。","respondent":"古巻防災課長","answer":"学校医療救護所の開設に関して、訓練に関してですが、今年度につきましては、去年学校医療救護所の開設というところで訓練項目に１つ入れておりますけれども、今年度はメニューの大きな目標というか、タイムラインが発生から２日目程度までということで考えておりますので、今回。","id":"exchange-036"},{"speaker":"いながわ副委員長","kind":"質問","question":"すみません。本部も参集してからですから、この９時というのは何か準備があるのですか。訓練の前に。どうして９時に設定したのか。同時でもいいのではないかなというのが。その趣旨などに、例えばどこで地震が起きて震度何の地震が起きましたという中で、被害想定というのですか、そういうものは訓練で必要なかったのでしたか。何か今まであったような気がしたので、その２点。","respondent":"曽田災害対策担当部長","answer":"２日目以降のことを。したがってそこで時間のラグがありますので、昼食などにあてまして、午後からは２日目のことを検討しようということとしておりますので、ここは３時としているものです。","id":"exchange-037"},{"speaker":"いながわ副委員長","kind":"質問","question":"要は、なぜ質問したかというと、何時に地震が起きて私たちは避難するかと。たしか去年の資料には入っていたような気がしないでもなかった。たしか５時に地震が起きて、ではそこからスタートしてやりましょうというようなものがあったと思いますので、それらもちょっと詳しく資料には書いておいていただいたほうが、こういう質問をしなくてもよかったのかなと思いますので。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-05","title":"本日は環境対策に関することのうち、環境三計画の改訂","agenda":"本日は環境対策に関することのうち、環境三計画の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"改訂協議会の人数と肩書等があれば教えていただきたい。それと、説明を伺ってちょっとわかりづらいなと思ったのが、エネルギー使用量は減っているのだけれども、温室効果ガスは増えているというところが繰り返しあったのですが、ちょっとその辺がわからなかったので教えてください。","respondent":"小林環境課長","answer":"区民公募の方がしっかりと入っているということで、区民の方のご意見、それから情報については十分発信できるかなというふうに考えておりまして、現在のところ説明会を開く予定はございません。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"今のご説明を聞いて。業務部門への対策というものを打ち出すべきだと思うのですけれども、いかがでしょうか。業務部門では実際排出の内訳というものはどうなっているのか、それもちょっと伺いたいのですけれども、といいますのは、やはりすごく絶対量が増えているというのは、オフィスビルが増えているということなのです。ですから私は言っているのですけれども、いかがでしょうか。","respondent":"小林環境課長","answer":"やはり国、都、また区がそれぞれ連携し合いながら、特に国も都も新たな目標値というものを定めているところですので、その中身を十分精査した上で、区として何％に持っていくべきなのか、今目標値を定めている、検討を進めているといったところです。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺います。やはり安易に目標を下げるのではなくて、区内の区民・事業者・区が連携して、ＣＯ２排出絶対量の削減を文字どおり達成すべきなのではないかと。最低限２００６年度比２５％削減というものは、これよりも下げるということは私はやっていけないと思うのですけれども、そのような数値目標にしていただきたいと思うのですが、いかがでしょうか。","respondent":"小林環境課長","answer":"目標値を下げることというのは基本的にないと考えておりますが、やはりエネルギー施策が大きく変わっている部分ではありますので、その中で以前の状況と今の現状が大きく変わっているといったところで。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは外さないということで、よろしいのでしょうか。ちょっと確認させていただきたい。それとあわせて、ほかのところにもいきたいのですけれども、サーマルリサイクルというものを今やっていますが、これＣＯ２の発生抑制ですとか、大気汚染の観点から見ると問題がある施策だと思うのですけれども、これはちょっとこの環境計画の中で見直しをかけていく必要があると思うのですが、いかがでしょうか。","respondent":"小林環境課長、工藤品川区清掃事務所長","answer":"床面積当たりの減少につきましても、先ほどご説明しましたように、繰り返しのご答弁になりますが。私のほうからはサーマルの件につきましてご説明いたします。水質浄化の件ですが、今、現状の環境計画の中でも水質改善すべく。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"ごみの発生抑制という点、全てのプラスチックのごみの回収をしなければいけない、やってほしい。これの実施。そういった国への働きかけなど、こうした取組みもあわせてやるべきだと思うのですけれども、ぜひ計画などにも織り込んでいただきたいと思いますが、いかがでしょうか。そうでないと進まないのではないかと思うのですけれども、そうした考えをぜひ入れていただきたいのですが、いかがでしょうか。","respondent":"小林環境課長、工藤品川区清掃事務所長","answer":"一方で雨が降った後のにおいの問題等々、いろいろとありますので、さまざまな対策は今後所管と連携を図りながら進めていければというふうに考えてあります。そういった中、３ページ目の左側の基本目標のところに、やはりごみの発生抑制に努め、ごみの減量化と資源化に取り組むという形で記載しております。こういったものの中で、総合的に取り組んでいくです。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"もちろん学識経験者、区民公募の方のお話も聞いていますが、直接そうした方々の案に対して意見を募る意味でも、しっかりとこの計画をまず、こういう計画だということを理解していただかないとやはり意見も出ませんから、これは繰り返し繰り返し、ぜひ求めていきますが、区として何かかたくなに説明会をやらないというスタンスがあるのかどうかわかりませんが、私は非常にそれは遺憾というか、残念なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"この現行の計画が３種類あって、それがわかりづらいということから２つにまとめられるということなのですが、これはできた経緯がちょっと違うなというのがあって、そしてこれを２つにまとめるということなのですけれども、国、都の動向に合わせる形でまとめる、それも含めてこういう形になっているのか、経緯と今後のまとめ方、考え方をもう一度教えていただきたいということが１つと、それから基本目標。","respondent":"小林環境課長、中村都市計画課長","answer":"先ほどご説明いたしましたように、その３つの計画がある中で、名称、中身、それぞれの関係性が非常にわかりづらいというご意見、区民の方を含めていろいろといただいているところです。その環境対策の中でどういった内容として盛り込むかは今後の検討になると思いますけれども、そういった形で公共交通機関についても考えていかなければいけないというふうに考えてあります。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"そういうものを何か品川区も、私たちも考えなければいけないのでしょうけれども、そういう区民の人たちが具体的な行動としてイメージしやすい、自分たちのやっていることが環境にいいのですよ、ＣＯ２削減になるのですよというようなものがリンクしてイメージできると進むのかなというようなことがあるので、ここの支援をぜひ、私たちも考えなければいけないと思うわけではありますが、ぜひそういう形で。","respondent":"小林環境課長","answer":"３つの計画のそれぞれ策定経緯がありますが、先ほどご説明しましたように、環境計画というものが一番大きなもとの計画です。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"今のご答弁の中で、第二次環境計画が上位なのですね。その下に地球温暖化対策地域推進計画というものがあるという認識でよろしいのですか。違いますか。というのは、期間が第二次の場合は期間１０年で平成２５年からなのです。真ん中のものは平成２２年からなのです。これはどういう関係があったのでしょうか。すみません。","respondent":"小林環境課長","answer":"実行計画につきましては５年間の計画といったところで、これ５年間、１０年間というのは１つの計画をつくっていく上で、国のほうから示された基準のようなものがございまして、そこの中で１つ定めているです。","id":"exchange-047"},{"speaker":"横山委員","kind":"確認","question":"何点かお伺いをしていきます。こちらの１ページ目の２の(2)、こちら未着手の取組みが９事業あるということなのですけれども、こちらはどのような事業が未着手になっているのでしょうか。確認なのですけれども、平成２４年、平成２５年の増の原因というのは、こちら資料に記載してある東日本大震災以降の国のエネルギー政策の大幅な転換などといったところで捉えてよろしいのでしょうか、お願いします。","respondent":"小林環境課長","answer":"９事業の点ですが、例えばよくありますのがカーボン、いわゆる他自治体から何か買い取って温室効果ガスを下げるとか、あるいは他自治体とかで再生可能エネルギーを設置するとか、要は他自治体との連携といったところが非常に大きな部分かなと考えています。","id":"exchange-048"},{"speaker":"横山委員","kind":"質問","question":"ご説明ありがとうございました。もう少し踏み込んだ質問を何点かお願いしたいのですけれども、例えばグリーンリースの普及支援ですとか、あとは水素の利活用をした先進的なモデルのようなものは区内で何かありますでしょうか。もしわかれば教えていただけたらと思います。災害廃棄物の処理に関して、これは計画の中には入っているのでしょうか。お願いいたします。","respondent":"小林環境課長","answer":"それから災害廃棄物の処理等々についてなのですが、この計画の中では、現在のところは考えていないところです。それらにつきまして、状況に応じて所管等と連携を図っていきたいというふうに考えてあります。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"１点、すみません。家庭部門に対する取組みの中にＬＥＤの推進というものは入っているのか、入っていないのかだけお聞きしたいのですけれども。","respondent":"小林環境課長","answer":"ＬＥＤにつきましてですが、現在推進している最中ですので、それら継続するものについては継続するということで、計画のほうにはしっかりとのせていきたいと考えております。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"今、庁舎内はＬＥＤに順次かえていくという形で進められていると思うのですが、やはり家庭内もしていかないといけないと思うのです。何かすごく具体的な行動指針の１つにもなれるのではないかなと思っているので、ぜひともしっかりと推進するという形で、拡大する形で行動指針に入れていただきたいなと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"２つなのですけれども、１つが本文で「このたび、説明会で頂いたご意見等を踏まえて、それぞれ都市計画案を検討いたしました」とありますが、前回の都市計画素案の説明会の意見を踏まえて、何か変更したことはあるのかないのか、伺います。ここではポスティングをやるということなので、ぜひ大崎のほうでもやるべきだったのではないかと思うのですが、その辺は何なのでしょう、違いは何なのか教えてください。","respondent":"中村都市計画課長","answer":"説明の対象の方々については漏れはないと考えております。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとお伺いしたのは、ポスティングをこちらはするという話が１１月中旬と言っているのですけれども、なぜ大崎のほうではポスティングをやらなくて、こちらではポスティングをやるのか。いや、もちろんポスティングはいいのです。やってほしいのですけれども、なぜそのような事業によって違いを出しているのかということがわからなかったのでお伺いします。","respondent":"中村都市計画課長","answer":"再開発のほうにつきましては、こちらはそれぞれの地権者の方がこの計画について発案をして、そしてそれぞれの地権者の方が、例えば土地を貸している方ですとか、その他関連の権利者に対しては。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと納得いく説明ではないのですが、私は別に戸越がずるいぞと言っているわけではなくて、ぜひ影響を受けるという点では、事業は違うといえども、同じでありますから、ぜひ周知の努力というものはさらにしていただきたい、改善をお願いしたいというふうに要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"安藤委員","kind":"意見","question":"立会川のほうでは高潮のほうで避難勧告まで出たと、ちょっと大変な状況だと思うのですけれども、こちらのほうはそういった電話対応というものはやっていないのか、その辺をお願いしたいと思います。","respondent":"古巻防災課長","answer":"同時に広報車で周辺を広報してまいりました。高潮のほうにつきましては、そういった世帯の把握等がまだ十分でございませんので、周辺を広報車で回って周知をするという形で広報を行ったという状況です。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。すみません。避難情報緊急通知コールというのは、何軒かけたのですか。それをちょっと。対象世帯のうち何軒にコールされたのか、それをお伺いしたいと思います。","respondent":"古巻防災課長","answer":"避難情報緊急通知コールの対象世帯につきましては、土砂災害と浸水、目黒川の浸水被害で約７００軒ほど、今登録がありますが、土砂災害だけというのは、今ちょっと数字を持ち合わせておりません。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/169461?Template=document&Id=4216#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":62389,"voices":169}},{"id":"h29-20171106-9","meetingId":"h29-cm11","date":"2017年11月6日","dateIso":"2017-11-06","committee":"文教委員会","time":"午後 １時００分～午後 ３時１４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","topics":[{"id":"topic-01","title":"学事制度審議会中間答申の報告","agenda":"学事制度審議会中間答申の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"学事制度審議会の中間答申が出されましたけれども、まず学校選択制についてお聞きしたいのですが、学校選択制が始まってから１７年たつわけですけれども、その検証がしっかりと行われていないのではないかと思います。このようにさまざま問題点がありますけれども、教育委員会が考える問題点は、改めて先ほどの説明のほかプラスアルファがあれば伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"学校選択制に関する問題点ですけれども、基本的には審議会での現状・課題の認識と一致しているものですので、先ほど説明申し上げたとおりです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"一致しているということで、私が挙げたものも含めていろいろあると思うのですけれども、そういったことは問題ではないと考えていらっしゃるのかも伺いたいと思います。やはり、求められているというのは、選択制の廃止ではないかと思うのですけれども、この点を伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"それぞれ地域の中の立場によって見方も異なりますので、反対されている方もいらっしゃるのは事実ですけれども、一方で、先ほど申したとおりお子さんをお持ちの保護者から見れば、選択「する」ことではなくて、選択「できる」環境というのが非常に大事なのだと考えておりますので。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"あわせて、この学校選択制と全体を見渡しても、中間答申について、子どもの視点というのでしょうか、子どもにとってどういったメリットがあったのかが明確に記載されていないと思っているのですが、教育的な部分で子どもにとってよかったということは、どういったことがあったのか伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"そういった中で、地域の中でのお子さん方とのつながりというのは、なかなか以前から見ると難しいというご意見をいただきながら、今回学校選択をする中で、それぞれ親御さんの考え方やご本人、特に中学生ぐらいになりますと、クラブ活動等で学校を選ぶ方もいらっしゃいますので。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこをしっかりとつかんでいただきたいと思います。それから、学校規模について伺いたいと思います。あわせて、長期間とはどのくらいの期間を考えていらっしゃるのかも伺いたいと思います。別のところに、小規模校は標準規模以上の学校より１人当たりの運営経費が高くなるということも書かれていますけれども、経費がかかるから統廃合していこうということなのか、伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"そういった状況になった場合には、何らか考えていく必要があるのではないかという議論がありましたけれども、審議会としてきちんとした期間を定めたものではございません。それから、その対応において統廃合を考えているのかというご質問です。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、後段の経費についてはあくまで試算だということで、つまり、経費がかかるから統廃合していくということは考えていないと受けとめていいのか、改めて確認させていただきたいと思います。","respondent":"篠田学校計画担当課長","answer":"統廃合につきましては、現状、教育委員会として積極的に統廃合を進めるという考え方は持ってございません。ただ、ここの答申の中にも、小規模校だからだめだとは一言も書いてはございません。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"最後の経費のところで、教育ですから、機会均等もありますし、しっかりとどの子にも教育を保障していくということが必要になってくると思います。そういったところをしっかり配慮していただいて、また、積極的には統廃合していくことは考えていないということでしたけれども、消極的にも考えていかないように、ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"それと、先ほどののだて委員の質問とも重なるところもあるのですけれども、中間答申の３ページの「転機を迎える学校教育」の中に、「新しい時代に求められる学校の役割」と記述があるのですけれども、ここでいう新しい時代というのは何を指しているのかを伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"子どもたちを取り巻く課題が複雑化・高度化しているといったところですけれども、こちらに関しましては、例えばスマホやＩＣＴの進捗等によりまして、子どもたち同士のコミュニケーションのあり方がこれまでと比べていろいろ変わってきていると言われていますし、その他にも。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、ぜひ調査していただき、その数字をお知らせいただきたいと思いますので、質問をしました。せっかく公表しているわけですから、意見を求めたいという思いもあって公表しているのだろうと思うわけで、この件に関する区民の関心度合いも含めてわかるところなので、把握すべきだと思っていますが、その点についてどうなのかを伺いたいと思います。そこも確認をしたいと思います。","respondent":"篠田学校計画担当課長","answer":"その前提として何があるのかというと、先ほどのこの答申前半もそうですし、またパンフレットの１ページ目にあるような、品川教育ルネサンスの取り組みといったものが前提となる中で、これを実現していくために。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"プラン２１の教育効果がどうだったのかということを分析したものがあれば、教えてほしいと質問したのですけれども、答弁がなかったのではないかと思っているのですが、分析していなかったのだったら、ないと答えていただきたいと思うのです。そのことをもう一回改めて伺いたいと思います。この結果について、教育委員会はどういうふうに捉えているのか、そこを伺いたいと思います。","respondent":"篠田学校計画担当課長、熊谷指導課長","answer":"ですので、今回の見直しに当たりましては、そういったさまざまな考えをどういった形で調和させていくかといった中で、今回、ブロック選択制から隣接校への選択制といった考え方が打ち出されたものです。教育委員会が行っている児童・生徒、そして保護者アンケートの中でも、品川は教育に力を入れていると思うと回答された保護者は、昨年度９４％でした。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"その点について伺いたいと思います。先ほど熊谷課長からご答弁に、子どものあるべき姿というところがあったので、それについて伺いたいと思ったのですけれども、まず子どもの姿がこうだから、こういう手だてが必要だし、こういう教育方針が必要だという教育委員会になっていただきたいと思っています。そういう考え方が、この表現の裏にはあるのかないのか、この点を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"まだ幾つかあるのですけれども、とりあえずは終わりにしますが、国に認められたということを、私は頭ごなしで悪いとは言わない、さっき、子どもの姿がまずあるべきだと思って質問したので、そういうふうに改めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問","question":"先ほどのお話の中で、まず学事制度の枠組みが整理をされたということは、私としては理解できます。滑らかな接続というところで、小１プロブレムや中１ギャップと言われる課題が解消してきているのではないかとイメージしているのですけれども、その点は、この学事制度と小１プロブレム、中１ギャップというところでは、どのように捉えていらっしゃいますでしょうか。","respondent":"大関教育総合支援センター長","answer":"今、こんの委員より小１プロブレム、中１ギャップについて、効果がどのようにあるかというご指摘をいただきましたが、教育委員会といたしましても、小中一貫教育をこれまで進めてきた成果がまさにあらわれていると認識しているところです。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"なので、今、不登校の出現率というお話もありましたけれども、ぜひそうした生活指導面についても、こうした学事制度の審議会で出された答申を、今後進めていくに当たって、非常に期待をされるところであると思いますので、ぜひその点、何かありましたらお答えをいただきたいのですが、私は期待をしたいというところですけれども、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"まさに小学校教員と中学校教員が一緒になって、課題を毎月考えているのが、本区の生活指導の対応ですので、現場の教職員と教育委員会が一体となって、これまでの適応指導教室の成果と課題を見据えて。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問","question":"ぜひよろしくお願いします。その一方で、枠組みを再編することにより、今まで連携していた学校との連携がなくなる、あるいはこちらの学校と連携というように簡単に連携をパチンと切って、別の学校と連携というのは、なかなかしにくいと思うのですけれども、その辺の連携のあり方は大丈夫なのでしょうか。すごく心配なのですけれども、その辺はどういうふうにお考えでしょうか。","respondent":"篠田学校計画担当課長","answer":"それは、小学校と中学校の関係が１対１になっていないというところがありますので、それまでの連携と違った形もなくはないですけれども、できるだけ今まで築き上げてきた実績をきちんと担保できるような形で整理していきたいと考えているところです。","id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"学校選択制についてですけれども、今回ブロック内で分けられるということなのですが、中間答申の２５ページから２７ページに記載されている今後の学齢人口の将来推計で、小学校では平成３４年と３５年、中学校では平成４０年、４１年と、ピーク人口がばらばらというか、各地域によって異なっているのですけれども、これはなぜ時期が違うのかについて伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"つきましては、抽選にはならないということです。ただ、例えば突然、極端にお子さんが増えてしまった場合には、それまでの学区域ではなくて、学区域を変えたりなど、何らかの制度的な変更等により、必ず受け入れる体制をつくっていくことになるものです。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"この災害時・緊急時の避難拠点は、どういったことが求められているのでしょうか。避難の受け入れ態勢についてですが、以前質問したかと思うのですけれども、緊急避難道路を通って避難所に向かってこられる方、地域があると思うのですが、そうしたことは、今回のブロックに分けて解決となるのかどうか伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"ただ一方で、これは町会からの声としてもあるのですけれども、同じ町会の中で２つの学校に分かれてしまったようなところがありますので、そういったところは、なかなか普段行きなれていないところに行かなければいけない方もいるのだという声をいただいていますので。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"平成３３年に鮫浜小学校の改築で、その後、随分先になっていくのですが、そのぐらいのレンジで考えていくというか、そういったことを含めた今回の答申なのでしょうか。ただ、その一方、学齢人口は急増していくのですけれども、その後ピークをすぐ迎えて、その先の人口についての課題もあるとすると、そちらも踏まえると非常に難しい判断に迫られると思うのですが、そのあたりはどうお考えでしょうか。","respondent":"篠田学校計画担当課長","answer":"それで、学校の改築ですけれども、これまでは基本的に老朽度を基準にしつつ、例えば人口の急増ですとか、そういったものへの対応も含めて、また区の実施計画の中で、毎年１校ずつ改築を選定していくということが決められておりますため。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういうふうにして見ると、人口の推移等もありますけれども、小学校などでは、かなり児童数が多いところで老朽化が進んでいるところもあるので、そのあたりを具体的に考えていくのは、ここ一、二年の中でしていかなければいけないという認識でよろしいのでしょうか。","respondent":"篠田学校計画担当課長","answer":"ただ、現在の改築に取り組んでいる学校に関しましても、取り入れられる部分としてはきちんと取り入れて、対応していくというスタンスで進めてまいりたいと考えているところです。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"本日は幾つか、手短に質問してまいります。そこで今現在、教育委員会でわかれば教えてほしいのは、最終答申が３月に出て、猶予期間を置くのか置かないのか、逆にこれは説明し出すとともに、こういうふうになるというのが先行していくと思うのです。中間答申まで出ていますから、これは間違いなく進めていくのだと思うのですけれども、どういうふうに進めていくのか、計画があれば教えてください。","respondent":"篠田学校計画担当課長","answer":"そちらと学事制度審議会の最終答申の周知のタイミングを、どういった形とするかは、実際今、私どもも内部的に検討しています。中間答申に関しまして、説明会等をやらないでという形で進めてまいりました。","id":"exchange-019"},{"speaker":"渡部委員","kind":"質問・要望","question":"ただ、一方で当分先の話を至急にきちんと報告する必要があるかというと、またそれも混乱を招くだけだと思うので、その辺は微妙なタイミングだと思いますが、時期をはかりながら進めていただきたいと思います。毎回変わったりというので大変だから、ある程度長い目で見据えて、どーんと仕掛けていかないと、やるのだったら区内一気にやらないとという思いがあるのですが、その辺の考え方はいかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"ただ、そうはいっても、１つはきちんとした考え方に基づいて整備していくことが必要ですので、今回学区域に関しましては、先ほどご説明させていただいたように、小・中学校の連携をきちんと明確化していくということで、グループ化をしていくということになるのですけれども。","id":"exchange-020"},{"speaker":"渡部委員","kind":"質問・要望","question":"本来であれば隣接していないから選べないけれども、そこへ行ったら、その中学校で部活ができるとか文化体験ができるというのがあれば、そういうのは基本的には指定校変更で積極的に受け入れられるのだということをきちんと担保できるのかどうか、教えてください。","respondent":"篠田学校計画担当課長","answer":"そういった場合、どう対応していくかというのは、これから整理していくところではあるのですけれども、一定程度きちんとした形で経過期間、経過措置を考えながら、それがどこまでという話では、まだ具体的にはお話しできないのですけれども。","id":"exchange-021"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"１つだけ。ある程度のところでいろいろと転用できるような、ある程度スパンを短くして、いろいろ転用できるような形で学校を考えるか、また長寿命化するのだったら、いろいろ付加価値をつけて他の用途にも転用できるような、ある程度いろいろな可能性を考えた構想のもとでつくるか、そういう観点というのが必要ではないかと思うのですが、いかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"具体的にどこがどうという話ではないのですが、現状では、お子さん方が増えてきているという状況がありますので、その受け入れができる体制を当然つくっていますけれども、将来的にお子さんが少なくなったときに、例えばフロア単位で別の施設として使えるとか。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"今、先生方の多忙化というのが社会問題になっていて、この問題について、学事制度の中間答申では、多忙化についてはどういうふうに解消できるのかどうか、自分の学校の特徴を出すということも含めて、先生たちの指導がかなり厳しく、準備だとかに時間がかかるという話を聞いているのですけれども、そういう問題をどういうふうに教育委員会としては考えているのか、その２つを伺いたいと思います。","respondent":"篠田学校計画担当課長、熊谷指導課長","answer":"そして区民の方から、実はさまざまなお声を寄せられるのですけれども、そういった部分の不公平感というものを指摘される声もいただくところですので、私どもとしましては、そういった部分で一定程度。それ以外の対応として、例えば学校事務システムの導入、職員カードによる勤怠時間管理等について、今、国や都でこうしたらどうだろうかと提案されているものについては、既に品川区では行っていますので、今後どうしていくかについて。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"小規模校の問題ですけれども、保護者や子どもさんに選択してもらうことを求めておいて、その結果、小規模校になってしまっているという状況に対して、小規模校はお金のかけ方が標準校よりかかっているから不公平だと。その点の考え方が間違っているのか、教育委員会の見解を聞きたいのと、経費かかっているのであれば、かけて悪いのですか。その点について、２点伺います。","respondent":"篠田学校計画担当課長","answer":"小規模校化に関しましては、まず委員ご指摘のように、学校選択の結果ではないのかということも確かにあるのですけれども、そうはいっても、この結果がこれだけの差を生んでいるということになりますと、では何らかの形で、それこそ今回、学事制度審議会の答申の中で。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"選択制をやめればいいのです。自分が住んでいるところの学校に、区域の学校に入るという制度に戻せば、こういう話は出てこないのではないですか。そういうことも含めて、広く区民の意見を求めていくべきだと思っています。そのことなしに、早計に隣接校という形で縮小したからといって学校選択制を続けるということは、やめるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-02","title":"平成２９年度移動教室実施結果","agenda":"平成２９年度移動教室実施結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回も実地調査されたときに、現場で放射線量などを測定されたのか、伺いたいと思います。あわせて、昨年の質疑の中で、特別支援学級の方も普通学級と一緒に行くという選択ができるということで、今回そういった方がいたのか、いた場合、インクルーシブ教育という面も含めて、一緒に過ごしていく中でどういった様子だったのか、わかる範囲で教えていただければと思います。","respondent":"有馬学務課長","answer":"放射線量の測定につきましては、一応、中学校も小学校もしています。それから、特別支援学級の６年生が実際何名いたかというところは、手元に今は資料がないのですけれども、大方は特別支援学級のほうで行かれている方のほうが多いのではないかと考えているところです。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"実地踏査のときの放射線の測量は、安全だったということでよろしいわけですか。","respondent":"有馬学務課長","answer":"２点目の、普通学級と一緒に行っている人数というものも、今後把握はしていきたいと思います。そして、どのような生活を送っていたかということも、学校にも確認をしながら把握をしていきたいと考えています。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"一般的にですけれども、修学旅行も含めてこういう移動教室に、経済的な問題で行けない子どもさんがいるとか、あるいはお友達関係で参加を見送らざるを得ない児童・生徒がいるとかということを聞くのですけれども、品川区の場合、そういう実態があるのかどうか、その点について伺いたいと思います。","respondent":"有馬学務課長","answer":"今年の欠席の実績ですけれども、経済的な事由ですとか友達の関係で行かないという方は、おりません。基本的には病気、体調不良等、あとは一部不登校などがありますけれども、経済的理由で行けなかったという方はおりません。","id":"exchange-028"},{"speaker":"南委員","kind":"確認","question":"そういう点で、全然なければ、それはそれですごくいいことなのですけれども、しつこくて悪いのですが、そういう関係は心配する必要がないと考えていいのかどうかを確認したいと思います。","respondent":"有馬学務課長","answer":"場合によっては本人が言いにくくというところについては、学校長にきちんと、行けなかった子に対してのフォローといいますか、そういったところの理由についてはきちんと把握していくように、今までも言っておりますけれども、今後とも。","id":"exchange-029"},{"speaker":"南委員","kind":"意見","question":"本当になければいいのですけれども、三、四年前に実際そういう相談に乗ったこともあったので、心配になって聞いたのですけれども、行かせることが本当にいいのかどうかというのは、また別問題としてあると思うのですけれども、不登校だとか、友達関係を良好に保つようなことが、教育の中できちんと手を打っていただけることを改めて願っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"非常に貴重な体験ができる学校行事だと思っていますので、無事に終わったということは、大変よかったと思います。引率の教員の先生の数なのですけれども、クラスによって、同じクラスでもばらつきがあるのですけれども、これは特別な配慮が必要な児童・生徒がいるという状況からか、それともこちらの人数には介助を行う方が含まれているのか、その辺をお聞きします。","respondent":"有馬学務課長","answer":"引率の教員の人数の算定につきましては、基本的には実施要項の中にも算定式が決まっていまして、学級数掛ける１.５プラス校長プラス保健を担当する教員ということが原則となっております。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういうときには、先ほどあったように学校の要請で、できるだけ多くの目で指導をしていただくことが必要だと思います。その点はいかがですか。","respondent":"有馬学務課長","answer":"基本的には、加配申請があったときは最大限考慮しているということですので、去年も今年もそうですけれども、それに対して拒否したということはありません。全て受け入れして、安全に楽しんできてもらおうということで、加配を認めているという状況です。","id":"exchange-032"}]},{"id":"topic-03","title":"平成２９年特別区および東京都人事委員会勧告の概要","agenda":"平成２９年特別区および東京都人事委員会勧告の概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"４ページの長時間労働慣行の見直し及び年次有給休暇の取得促進というところで、業務の見直し等について措置を講じていく必要があるということが書かれておりますが、今の品川区の状況と対策をどういうふうにやられているのか、伺いたいと思います。","respondent":"熊谷指導課長","answer":"申し訳ございません。こちらにつきましては、行政職員のことについての意見ですので、本日の総務委員会でご説明がなされているかと思います。","id":"exchange-033"}]},{"id":"topic-04","title":"平成３０年度品川区立学校教育職員採用候補者選考状況","agenda":"平成３０年度品川区立学校教育職員採用候補者選考状況","exchanges":[{"speaker":"鈴木（博）副委員長","kind":"質問","question":"たしか前も固有教員に辞退があったと思うのですけれども、受験で最終的に合格した後、辞退者が出ることを想定して、例えば対策とかということを何かご検討はされているのですか。","respondent":"熊谷指導課長","answer":"人物重視ということで一次・二次選考、最終面接を行ってきまして、最後のところで確認を行っているところなのですけれども、ただ、実際に今回辞退があった方は、中学・高校の高校で英語をやりたいという思いがあったようです。","id":"exchange-034"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"この前辞退したときは、少し人数が足りなくなってしまったと思うのですけれども、今回はそれも見込んで、辞退者が出ても別に問題がないように内定者を確定させたのですか。","respondent":"熊谷指導課長","answer":"それに合った方を、実際に名簿登載がされていたとしても、それにふさわしい方の採用のみということで行っていきたいと考えております。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"あわせて、区独自で雇っている教員の方がいるということで、先ほども３区しかやっていないということがありましたけれども、そういった状況があるので、ぜひこれを活かして、３０人学級の実現にもぜひ踏み込んでいただきたいと思いますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"２点目の３０人学級ですけれども、この固有教員につきましては、品川区の教育施策といえば市民科であったり、コミュニティースクール、地域と連携する核であったり、そういうことを推進していく人材として位置づけておりますので、３０人学級のためにとは考えてはございません。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"市民科とか、品川の教育の推進のためということですけれども、３０人学級をぜひ検討していただいて、やはり少人数学級が教育的にすぐれているということは明らかだと思いますので、あらゆる手を工夫して実現していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"もし可能ならば第二次選考の合格者９名の中に、どういう教科の方が残ったのかというところも、もしお話できる範囲があればお願いします。","respondent":"熊谷指導課長","answer":"実際に教科なのですけれども、小学校全科を持っていらっしゃる方が現段階では１５名ということなのですが、中学、高校の免許は国・社・数・理・英・美・体・家庭科、そして特別支援ということで、音楽と技術だけ持っている方がいないのですけれども、いっとき。","id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"先ほどの説明の中で、管理職の方が１名いらっしゃると言ったではないですか。区の固有教員は管理職としてどこまで行けるようになっているのですか。","respondent":"熊谷指導課長","answer":"現段階では副校長までとなっておりますので、また他区にも、これから管理職が出てくるかと思いますので、他区と一緒に国に要望していきたいと考えております。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問・要望","question":"そうですよね。いずれ区の教員の方々が経験を積んでいただいたときに、どこまでなれるかというのは、たしか話をしていて、なるべくそういうふうになれるように動いていただきたいということを要望させていただいたと思いますので、どういう形ができるのかというのを研究していただいて、進めていただければと思います。","respondent":"熊谷指導課長","answer":"そもそも３０名をということで始まった事業ですけれども、品川区の教育を推進していくためには、３０名で終わりということではなくて、継続して採用できたらということで検討していきたいと考えているところです。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/476060?Template=document&Id=4926#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":43718,"voices":124}},{"id":"h29-20171106-5","meetingId":"h29-cm11","date":"2017年11月6日","dateIso":"2017-11-06","committee":"総務委員会","time":"午後 １時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","topics":[{"id":"topic-01","title":"」を聴取いたします。 まず、「シティプロモーション動画","agenda":"」を聴取いたします。 まず、「シティプロモーション動画","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"シティプロモーションサミットの時も、教育講座に参加して、実際にどういうふうに、自治体の職員でも気軽に作れるんですよという講座に出た時に、やはり、幕の内弁当ってうまい言葉だなと思ったのですが、何でもかんでも盛り込むのではなくて、１テーマに絞ってあまり長くならないように、短くという話を聞いて、ああ、なるほどだな、と思ったので、今回、どの辺に見てもらいたいのか。","respondent":"木村報道・プロモーション担当課長","answer":"テーマに関しまして、一つ一つを短くというところについては、今回も意識してみた部分です。ただ、やはり今、動画は３分を超えるとなかなか見られないという、もう３分を超えているのですけれども、そういう部分もありますので、凝縮してつくったつもりです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"意見","question":"結構、子供のところが取り上げられていたし、商店街とか、どちらかというと女性というか、品川に住んでほしいという、子育てしてほしいという、その辺が色濃く出ていたのかなと思いました。これは、制作にどのくらい予算が使われているのか、お聞かせください。","respondent":"木村報道・プロモーション担当課長","answer":"こちらですけれども、この楽曲そのものもオリジナルの歌詞、曲でございまして、その制作費も含めまして１,５００万円程度です。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"その辺をどのようにお考えになったのか教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"動画の評判と観光者数とがリンクする、しないのところですけれども、実際には、最初もちょっとご説明させていただきましたが、区民の方のご参加をいただいて、確かに、「来てください、住んでください」というのもあるのですけれども、これを通しまして区民の方に、「ああ。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"そうすると、その効果測定というのはすごく難しいと思うのですけれども、一応、やはり１,５００万円かけたということであれば、どこかで何か考えなければいけないかと思うのですが、その辺はどのようにお考えか教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"これは１つ、シティプロモーションの事業の指標として使ってきているのですけれども、それはいわゆる区外の方がどのようなメディアを見て品川区を認識したかというようなところの調査がございまして、そちらで測っていくという部分が１つと。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはりどこかで効果は測るべきだと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"４点、お伺いします。それなので、もうせっかくそういった発信方法をしているのならば、しっかりとその動画にたどり着くように、スムーズなリンクを張っていただければと思いますので、それは要望で終わりますが、そのアクセス方法の中で、例えばどこからその動画にたどり着いているのかなどというのは分析などをされているのか、また、される予定があるのか。よろしくお願いします。","respondent":"木村報道・プロモーション担当課長","answer":"周知に関しましては、例えば大崎駅前のビジョンでありますとか、ケーブルテレビの放送であるとか、それから、区内施設に年明けから配備予定のデジタルサイネージに動画も出ますので、そちらで活用するという形で周知を図ってまいるのと、今年。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ有効活用していただきたいと思いますけれども、１点、その学校とのかかわり方で、ほんとうにダンスも今、必修科目と言うんですか、学校でも授業でダンスを取り入れられているということもあると思うので、ぜひそういった部分を活用していただいて、子供たちがそれこそ大人になって思い出として、品川区の事を思い出せるようなものにしていただければとも思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あくつ副委員長","kind":"質問","question":"それで、あと途中でタコ公園や、恐竜公園なども取り上げられていて、もう１つ、できればクジラの滑り台も入れてほしかったのですが、時間的な問題もあるのかなと思います。それで、ここからちょっと質問なのですけれども、最後の迫力がある区民とのダンスのシーン、ここでは合計３００人以上とあるのですけれども、ここは全て区民エキストラということで、公募のエキストラということでよろしいのでしょうか。","respondent":"木村報道・プロモーション担当課長","answer":"ただ、１つ、この委託先のポニーキャニオンのほうも同時にプレスリリースをしていまして、そちらのほうはいわゆるネットニュース各社でリリースがされているような状態でありますので、うちもちょっとそういう形で。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"例えばこういう調査、１ページ目の２の民間給与実態調査の内容、特別区内の１,０９９民間事業所を実地調査、調査完了７８９事業所と書いてあるのですが、例えばこういう会社名、ならびにその会社の規模、事業所の産業などさまざまな要素があると思うのですが、そういうのは一緒に報告事項として特別区人事委員会から来ているのですか。教えてください。","respondent":"黒田人事課長","answer":"特別区人事委員会の調査内容の報告ですが、統計として整理しました事業所規模ですとか、支店長クラス、事業所長クラスの平均年齢、平均給与等が幾らですというところで、調査の概要を統計処理したデータはいただいておりますが、個々の企業の情報について。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"どちらかというとアルバイトの方が、人材不足で時給の単価が上がったという話は聞いていますが、実際職員として勤労者として働いている方の給与は、品川区内ですから中小企業の方が多いのですが、そういう話は聞かないということで、大分、特別区人事委員会の報告との差が大きいような気がしますので、それだけちょっと要望として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"やはり正しい比較をしていかなくてはいけないというのが１点あると思うんですね。ちょっとそこについてのお考えをお伺いしたいのと、やはり公務員の賃金というのは、平均のレベルというところにおいては、公務員の賃金が下がると全体的にみんな下がってしまうので、やはり指標になるという捉え方をしていかなくてはいけないのではないかなと思っているので、ちょっとその辺を聞かせてください。","respondent":"黒田人事課長","answer":"今後の予定ですが、人事委員会勧告をもとに、特別区長会のほうで、職員団体のほうにこれに合わせた制度改正も含めて提案をする流れがございまして、現在、鋭意交渉を行うというところで、交渉の妥決が例年ですと１１月中旬ぐらいになりますので。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこが１点と、あとIIIの扶養手当の見直しのところでちょっとお伺いをしたいなと思うのですが、この頭に、国における扶養手当の見直しを踏まえて、と書いてあるのと、終わりのほうに、区の状況に応じた見直しを図ることが適当、と書かれているのですが、１点、ここの扶養手当、配偶者の手当と子供の手当とかかわっているのですが、意見として出されていたのは、全国レベルの水準と、東京都。","respondent":"黒田人事課長","answer":"扶養手当につきましては、今回改正が行われる趣旨としまして、国のほうで制度改正がされたということで、平成２８年勧告において特別区の実態を把握して、どうするかということで検討がなされて、今回勧告が出されたものでございまして、各区ごとに設定するということではなくて。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４０時間労働において、プラス２０時間、合わせて週６０時間が限度ではないか、それを超えると体調に異常を来すということも言われている中で、品川区はやはり長時間労働の部署がかなりあるといったことで、ここにはいろいろ方策に努めるように、休暇がとれるようにと書かれていますけれども、ぜひここを具体的に改善をしていただきたいと思うのですが。","respondent":"黒田人事課長","answer":"いわゆる長時間労働慣行の見直しのことにつきましては、当然、その年によっていろいろ事業の量が異なりますし、年次によって急に発生するもの、緊急な対応が必要なものであったりというものがありますので、なかなかそこの部分を、職員の採用というのは何十年単位で見ていって。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"それが正しい、きちんとした要求かどうかはちょっとわかりませんけれども、やはり仕事に見合った人員を配置するという考えでやられていると思うのですが、でも、現実的に大幅に健康状態に悪影響を及ぼすほどの残業を行っている部署と人がいるということ自体は、やはりしっかり認めていかないといけないと思うのですが、この点はいかがでしょうか。","respondent":"黒田人事課長","answer":"当然、仕事量に見合った配置ということで、所要人員については係単位での仕事も、いわゆる積み上げ等で見ていく中では、当然その組織の中で職員が応援できないかとか、いろいろな観点で、まず今ある事業量を見直しするというところがありますし。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後にしますけれども、仕事量の見直しとか、さまざまな手立て、もちろんいろいろやられると思うのですが、その中に、やはり必要なところには人を増やす、私はこれが欠けてはだめだと思うんですね。だから、ぜひ仕事量に合った人員、いろいろ工夫をした上でも仕事量に合った人の配置をしていくという姿勢を持っていただきたいのですが、最後ですので、いかがでしょうか。","respondent":"黒田人事課長","answer":"必要なところに人員を配置するというのは、これまでもやっておりますし、今後もやっていきますので、そういったところで常に見直しを図ってまいりたいと考えています。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"改めてしげしげとこの勧告の内容を、今見ていたのですけれども、わりと給与に関する勧告とか、それから、具体的な、例えば２ページ目の、新たな人事・給与制度の構築というあたりは、わりと明確なので、この勧告のとおり従うか従わないかというのが明確で、後の点検などもしやすいと思うのですけれども、今、飯沼委員からもありましたけれども、この勤務環境の整備とか、それから、ちょっと戻りますけれども。","respondent":"黒田人事課長","answer":"例えば、勧告内容ですと、給料表につきましては当然その勧告給料表ということで、新しい給料表が示されておりますので、これを妥結後に、条例を作成した後に、議会でご審議いただいた上で決めていくということになりますが、今、ご指摘のあった例えば障害者採用につきましては。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"だから、例えばその任命権者と検討というのはその辺が必要なのではないかと思うのですが、それは制度ができてからだと実際はなかなか運用が厳しいかなと思うのです。その辺をこの勧告に従って、今どれくらいまで検討されているのか、それから、今後その制度ができることを見越してどういう検討を進められていくのか、もしお考えがあったら教えてください。","respondent":"黒田人事課長","answer":"採用制度につきましては、特別区共通の制度ですので、品川区だけということで実施できるものではございませんが、例えば、先ほど申し上げたとおり、現在やっております身体障害者を対象とする特別区職員採用選考も、III類事務という位置づけで。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、その辺を、２３区の問題だから品川区で勝手に決められないのは承知の上ですが、やはり現場のほうからもこういう制度をつくっていくというところでは、意見を言うような場などがきっとあると思いますので、その辺はぜひいい方向で主張していただきたいというのが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-02","title":"元なぎさ通り道路整備工事（３－２区間）請負契約","agenda":"元なぎさ通り道路整備工事（３－２区間）請負契約","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"それはさまざまな、いわゆる老朽化も含めて、理由があるのかなと思うのですけれども、道路の工事は、道路本体の工事、例えば舗装するだけだったら２回、３回にわけてやらなくても済むかと思うのですけれども、例えば地中に埋められているものの工事になると、電気をやって、１回埋め戻して、また水道をやって、という繰り返しになる工事もあるかと思うのですが、やはり区民の方々からは、工事をやって。","respondent":"立川経理課長","answer":"ただいまいただいたご意見につきましては、工事所管課に伝えてまいります。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほどちょっと見てきました。もうきれいな道で、ほかの自治体では、ほんとうにここまで整備されているところというのはなかなかないのですが、これもやはりオリパラを１つの契機とした、幹線道路整備の一環なのでしょうか。生垣もきちんとつくって、一応工事はこれからやるのでしょうけれども、事故のないようにやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"意見","question":"１つには３ページの辞退をされた業者の辞退理由と、あと、落札したところとそれ以外のところの金額の違いというのはどういうところにあるのかなというのが、内容的にわかるのかどうか。４ページのところに工事内容が書かれていますよね。この内容自体は、区のほうでこういった中身でという指定が行われるものなのか、事業者が設計した中身なのか、ちょっとそれも。","respondent":"立川経理課長","answer":"第１点目、辞退理由ですが、配置技術者の調整がつかなかったという都合です。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"ざっくり割り返すと３万円ぐらいなのですが、費用というのはこんなものなのか、あと、どういうときにこの工事が行われるのか、どういう段階になったときにこの工事が行われるのか、あと、この１回の工事が終わるとここはどのくらいもつのかというあたりも、わかったら教えてください。","respondent":"立川経理課長","answer":"金額について精査されているかというご質問ですが、こちらにつきましては項目ごとに金額を出してもらっておりますので精査されていると認識しております。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"なぜそういうことを伺うかというと、実は、生活者ネットワークに、この低木の植栽についてのご意見がすごく来るのです。区民の方たちに、私たちはよく叱られるのです。手がかけられないのだったら、そんな手のかかるものを選ぶべきではないのではないかというご意見もあって、その辺をどこでどういうふうに判断をしていらっしゃるのか、教えていただきたいです。","respondent":"立川経理課長","answer":"事前に所管のほうに確認したところ、ハナミズキにつきましては住民アンケートで選定されたです。それから、オオムラサキツツジにつきましては、道路の植栽では一般的に使われているということで、これが採用されたということで聞いております。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"それは多分ここでは難しいなと思いつつ、もうこの内容で発注したということだったので伺ったのですが、その辺のことは、では今後やはりそういうご意見というのはそちらのほうにつないで、そうするとこれが変わっていくかもしれないというふうに考えてよろしいでしょうか。もし何かあれば。","respondent":"立川経理課長","answer":"こちらの要望については、各所管のほうにお伝えいただければと思います。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"意見","question":"１つだけ、済みません。特に異論はないのですけれども、予定価格が１億円余で、この入札金額が９,０００万円というところで、ほかの２社については１回目に１００％近い金額で出していて、落札業者はそれらの１割ぐらい低い価格で出されているのですが、最低制限価格は幾らだったのか、もちろんかかっていないからこうして落札されたと思うのですけれども、これについてもし答えられれば。","respondent":"立川経理課長","answer":"最低制限価格につきましては、未公表ですので、この場でお話しすることはできませんが、当然、最低制限価格を実施している工事です。","id":"exchange-025"}]},{"id":"topic-03","title":"天王洲公園管理事務所増築工事請負契約","agenda":"天王洲公園管理事務所増築工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"それで、次にこちらの管理事務所ですけれども、これは地上２階建て、鉄筋コンクリートというと、よくある工事なので、金額的にも比較的わかりやすいのでちょっとお聞きしたいのですが、１億４,５００万円程度かかるのですが、例えば２階などはほとんどがらんどう、１階もそんなに特別に設備もないのですが、民間の建築物などと比較すると随分額がかかっているなと、入札予定価格が高いなと思うのですが。","respondent":"立川経理課長、小林施設整備課長","answer":"で、予定価格というのは国、東京都の積算単価を用いまして妥当な価格ということで出していますので、その金額に落札価格が近づくということは事業者の見積もりとしても妥当と認識しています。そういう部分も、大きな公園ですけれども、使用しながら、いながら工事ということで必要最低限の狭いところでの工事という特殊な状況であるというのはあります。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、仮設でそういう事務所を継続できるようにつくっておいて、工事を同時に進めるということでこういう金額になっているということでよろしいのでしょうか。もう一度、いいですか。","respondent":"小林施設整備課長","answer":"いわゆる特殊な建物だということで認識してもらえればいいと思います。","id":"exchange-027"},{"speaker":"須貝委員","kind":"確認","question":"済みません。２階建てで、場所が水辺に近いということで、それで杭を２階建てでもやるということなのですね。普通、２階や３階だとベタ基礎のままではないですか。それが、やはりそういう事情があって、地盤沈下云々があるから、そういうふうにやらざるを得ないということですね。ちょっと確認だけ。","respondent":"小林施設整備課長","answer":"そのとおりです。水辺なものですから、地質を調査した段階では杭が必要だというところです。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"この工事は、管理事務所増築工事とあって、図を見ると横に長い１棟が建っています。ここにプラス新しく建てるという理解でいいのですよね。この増築の目的と、あと、上のほうの図の右に、女子更衣室・トイレについては、既存棟を改修し、整備する、と書かれているのですが、ここの既存棟の改修というのは、今後いつ行われるのか教えてください。","respondent":"小林施設整備課長","answer":"今の既存の事務所は、先ほどもお話ししましたけれども、施設を利用しながらということで、更衣室関係とかそういうのがなくなると結果的には仮設だとかそういうのをつくりますので、今現在の事務所棟と更衣室関係をそのまま生かしながら、ただ。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"７ページに戻るのですが、３社が辞退というので、済みませんが辞退の理由を教えていただきたいのと、辞退というのはどの時点で出されるのか、入札金額を一応出された後に辞退するのか、ちょっと辞退の時期がどういう流れで出てくるのか教えてください。","respondent":"立川経理課長","answer":"辞退の時期ですが、まず入札公告というものを出しまして、それでその後、詳細図面等を確認しまして、そこで検討を開始するですので、実際の辞退の時期ですが、入札日の直前であったり、１日前であったり、そういった時期です。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"辞退の理由はいろいろだと思うのですが、結構こういう辞退というのはあるのでしょうか。３社も辞退しているので、その辺の状況を教えて下さい。","respondent":"立川経理課長","answer":"事業者としましては、詳細図面、工程表等を見ないと、やはりこの工事をとりに行くかということは決められないということがありますので、申し込み後の辞退というのは、ここ最近の人手不足であるとか、そういったことも影響いたしまして、以前よりは増えていると認識しています。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"先ほどの杭打ちをするということも含まれているのですが、こういった建物を請け負える力量のある事業所というのは、品川区内にどのくらいあるのですか。そんなに大規模ではないところは、主に区内の事業所さんにお仕事が回るといいなと思っているのですが、どの程度あるのでしょうか。","respondent":"立川経理課長","answer":"ただ、学校の建築だとか、ああいった大規模な工事につきましては、いわゆるＪＶで実施していますけれども、そういったものについてはいわゆるゼネコンというところにトップになっていただいて、区内の事業者を絡めて実施しているものです。","id":"exchange-032"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけなのですけれども、先ほど水辺のところだからしっかりと杭を打ってその建物を丈夫にしておいて、何かあったときの対応ということだと思うのですが、ここはシャワー室もあるではないですか。","respondent":"小林施設整備課長","answer":"そのとおりで、現在進めている設計については、給水も排水も耐震化の設計をしています。","id":"exchange-033"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ、例えば今回の東芝の例をとると、東芝さんに対して区は今までこうしてほしいという要望を出されていますよね。で、その東芝から今度その権利が継承されて、ほかの団体になるというときに、先ほど、そういった申し入れというのは引き続きしていくというようなお話でしたけれども、今まで区としていろいろな要望をして、区としてはそれを引き継いでもらいたいわけではないですか。","respondent":"柏原企画調整課長","answer":"あわせて、今後承継される予定のその事業者に対しても、こちら、区からも直接お話はしますし、それからもちろん東芝から、先ほどの事業者にもそういった旨での承継をしてくださいということで、東芝からもアプローチしてもらうという。","id":"exchange-034"},{"speaker":"石田（し）委員","kind":"意見","question":"委員長にお願いですけれども、これだけ数字がいっぱい出る報告をされるのに、当日資料もないと、我々としてももうどうしたものかなというのがあるので、できたらそういったものに関しては、できる限り、事前は無理かもしれないので、当日の資料でも構わないので、できたらいただければと思いますので、それは委員長のほうにお願いさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前回の都議会議員選挙の折に、１８歳選挙権が始まったばかりで年齢別のところの投票率をお知らせいただいたのですが、今回初めての国政選挙なので、その辺をぜひ、お時間がかかるかもしれないのですけれども、お出しいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"あくつ副委員長","kind":"質問","question":"しながわ」とどういう関係性を持つのかというところと、どういうコンセプトでこれを公募されているのか、もしかしたら次の委員会等で報告があるのかもしれませんが、ちょっと期間も短いようだったので、改めてちょっとここで伺いたいと思いました。","respondent":"木村報道・プロモーション担当課長","answer":"しながわ」はもちろん今あるのですけれども、あと、先ほどのそれぞれの売り文句、商店街があるとか、交通の便がいいとか、そういうもの以外で何か品川を売るというかＰＲできるような、そういう素材、コピーはないだろうかというところで、大体。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/577253?Template=document&Id=2092#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":30029,"voices":113}},{"id":"h29-20171107-14","meetingId":"h29-cm11","date":"2017年11月7日","dateIso":"2017-11-07","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時１８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","topics":[{"id":"topic-01","title":"区有施設、公有地等活用に関すること","agenda":"区有施設、公有地等活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと質問ですけれども、具体的な資料の内容で何点かお伺いしたいのですが、まず３３ページですか。地域センターについて、地域の拠点として強化が求められる機能。ですから、きちんとニーズを把握して、むしろ活動を促すためには、枠は増やすべきところは増やさないといけないのではないかと思うのですけれども、そこら辺はどういうふうになっているのかお伺いしたいというのが１点です。","respondent":"柏原企画調整課長","answer":"児童センターのほうは、もちろん多世代で交流するというのもあるのですが、ゆうゆうプラザをそこでつくるというよりは、今子育てのところで、ネウボラの相談というのを拡充したいという思いもありますし。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"安心いたしました。けれども、５月１６日の行革委員会の議論で、私が質問したところで民営化をバラ色に描き過ぎているのではないですかということでお伺いしたところ、課長は委託した部分は民にお任せをして、そうでない部分に対して区がもっと力を入れなくてはいけないところについては、区のほうで直営で力を入れると。選択と集中で集中するほうは何なのかというのをお伺いしたいというふうに思います。","respondent":"柏原企画調整課長","answer":"それはそれぞれの事業を見直しながら検討すると。民のほうにお願いできればお願いをしていくという中身です。それ以外で各セクションで課題を持っていたりとか解決しなくてはいけない問題。それはやはり区で職員がやらなくてはいけない部分。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"そうなのですか。今考えをうかがったのですが、例えばこの冊子の１０ページに、施設分類ごとの管理運営形態ということでこういうふうに資料が出ているのですけれども、住宅系は８９.７％が指定管理者ですから民営化していると。少しお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"その中に例えば今お話があった子育て支援施設といったところでも、いろいろな施設が含まれておりますので、保育園、児童センター、その他の施設が入っていますから、これで全部が委託だとか全部が直営だとかいう議論を行うつもりではなく。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"５園からと。１つは、財政負担をかなり強調していらっしゃいますが、そこはどうなのかなという点でまず１点お伺いしたいのが、まず前回も示したのですけれども、３０年間で見るとこれまでの施設経費に要した実績というのは５４.９億円なのですが、これが将来は８０.８億円になるから大変だというふうにおっしゃっていますが、これはそもそも１０年計画ですよね。伺いたいと思います。","respondent":"柏原企画調整課長","answer":"今委員から１０年間でというところのお話がありましたけれども、例えば２５ページのグラフ等をご覧いただくと、現在の延床面積をそのまま維持するということを考えたときに、直近の１０年間だけでもこのぐらいの大規模改修であったり施設の更新が想定されるわけです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"一方で、もう浪費のように莫大な税金を、しかも一旦建てたら３０年５０年とありましたけれども、それは再開発マンションも同じでどうするのですかという話なのです。将来にわたって人口を増やす考えや政策というのは、区は持たないのですかというのを伺いたいと思います。そういう施策はないのですか。さっきの質問とあわせて、人口増やす考えは持たないのですかということを答えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"ありますけれども、ただそれだけでいいのですかという話なのです。私が伺ったのは、品川区としては、将来にわたり人口を増やす考えや政策を持たないのですか。諦めているのですか。今般、各委員会で行政視察にも行きましたけれども、地方の自治体というのは、本当にいかに自分たちの町に住み続けてもらう人を増やすかということで、血眼になってやっているわけではないですか。いかがでしょうか。","respondent":"柏原企画調整課長","answer":"平成２５年に改訂いたしましたけれども、そういった中でも人口を増やしたりであるとか、子育て世帯への充実であったりとか、定住していただくとかそういった施策を充実させるべく、長期基本計画も改定しているということでございまして、今委員がおっしゃった内容につきましては。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"当委員会でも、人口動向についての調査事項もありますので、私はそうした品川区が将来にわたり持続可能なそうした施策をつくっていく。そういうところこそが大事だと考えていますので、ぜひそこら辺は提言もしながら充実していきたいし、していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"ないし、改築していくというのが喫緊の課題。いわゆる６０年の寿命が過ぎているわけです。もしくは当然必要になると思うのは、同等施設が近隣にあった場合は、たかだか２３平方キロしかないところですから、これはもう合併していくなり、統合していくなりというのは当然これから先必要なことであって、それは今ではないかもしれないけれども、そこを視野に入れて、これからは区の行政施設。","respondent":"柏原企画調整課長","answer":"実は言葉としては、２７、２８ページに全体方針を記載させていただいているのですけれども、２８ページのところに、大きな５つの柱の中で、(3)の部分で、表題の中にも転用というところで入れさせていただいています。それから、(2)の文章の中でも用途転用。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"１０年後どうなるかというのも本当にわからないと思うのですけれども、建物というのは、どんどん年々劣化していきますから、それに準じて毎年ある程度計画性を持って、区の行政施設の更新は進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問","question":"すみません。３３ページ、まずそこから聞いていきたいのですけれども、総合庁舎の部分。マネジメントの方向性というところで、地域センターについて、町会・自治会の活動の促進と高齢者の支援などと書いてありますけれども、子育てですとか障害をお持ちの方々、そういった部分については、どのようにお考えでしょうか。お願いいたします。","respondent":"柏原企画調整課長","answer":"どなたでもどういった形でも利用できるというのが一番理想的な形ではあります。ただ施設が古かったりとか、ハード的な制約というのはありますけれども、そういったどなたでも使えるような形でということでの検討は当然ながらしていかなくてはいけないというふうに思っています。","id":"exchange-010"},{"speaker":"横山委員","kind":"質問・要望","question":"例えばダンスですとか、室内で運動されるという方が最近大変増えているということで区民の方からお声をいただいておりますが、なかなか利用がしづらいということで、予約率と利用率といいますか、予約で先に押さえられていても実際使われていないのではないかというようなお声も入っておりまして、実際の使用の利用率だけではなくて、予約率と利用率みたいなところでしょうか、当日の利用の状況等含めて。","respondent":"柏原企画調整課長","answer":"ここは、料金とそういったところの関係にもつながってくる部分ではあるのですが、その辺の考え方をいろいろな施設でどうするべきかというのを考えているのですが、我々企画部門としてもそれをトータルに横断的に検討といったところの中でもそういった課題については。","id":"exchange-011"},{"speaker":"横山委員","kind":"意見","question":"そういったところを品川区全体として見ていただくというそういう視点も、この計画の中に今後いろいろ入れていただくとよろしいのかなと思いますので、ぜひ検討を進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"なぜならこれは出生率が減っているわけですから、減っていくのは当たり前の話で。少しお伺いをしたいのですけれども、先ほどシルバーセンターについては建替え・大規模改修のタイミングで高齢者多世代交流支援施設ゆうゆうプラザへの転換について検討しますと。こういうことも考えながら、そういう考えをぜひ入れていただきたいなと思うのですけれども、その辺についてのお考えを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"もちろん個々の状況によりますので、それは状況を見ながらということでありますけれども、今お話しいただいた施設の捉え方というのは、十分区も考えながら進めていきたいというふうに思います。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"年当たり平均で２５.９億円のコスト増というところで、この財源についてなのですけれども、基本的に区の単費でどこまで負担するという見通しというか、もちろんいろいろな補助金とかを当て込んでいくものはどんどん当て込んでいくのだという姿勢だというのは理解していますが、その辺の中で区の単費というものをどのぐらい見込んでいるのか、わかる範囲で結構なのですが、教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"なかなか区の単費でどのぐらいかというのは難しいところでありまして、具体的な数字としては、何％とかいうのが申し上げづらい部分はあります。ただ、なるべく負担を減らすような方向での捉え方。補助金であったり特定財源です。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。認識が違っていたらそれは指摘していただきたいのですけれども、この維持管理とか修繕・更新。この辺の年８０.８億円の割合というと、維持管理がどのぐらいかかっているのかとかそういうところについても、もしわかれば教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"何パーセントとかというところが手持ちにないものですから、確認させていただければと思います。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"それで少し違う視点なのですけれども、今回の計画を見する中で、一番大きなネックといいますか、特にここ１０年ぐらいのこの計画の中では、学校教育施設の延床面積が一番大きくて、しかも１９６０年前後に建てられているものがまだまだたくさん残っていて、１つの改修にすごくお金もかかりますし、今オリンピック前でここ一、二年は非常に建築資材、人件費等が高くなっているというところもあるし。","respondent":"柏原企画調整課長","answer":"捉え方としますと、この公共施設等総合計画の簡易計画とまでは言いませんけれども、個別の具体の部分をちょうどその学事制度審議会で施設のことも検討しているというところがありますので、個別計画という意味合いで捉えています。","id":"exchange-016"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。タイミングの問題というところで、いたし方ないところもあるかと思いますので、最終的にはしっかりとした整合性というか、それぞれの位置づけにおいて適切な表現というところでお願いしたいと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問","question":"ちょうどこれ今ページで言うと２７、２８ページに基本方針があって、ここでもさっき渡部委員が指摘したように、単に管理ではなくてということで、いろいろな手法も書かれている。何を伺いたいかというと、今コストは確かにかかると。延床面積を広げたい。その辺の単に費用対効果ではなくて、大幅なプラスの面というのですか。どこでどのように算定をして想定をして加味していくのか、教えてください。","respondent":"柏原企画調整課長","answer":"今も捉えられる範囲の数字では検証であるとか、今までも検討はしているのですけれども、今後新公会計制度が導入されたときに、そのデータ化というところがある程度見える化ができる部分があります。","id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問","question":"当然考えているはずなのですよ。今既存の施設、学校改築も含めて新しい施設はどう考えても評判いいのですよ。すごく広さの点から、あるいは各機能。誰もが感心する。そういう意見です。それは小さな機能でもいいわけですから、そういういい意味でのシミュレーションはどんどんしていくべきかなと。タイミングの話なので、ぜひとも検討いただければと思いますが、最後そのコメントをいただいて終わりにします。","respondent":"柏原企画調整課長","answer":"ご指摘いただいた部分です。こちらにつきましては、それぞれの施設のいろいろなありようもありますけれども、今、メニューというお言葉もいただきましたが、そういった形でどうできるかというのは検討させていただきたいと思ってあります。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、利用率が低いところは絞っていくというか、そういうふうな方向があるのかなというふうにも見えるのですけれども、この利用率があまりよくないところはどうしていこうかというのは、今に始まった話ではなくて数年前からある話だと思うのですが、こうした地域の支え合いをつくるためにも必要な集う場所というのを利用率で絞っていくという。","respondent":"柏原企画調整課長","answer":"その利用率によっては、例えば別の機能もあわせて複合化するであるとか、別の近くの施設との関係でどうするかとか、そういう議論には当然なると思います。利用率だけでということではありませんけれども、利用率は当然見なくてはいけない指標だというふうに思ってあります。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この利用率をどうやって上げていくのかという方向を向いたほうがいいだろうなと私は思います。無料でということで安心して使える施設を、やはり振興に資する施設として進めていっていただきたいなと。そして安心して使える方向で考えていっていただきたいと思いますけれども、その辺は有料にしていってしまうという、これがスポーツ振興なのかというのをお伺いしたいのですが。","respondent":"柏原企画調整課長","answer":"ということで、その部分に対して区の税金で施設を整備したわけですので、使われる方、利用の目的のある方に対して一定の利用料といいますか、使用料といいますか。取るのは１つ考え方としては、当然といいますか、１つあるのだと思います。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"前回の議論のところでスポーツ振興というところの話の中で、スケートボード場が出されたので、そうは言っても有料ではないかと私は思ったもので、聞かせていただきました。そういうことではないというようなお話だったと思うのですけれども、子育て支援の視点でということだったのですが、これはシルバーセンターと合築していくということではないということでよろしいですか。","respondent":"柏原企画調整課長","answer":"具体的にどの施設と合築するかどうかというところは、ここの計画でそれを言っているというところではなくて、ここの方向性としては建て替えであったりとか、施設のほうの更新の時期のタイミングを見て、さまざまな機能。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで過去３０年は５４.９億円だったと。それから今後３０年間は８０.８億円。やはり建て替えとか更新、改修というのは必要なので、そのコストというのを見ていくのは大事だと思うのですけれども、だから財源が不足すると見込まれるというこの表現はなくてもいいのではないかなというぐらい、品川区の健全財政と言われている潤沢すぎるほどあるというふうに思うのですが、そこら辺はいかがでしょうか。","respondent":"柏原企画調整課長","answer":"先ほどもご議論のあったところですけれども、施設の計画というのはこの先３０年４０年も含めた形での計画ということで、これは検討させていただいたものです。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"３０年４０年５０年と、それだけ先になってくれば、そうはいっても見通しは大事ですけれども、実際のところはわからないわけですよね。３０年前もこの間過去３０年ということで見立てていましたけれども、過去３０年と今というのも大分違ってきていますよね。それをやはり子どもを産み育てる、増やせるというところにつなげていくべきではないかなと思うのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"人口のお話ですけれども、これは先ほどもご議論ありましたが、国全体での人口が今減っているという状況はまず我々は認識しなくてはいけないというところです。日本の中での人口が動いている状態で品川区に人口が増えているという現象だということです。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、人口がこれから全体的に減っていくということなのですけれども、やはり全体的に増やしていくというふうに国にも求めていっていただきたいなと思いますし、品川区からもどんどん進めていかなければいけないところではないかなと。ですので、やはりさらに充実をさせていくという、そのためにはどうしていくかという計画をぜひ立てていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"委員長にお願いがあるのですが、この質疑の時間。ある一定の時間で委員長の判断で仕切っていただきたいと私思っております。すみません。児童センターについて、お伺いをしたいと思います。時期が古い、年数がたっている、劣化しているところからまず最初にてこ入れするのか、あと地域の要望とか、そういうのも含めた話でそういった改修をやるのかどうか。その１点だけお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"基本的には委員おっしゃっていただいたようにまず時期といいますか、劣化・老朽の状態によってやるというのがまず基本にはなってくるとは思いますけれども、例えばほかの施設との関係で、いろいろな機能を充実させたりとか別のところにとかという。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"すみません。私は１６ページの公園についてなのですけれども、開設から３０年を超えている公園が約５割、５０％ということで、この健全度調査というのは、例えば椅子とかトイレとか手洗い場とか、樹木も含まれるのかわかりませんけれども、どういったところを調査して、健全度というのを決められているのか、その辺について伺いたいと思います。","respondent":"柏原企画調整課長","answer":"それから例えば地盤であったりとかその老朽度とか、そういったところも含めてトータルで健全度の判定というところで、例えばＤ判定が出ているようなものは全体的に顕著な劣化があるであるとか、事故につながるおそれがある設備があるだとか、緊急の補修が必要だとか。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問・要望","question":"今品川区で公園の利用率というのを多分把握されていると思うのですが、全然使われていないというところも、１日１人か２人ぐらいのところもあるし、ほとんど使われていない公園というのがあるのですが、そうした公園というのは、今後どのように転用というか、今求められている例えば保育施設とかそうした部分も考えていかなければいけないのではないかと思うのですが。","respondent":"柏原企画調整課長","answer":"ただ、利用が無くなったからいきなり違うものにというのが、地元の方のご意見であったりとか、今も申し上げましたけれども、全体の例えば緑化率であったり、いろいろなところに影響してきますので、防災とかいろいろな面も含めてどう捉えるべきかというのは。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"一方区民の声は、全体で見ると約６割以上、６割強というのですか。ある意味で区のいわゆるこの計画をつくられた側の姿勢と、それから区民の思いというのが逆というのですか、ある意味で矛盾しているというのか。そういう計画になっているのかなと思うのですけれども、ここら辺の課題については、今後どういうふうに進められるかというのは聞いておきたいと思います。","respondent":"柏原企画調整課長","answer":"これは以前の有効活用プランでは、この考え方は表にあまり強くは出していなかったのですが、今回はつくるべきところはつくるというような考えに立っておりますので、適正化の話と相反する部分は出る可能性はあるのですけれども。","id":"exchange-029"},{"speaker":"若林委員","kind":"質問・要望","question":"一方で、区民もそうだけれども、区役所の庁内も計画をつくられた方のほうが、いわゆるバランスをとりながら１０年３０年５０年先を見据えて計画を財政的な部分を含めて立てられたわけだけれども、個々の所管にあってはうちの所管の施設を少なくしたり、いわゆる適正化をするということに対しては、「はいそうですか」というふうには当然ならないし、またそうならないのがいわゆる行政現場を預かっている方々。","respondent":"柏原企画調整課長","answer":"そしゃくしながら必要な施設のありようであるとか、そういったところを研究しながら実際具体にお使いになっている方々とのやりとりの場面、それから地域の方々、そういったところをどうやって進めていくかというのは、まさに所管と我々がきちんと進めて。","id":"exchange-030"},{"speaker":"若林委員","kind":"意見","question":"今学事制度審議会という、いわゆる個別計画という位置づけで、今後いわゆる個別の計画というのは、どういう分野でどの程度つくられるかだけお示しいただいて終わりにしたいと思います。","respondent":"柏原企画調整課長","answer":"今具体で動いていますというのは、お話ししましたとおり学事制度審議会が同様の検討という形になりますので、それがまず１つです。それから今申し上げた住宅部門は長寿命化の計画、今更新中で、変更をかけていますので、それが個別の計画になります。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"すみません。先ほどの意見の中で言うべきだったのか、少し迷ったのですけれども、こちらのその他で言わせていただけたらと思います。委員長にお伝えしたいのですけれども、委員会の運営のあり方ですとか、進行の仕方というところをどのように考えていらっしゃるのか、今一度教えていただきたいなと思うところがありまして、要望をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"委員長がどう考えているかということでのご意見をいただきましたので、委員長としての私の意見を述べさせていただきたいと思いますけれども、この委員会というのは、委員がそれぞれ事前に資料をいただいて、それに対して自分と区民の意見を述べるという事で、背景に区民の意見があるわけですよね。そして、それがきちんと保障されなければならないというふうに思います。よろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問","question":"今の委員長のご発言まさにそのとおりだと思いますので、そこに関しましては、しっかりと私どももわかっているつもりでお話を本日しています。ただ、特定の委員の発言が全て繰り返しの発言になっておりまして、それが１度や２度ではなかったと本日多分ほかの委員も承知をしているのではないかと思います。答えは結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/788161?Template=document&Id=6038#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":44879,"voices":72}},{"id":"h29-20171108-18","meetingId":"h29-cm11","date":"2017年11月8日","dateIso":"2017-11-08","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時３６分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"１点だけですけれども、要望書の２番のところ、都庁でもあえて質問したのですけれども、「大会後の区民の利用に資する公園内施設として」の文章の後ろのほうに、要はレガシーの観点からオリンピックという表現を名称に入れて、後世に残してほしいということを文言に加えていただければと思います。文言は全て正副にお任せいたします。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"たけうち委員","kind":"意見","question":"文言の追加ではないのですけれども、３番のところでクラブハウスという表現になっているのですけれども、先ほど都から頂いた資料だとスポーツセンター管理棟という表現になっているので、その中のクラブハウスというイメージなのかなと思います。その辺の文言整理はお任せしたいと思いますけれども、検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"意見","question":"１番と２番のところに多機能トイレと書いてあるのですけれども、俗に言うこれは「誰でもトイレ」という言い方かちょっとわからないけれども、よく「誰でもトイレ」を一番耳にする言葉なので、例えば多機能トイレの後ろに括弧して「誰でもトイレ」と入れてもいいのかななんて思いましたので、それも正副にお任せしますのでよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"「誰でもトイレ」と考えて当初は要望書を作成していましたが福祉関係の部署に確認しましたら、多機能トイレの方が広い意味になるのではないかということでした。例えば新幹線のホームに行ったときに、新幹線では「誰でもトイレ」という名称を使っていないで、そちらのほうがいいのかなということで表現を変更いたしました。","respondent":"木村委員長","answer":"つきましては当要望書は、１１月を目途に東京都へ提出できればと考えています。修正後の案文につきましては、作成でき次第、各委員にお渡しをいたします。なお、今後ですが、私のほうで１１月２２日に予定されております議会運営委員会に出席し、内容を説明してまいります。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/400453?Template=document&Id=6524#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":3065,"voices":12}},{"id":"h29-20171113-10","meetingId":"h29-cm11","date":"2017年11月13日","dateIso":"2017-11-13","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"議会報告会等準備会議からの報告事項","agenda":"議会報告会等準備会議からの報告事項","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"ちょっとこれと直接関係ないのですけれども、本日、ご案内かとは思いますが、第２回目の品川女子学院との意見交換会を、この議運の終了後、４時から品川女子学院で行わせていただきますので、また改めてご報告等させていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/560108?Template=document&Id=5250#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":4896,"voices":18}},{"id":"h29-20171122-10","meetingId":"h29-cm11","date":"2017年11月22日","dateIso":"2017-11-22","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"平成３０年第１回定例会の日程","agenda":"平成３０年第１回定例会の日程","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ。は委員長会を開かないと委員会日程が決まらないというのもわかっているのですけれども、その辺をもし検討ができることがあれば検討していただいて、混乱がないようにしていただければなというふうに思いますので、要望だけお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/560108?Template=document&Id=5252#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":8092,"voices":34}}]);
